('current', 18456, 40, 'Mỗi đêm lúc 02:00', '{\"1\": {\"name\": \"Khởi động\", \"level\": 1, \"totalSets\": 8, \"partCounts\": {\"all\": 8, \"Part 1\": 3, \"Part 2\": 3, \"Part 3\": 1, \"Part 4\": 1}, \"description\": \"Tỷ lệ làm sai thấp nhất (dưới 20%), phát âm rõ ràng, từ vựng quen thuộc\", \"totalSentences\": 567}, \"2\": {\"name\": \"Cơ bản\", \"level\": 2, \"totalSets\": 8, \"partCounts\": {\"all\": 8, \"Part 1\": 1, \"Part 2\": 2, \"Part 3\": 3, \"Part 4\": 2}, \"description\": \"Độ khó cơ bản, tốc độ nói vừa phải, phù hợp để xây dựng phản xạ\", \"totalSentences\": 760}, \"3\": {\"name\": \"Vững vàng\", \"level\": 3, \"totalSets\": 8, \"partCounts\": {\"all\": 8, \"Part 1\": 2, \"Part 2\": 2, \"Part 3\": 2, \"Part 4\": 2}, \"description\": \"Độ khó trung bình, xuất hiện ngữ điệu tự nhiên và một số bẫy phổ biến\", \"totalSentences\": 658}, \"4\": {\"name\": \"Thử thách\", \"level\": 4, \"totalSets\": 8, \"partCounts\": {\"all\": 8, \"Part 1\": 1, \"Part 2\": 2, \"Part 3\": 3, \"Part 4\": 2}, \"description\": \"Thử thách với tốc độ nói nhanh, nối âm thực tế và từ vựng mở rộng\", \"totalSentences\": 777}, \"5\": {\"name\": \"Cực khó\", \"level\": 5, \"totalSets\": 8, \"partCounts\": {\"all\": 8, \"Part 1\": 3, \"Part 2\": 1, \"Part 3\": 1, \"Part 4\": 3}, \"description\": \"Tỷ lệ làm sai cao nhất, nhiều bẫy suy luận, tốc độ nói nhanh và đa dạng ngữ điệu\", \"totalSentences\": 517}}', '2026-09-15 07:20:32', '2026-09-12 19:38:45', '2026-09-15 07:20:32')
