('set-2026-t10-p2-s5', 'set-2026-t10-p2', 5, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/8.mp3', NULL, NULL, 2.014e0, 4.116e0, 'Why don\'t you ask Ms. Kim for help?', '[{\"end\": 2.174, \"word\": \"Why\", \"score\": 0.933, \"start\": 2.014, \"posTag\": \"SCONJ\"}, {\"end\": 2.434, \"word\": \"don\'t\", \"score\": 0.728, \"start\": 2.234, \"posTag\": \"AUX\"}, {\"end\": 2.614, \"word\": \"you\", \"score\": 0.671, \"start\": 2.474, \"posTag\": \"PRON\"}, {\"end\": 2.935, \"word\": \"ask\", \"score\": 0.999, \"start\": 2.754, \"posTag\": \"VERB\"}, {\"end\": 3.255, \"word\": \"Ms.\", \"score\": 0.7, \"start\": 3.015, \"posTag\": \"PROPN\"}, {\"end\": 3.575, \"word\": \"Kim\", \"score\": 0.917, \"start\": 3.295, \"posTag\": \"PROPN\"}, {\"end\": 3.776, \"word\": \"for\", \"score\": 0.887, \"start\": 3.636, \"posTag\": \"ADP\"}, {\"end\": 4.116, \"word\": \"help?\", \"score\": 0.799, \"start\": 3.816, \"posTag\": \"NOUN\"}]', '[\"Kim\"]', '', 'waɪ doʊnt juː æsk ɛmɛs kɪm fɔːɹ hɛlp', '[\"Lịch khám nha khoa của bạn là vào thứ Ba tuần tới phải không?\", \"Khoảng 20 mét.\", \"Một ít nước đã đọng lại trên lối đi.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 5 trong bài luyện nghe Part 2.\", \"display_text\": \"Why don\'t you ask Ms. Kim for help?\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s6', 'set-2026-t10-p2', 6, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/8.mp3', NULL, NULL, 6.159e0, 7.941e0, 'Because she\'s on a conference call.', '[{\"end\": 6.599, \"word\": \"Because\", \"score\": 0.857, \"start\": 6.159, \"posTag\": \"SCONJ\"}, {\"end\": 6.9, \"word\": \"she\'s\", \"score\": 0.794, \"start\": 6.699, \"posTag\": \"PRON\"}, {\"end\": 7.04, \"word\": \"on\", \"score\": 0.803, \"start\": 6.96, \"posTag\": \"ADP\"}, {\"end\": 7.12, \"word\": \"a\", \"score\": 0.505, \"start\": 7.08, \"posTag\": \"DET\"}, {\"end\": 7.601, \"word\": \"conference\", \"score\": 0.923, \"start\": 7.18, \"posTag\": \"NOUN\"}, {\"end\": 7.941, \"word\": \"call.\", \"score\": 0.871, \"start\": 7.641, \"posTag\": \"NOUN\"}]', '[\"conference\"]', '', 'bɪkʌz ʃiːz ɔn ɐ kɑːnfɹəns kɔːl', '[\"Vé xem buổi hòa nhạc tối thứ Sáu có giá 10 đô la một vé.\", \"Cứ thong thả suy nghĩ xem bạn muốn chọn cái nào.\", \"Bạn chắc chắn sẽ thu hút được rất nhiều khách vãng lai.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 6 trong bài luyện nghe Part 2.\", \"display_text\": \"Because she\'s on a conference call.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s7', 'set-2026-t10-p2', 7, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/8.mp3', NULL, NULL, 9.903e0, 11.626e0, 'There\'s no more paper in the cabinet.', '[{\"end\": 10.124, \"word\": \"There\'s\", \"score\": 0.897, \"start\": 9.903, \"posTag\": \"PRON\"}, {\"end\": 10.304, \"word\": \"no\", \"score\": 0.99, \"start\": 10.184, \"posTag\": \"DET\"}, {\"end\": 10.524, \"word\": \"more\", \"score\": 0.836, \"start\": 10.344, \"posTag\": \"ADJ\"}, {\"end\": 10.905, \"word\": \"paper\", \"score\": 0.841, \"start\": 10.564, \"posTag\": \"NOUN\"}, {\"end\": 11.005, \"word\": \"in\", \"score\": 0.753, \"start\": 10.945, \"posTag\": \"ADP\"}, {\"end\": 11.125, \"word\": \"the\", \"score\": 0.832, \"start\": 11.045, \"posTag\": \"DET\"}, {\"end\": 11.626, \"word\": \"cabinet.\", \"score\": 0.867, \"start\": 11.145, \"posTag\": \"NOUN\"}]', '[\"cabinet\"]', '', 'ðɛɹz noʊmɔːɹ peɪpɚɹ ɪnðə kæbᵻnət', '[\"Tôi không gặp bạn kể từ khi chúng ta cùng học lớp dành cho chủ doanh nghiệp năm ngoái.\", \"À, tôi cần sự giúp đỡ để gửi các thiệp mời.\", \"Tôi sẽ liên hệ với một số công ty để xin báo giá.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 7 trong bài luyện nghe Part 2.\", \"display_text\": \"There\'s no more paper in the cabinet.\"}', '2026-09-15 07:19:41')
