('set-2026-t10-p2-s8', 'set-2026-t10-p2', 8, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/8.mp3', NULL, NULL, 12.567e0, 14.93e0, 'I\'ve already seen that one.', '[{\"end\": 13.768, \"word\": \"I\'ve\", \"score\": 0.93, \"start\": 13.628, \"posTag\": \"PRON\"}, {\"end\": 14.129, \"word\": \"already\", \"score\": 0.876, \"start\": 13.808, \"posTag\": \"ADV\"}, {\"end\": 14.449, \"word\": \"seen\", \"score\": 0.796, \"start\": 14.209, \"posTag\": \"VERB\"}, {\"end\": 14.649, \"word\": \"that\", \"score\": 0.754, \"start\": 14.489, \"posTag\": \"DET\"}, {\"end\": 14.93, \"word\": \"one.\", \"score\": 0.956, \"start\": 14.81, \"posTag\": \"NUM\"}]', '[\"seen\"]', '', 'siː aɪv ɔːlɹɛdi siːn ðætwʌn', '[\"Cảm ơn các bạn đã dành thời gian gặp chúng tôi để bàn về khoản vay cho việc kinh doanh của mình.\", \"Trưởng phòng kế toán mới.\", \"Cách đây vài giờ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 8 trong bài luyện nghe Part 2.\", \"display_text\": \"I\'ve already seen that one.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s9', 'set-2026-t10-p2', 9, 3, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/9.mp3', NULL, NULL, 2.152e0, 5.233e0, 'Do you want to review the report together or on your own?', '[{\"end\": 2.252, \"word\": \"Do\", \"score\": 0.86, \"start\": 2.152, \"posTag\": \"AUX\"}, {\"end\": 2.432, \"word\": \"you\", \"score\": 0.886, \"start\": 2.312, \"posTag\": \"PRON\"}, {\"end\": 2.652, \"word\": \"want\", \"score\": 0.838, \"start\": 2.472, \"posTag\": \"VERB\"}, {\"end\": 2.792, \"word\": \"to\", \"score\": 0.617, \"start\": 2.692, \"posTag\": \"PART\"}, {\"end\": 3.172, \"word\": \"review\", \"score\": 0.937, \"start\": 2.852, \"posTag\": \"VERB\"}, {\"end\": 3.312, \"word\": \"the\", \"score\": 0.846, \"start\": 3.232, \"posTag\": \"DET\"}, {\"end\": 3.732, \"word\": \"report\", \"score\": 0.943, \"start\": 3.372, \"posTag\": \"NOUN\"}, {\"end\": 4.213, \"word\": \"together\", \"score\": 0.928, \"start\": 3.792, \"posTag\": \"ADV\"}, {\"end\": 4.533, \"word\": \"or\", \"score\": 0.824, \"start\": 4.433, \"posTag\": \"CCONJ\"}, {\"end\": 4.713, \"word\": \"on\", \"score\": 0.8, \"start\": 4.633, \"posTag\": \"ADP\"}, {\"end\": 4.933, \"word\": \"your\", \"score\": 0.868, \"start\": 4.753, \"posTag\": \"PRON\"}, {\"end\": 5.233, \"word\": \"own?\", \"score\": 0.911, \"start\": 5.053, \"posTag\": \"ADJ\"}]', '[\"want\", \"review\", \"report\"]', '', 'duː juː wɔnt tə ɹᵻvjuː ðə ɹᵻpɔːɹt təɡɛðɚ ɔːɹ ɔn jʊɹ oʊn', '[\"Cảm ơn vì đã đồng ý giúp tôi tổ chức bữa tối gây quỹ thường niên của thư viện nhé, Klaus.\", \"Nếu hỏi hành khách, tôi cá là họ sẽ bảo vị trí tiện lợi nhất là càng gần sân ga càng tốt.\", \"Natalie phụ trách phần đồ dùng.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 9 trong bài luyện nghe Part 2.\", \"display_text\": \"Do you want to review the report together or on your own?\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s10', 'set-2026-t10-p2', 10, 3, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/9.mp3', NULL, NULL, 7.254e0, 9.334e0, 'No, I don\'t need any more copies.', '[{\"end\": 7.494, \"word\": \"No,\", \"score\": 0.932, \"start\": 7.254, \"posTag\": \"INTJ\"}, {\"end\": 7.994, \"word\": \"I\", \"score\": 0.99, \"start\": 7.934, \"posTag\": \"PRON\"}, {\"end\": 8.234, \"word\": \"don\'t\", \"score\": 0.784, \"start\": 8.034, \"posTag\": \"AUX\"}, {\"end\": 8.494, \"word\": \"need\", \"score\": 0.883, \"start\": 8.294, \"posTag\": \"VERB\"}, {\"end\": 8.694, \"word\": \"any\", \"score\": 0.93, \"start\": 8.554, \"posTag\": \"DET\"}, {\"end\": 8.874, \"word\": \"more\", \"score\": 0.866, \"start\": 8.714, \"posTag\": \"ADJ\"}, {\"end\": 9.334, \"word\": \"copies.\", \"score\": 0.822, \"start\": 8.894, \"posTag\": \"NOUN\"}]', '[\"need\", \"copies\"]', '', 'noʊ aɪ doʊnt niːd ɛni mɔːɹ kɑːpɪz', '[\"Gói hàng màu xanh mà cậu đã gửi cho tôi.\", \"Tuy nhiên, địa điểm có 390 gam trên mỗi tấn lại có mỏ lớn hơn, vì vậy đó là nơi chúng ta sẽ xây dựng mỏ mới.\", \"Chúng tôi hiểu rằng nhiều người đi lại cần đến Midway càng sớm càng tốt.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 10 trong bài luyện nghe Part 2.\", \"display_text\": \"No, I don\'t need any more copies.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s11', 'set-2026-t10-p2', 11, 3, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/9.mp3', NULL, NULL, 10.195e0, 13.176e0, 'I\'d prefer to look it over myself.', '[{\"end\": 11.455, \"word\": \"I\'d\", \"score\": 0.809, \"start\": 11.295, \"posTag\": \"PRON\"}, {\"end\": 11.895, \"word\": \"prefer\", \"score\": 0.896, \"start\": 11.515, \"posTag\": \"VERB\"}, {\"end\": 12.015, \"word\": \"to\", \"score\": 1.0, \"start\": 11.955, \"posTag\": \"PART\"}, {\"end\": 12.215, \"word\": \"look\", \"score\": 0.931, \"start\": 12.055, \"posTag\": \"VERB\"}, {\"end\": 12.315, \"word\": \"it\", \"score\": 0.984, \"start\": 12.255, \"posTag\": \"PRON\"}, {\"end\": 12.616, \"word\": \"over\", \"score\": 0.901, \"start\": 12.395, \"posTag\": \"ADP\"}, {\"end\": 13.176, \"word\": \"myself.\", \"score\": 0.815, \"start\": 12.656, \"posTag\": \"PRON\"}]', '[\"prefer\", \"look\"]', '', 'biː aɪd pɹɪfɜː tə lʊk ɪɾ oʊvɚ maɪsɛlf', '[\"Hội nghị được tổ chức ở đâu?\", \"Tôi không gặp bạn kể từ khi chúng ta cùng học lớp dành cho chủ doanh nghiệp năm ngoái.\", \"Vài cái đinh và một chiếc búa.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 11 trong bài luyện nghe Part 2.\", \"display_text\": \"I\'d prefer to look it over myself.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s12', 'set-2026-t10-p2', 12, 3, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/9.mp3', NULL, NULL, 14.176e0, 16.577e0, 'A 15-page document.', '[{\"end\": 15.256, \"word\": \"A\", \"score\": 0.67, \"start\": 15.196, \"posTag\": \"DET\"}, {\"end\": 16.057, \"word\": \"15-page\", \"score\": 0.759, \"start\": 15.357, \"posTag\": \"NUM\"}, {\"end\": 16.577, \"word\": \"document.\", \"score\": 0.994, \"start\": 16.117, \"posTag\": \"NOUN\"}]', '[\"document\"]', '', 'siː ɐ fɪftiːnpeɪdʒ dɑːkjuːmənt', '[\"Mấy giờ tôi có thể lấy kính vậy?\", \"Ngay sau cuộc họp của tôi với nhân viên ở Chicago thì sao?\", \"Nếu nhìn vào trang đầu tiên của tập tài liệu đào tạo, bạn sẽ thấy tên người dùng và mật khẩu tạm thời.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 12 trong bài luyện nghe Part 2.\", \"display_text\": \"A 15-page document.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s13', 'set-2026-t10-p2', 13, 4, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/10.mp3', NULL, NULL, 2.093e0, 3.735e0, 'When\'s the marketing conference?', '[{\"end\": 2.414, \"word\": \"When\'s\", \"score\": 0.846, \"start\": 2.093, \"posTag\": \"SCONJ\"}, {\"end\": 2.574, \"word\": \"the\", \"score\": 0.886, \"start\": 2.474, \"posTag\": \"DET\"}, {\"end\": 3.094, \"word\": \"marketing\", \"score\": 0.915, \"start\": 2.634, \"posTag\": \"NOUN\"}, {\"end\": 3.735, \"word\": \"conference?\", \"score\": 0.921, \"start\": 3.155, \"posTag\": \"NOUN\"}]', '[\"conference\"]', '', 'wɛnz ðə mɑːɹkɪɾɪŋ kɑːnfɹəns', '[\"Xin chú ý, quý hành khách!\", \"Xin chào.\", \"Tất cả chúng ta đều thất vọng vì doanh số bán quần áo sụt giảm.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 13 trong bài luyện nghe Part 2.\", \"display_text\": \"When\'s the marketing conference?\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s14', 'set-2026-t10-p2', 14, 4, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/10.mp3', NULL, NULL, 5.817e0, 7.519e0, 'The convention center downtown.', '[{\"end\": 5.918, \"word\": \"The\", \"score\": 0.846, \"start\": 5.817, \"posTag\": \"DET\"}, {\"end\": 6.538, \"word\": \"convention\", \"score\": 0.915, \"start\": 5.958, \"posTag\": \"NOUN\"}, {\"end\": 6.899, \"word\": \"center\", \"score\": 0.765, \"start\": 6.578, \"posTag\": \"NOUN\"}, {\"end\": 7.519, \"word\": \"downtown.\", \"score\": 0.907, \"start\": 6.919, \"posTag\": \"NOUN\"}]', '[\"convention\"]', '', 'ðə kənvɛnʃən sɛntɚ daʊntaʊn', '[\"Mọi người thực sự rất thích nó.\", \"Hôm nay bạn không thể cập nhật cơ sở dữ liệu à?\", \"Họ dự kiến sẽ hoàn thành việc sửa chữa trong vòng một giờ tới.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 14 trong bài luyện nghe Part 2.\", \"display_text\": \"The convention center downtown.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s15', 'set-2026-t10-p2', 15, 4, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/10.mp3', NULL, NULL, 9.582e0, 10.683e0, 'Sometime next month.', '[{\"end\": 10.042, \"word\": \"Sometime\", \"score\": 0.818, \"start\": 9.582, \"posTag\": \"ADV\"}, {\"end\": 10.303, \"word\": \"next\", \"score\": 0.922, \"start\": 10.102, \"posTag\": \"ADJ\"}, {\"end\": 10.683, \"word\": \"month.\", \"score\": 0.91, \"start\": 10.423, \"posTag\": \"NOUN\"}]', '[\"month\"]', '', 'sʌmtaɪm nɛkst mʌnθ', '[\"Tôi tên là Diego và tôi phụ trách tất cả các buổi định hướng.\", \"Dẫu sao thì Ife Rotimi đã vô địch giải đấu khu vực vào tháng trước.\", \"Tôi đọc hết chúng rồi.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 15 trong bài luyện nghe Part 2.\", \"display_text\": \"Sometime next month.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s16', 'set-2026-t10-p2', 16, 4, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/10.mp3', NULL, NULL, 11.644e0, 14.207e0, 'I need a room with a projector.', '[{\"end\": 12.785, \"word\": \"I\", \"score\": 0.999, \"start\": 12.725, \"posTag\": \"PRON\"}, {\"end\": 13.006, \"word\": \"need\", \"score\": 0.927, \"start\": 12.825, \"posTag\": \"VERB\"}, {\"end\": 13.066, \"word\": \"a\", \"score\": 0.998, \"start\": 13.046, \"posTag\": \"DET\"}, {\"end\": 13.346, \"word\": \"room\", \"score\": 0.793, \"start\": 13.126, \"posTag\": \"NOUN\"}, {\"end\": 13.526, \"word\": \"with\", \"score\": 0.836, \"start\": 13.386, \"posTag\": \"ADP\"}, {\"end\": 13.626, \"word\": \"a\", \"score\": 0.021, \"start\": 13.606, \"posTag\": \"DET\"}, {\"end\": 14.207, \"word\": \"projector.\", \"score\": 0.919, \"start\": 13.686, \"posTag\": \"NOUN\"}]', '[\"room\", \"projector\"]', '', 'siː aɪ niːd ɐ ɹuːm wɪð ɐ pɹədʒɛktɚ', '[\"Nhân viên tổng đài sẽ kết nối với bạn trong giây lát.\", \"À, tôi nghĩ Pauline từng gặp một vấn đề tương tự với trò chơi mà cô ấy kiểm tra.\", \"Chúng tôi đóng cửa lúc 6 giờ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 16 trong bài luyện nghe Part 2.\", \"display_text\": \"I need a room with a projector.\"}', '2026-09-15 07:19:41'),
