('set-2026-t10-p2-s52', 'set-2026-t10-p2', 52, 13, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/19.mp3', NULL, NULL, 11.268e0, 13.792e0, 'Yes, I like it a lot.', '[{\"end\": 12.55, \"word\": \"Yes,\", \"score\": 0.919, \"start\": 12.27, \"posTag\": \"INTJ\"}, {\"end\": 13.091, \"word\": \"I\", \"score\": 0.925, \"start\": 13.011, \"posTag\": \"PRON\"}, {\"end\": 13.311, \"word\": \"like\", \"score\": 0.855, \"start\": 13.131, \"posTag\": \"VERB\"}, {\"end\": 13.411, \"word\": \"it\", \"score\": 0.74, \"start\": 13.351, \"posTag\": \"PRON\"}, {\"end\": 13.471, \"word\": \"a\", \"score\": 0.999, \"start\": 13.451, \"posTag\": \"DET\"}, {\"end\": 13.792, \"word\": \"lot.\", \"score\": 0.898, \"start\": 13.552, \"posTag\": \"NOUN\"}]', '[\"like\", \"lot\"]', '', 'siː jɛs aɪ laɪk ɪɾ ɐ lɑːt', '[\"Tôi vừa mua ít hoa cho bữa tiệc nghỉ hưu của Tunji.\", \"Quy trình nộp báo cáo chi phí của tôi như thế nào?\", \"Trên màn hình, quý vị có thể thấy thông tin về quặng được khai thác từ các địa điểm khác nhau.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 52 trong bài luyện nghe Part 2.\", \"display_text\": \"Yes, I like it a lot.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s53', 'set-2026-t10-p2', 53, 14, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/20.mp3', NULL, NULL, 2.274e0, 4.738e0, 'How many people are attending the orientation session?', '[{\"end\": 2.394, \"word\": \"How\", \"score\": 1.0, \"start\": 2.274, \"posTag\": \"SCONJ\"}, {\"end\": 2.635, \"word\": \"many\", \"score\": 0.845, \"start\": 2.434, \"posTag\": \"ADJ\"}, {\"end\": 2.935, \"word\": \"people\", \"score\": 0.779, \"start\": 2.675, \"posTag\": \"NOUN\"}, {\"end\": 3.075, \"word\": \"are\", \"score\": 0.79, \"start\": 2.975, \"posTag\": \"AUX\"}, {\"end\": 3.496, \"word\": \"attending\", \"score\": 0.89, \"start\": 3.115, \"posTag\": \"VERB\"}, {\"end\": 3.636, \"word\": \"the\", \"score\": 0.669, \"start\": 3.536, \"posTag\": \"DET\"}, {\"end\": 4.297, \"word\": \"orientation\", \"score\": 0.914, \"start\": 3.716, \"posTag\": \"NOUN\"}, {\"end\": 4.738, \"word\": \"session?\", \"score\": 0.904, \"start\": 4.337, \"posTag\": \"NOUN\"}]', '[\"orientation\"]', '', 'haʊ mɛni piːpəl ɑːɹ ɐtɛndɪŋ ðɪ ɔːɹiənteɪʃən sɛʃən', '[\"Ban quản lý Reston đã xác nhận danh sách khách thuê của tòa nhà và chúng tôi đã phỏng vấn Giám đốc điều hành của Barnum Financial Services về văn phòng mới của họ.\", \"Không, tôi vẫn chưa nhận được email xác nhận.\", \"Cho đến nay, đó là chi nhánh đông khách nhất của chúng ta.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 53 trong bài luyện nghe Part 2.\", \"display_text\": \"How many people are attending the orientation session?\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s54', 'set-2026-t10-p2', 54, 14, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/20.mp3', NULL, NULL, 6.701e0, 8.243e0, 'There should be 21 people.', '[{\"end\": 6.861, \"word\": \"There\", \"score\": 0.853, \"start\": 6.701, \"posTag\": \"PRON\"}, {\"end\": 7.081, \"word\": \"should\", \"score\": 0.712, \"start\": 6.881, \"posTag\": \"AUX\"}, {\"end\": 7.221, \"word\": \"be\", \"score\": 0.863, \"start\": 7.121, \"posTag\": \"AUX\"}, {\"end\": 7.822, \"word\": \"21\", \"score\": 0.522, \"start\": 7.402, \"posTag\": \"NUM\"}, {\"end\": 8.243, \"word\": \"people.\", \"score\": 0.804, \"start\": 7.882, \"posTag\": \"NOUN\"}]', '[\"people\"]', '', 'ðɛɹ ʃʊd biː twɛnti wʌn piːpəl', '[\"Ngoài ra, xin nhắc lại là quán cà phê của nhà ga mở cửa lúc 8 giờ sáng và có các quầy bán đồ ăn ở Sân ga 1.\", \"Chúng được làm từ giấy.\", \"Dụng cụ vẽ đã được bày trên sàn nhà.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 54 trong bài luyện nghe Part 2.\", \"display_text\": \"There should be 21 people.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s55', 'set-2026-t10-p2', 55, 14, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/20.mp3', NULL, NULL, 10.246e0, 11.247e0, 'Maybe next week.', '[{\"end\": 10.566, \"word\": \"Maybe\", \"score\": 0.807, \"start\": 10.246, \"posTag\": \"ADV\"}, {\"end\": 10.866, \"word\": \"next\", \"score\": 0.875, \"start\": 10.626, \"posTag\": \"ADJ\"}, {\"end\": 11.247, \"word\": \"week.\", \"score\": 0.88, \"start\": 10.947, \"posTag\": \"NOUN\"}]', '[\"week\"]', '', 'meɪbiː nɛkst wiːk', '[\"Ồ, tôi nghĩ chúng ta nên chuyển thông tin đó ra khỏi trang Giới thiệu và tạo một trang riêng cho phần chỉ đường và thông tin đậu xe.\", \"Máy chiếu đang hoạt động không đúng cách.\", \"Tuyệt quá.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 55 trong bài luyện nghe Part 2.\", \"display_text\": \"Maybe next week.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s56', 'set-2026-t10-p2', 56, 14, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/20.mp3', NULL, NULL, 12.228e0, 14.592e0, 'I can\'t see the screen.', '[{\"end\": 13.39, \"word\": \"I\", \"score\": 0.699, \"start\": 13.33, \"posTag\": \"PRON\"}, {\"end\": 13.711, \"word\": \"can\'t\", \"score\": 0.869, \"start\": 13.45, \"posTag\": \"AUX\"}, {\"end\": 13.971, \"word\": \"see\", \"score\": 0.915, \"start\": 13.771, \"posTag\": \"VERB\"}, {\"end\": 14.131, \"word\": \"the\", \"score\": 0.83, \"start\": 14.031, \"posTag\": \"DET\"}, {\"end\": 14.592, \"word\": \"screen.\", \"score\": 0.92, \"start\": 14.171, \"posTag\": \"NOUN\"}]', '[\"screen\"]', '', 'siː aɪ kænt siː ðə skɹiːn', '[\"Phải đến chiều nay cơ.\", \"Ngay cạnh lối vào chính.\", \"Ồ, thế à?\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 56 trong bài luyện nghe Part 2.\", \"display_text\": \"I can\'t see the screen.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s57', 'set-2026-t10-p2', 57, 15, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/21.mp3', NULL, NULL, 2.532e0, 5.493e0, 'There\'s a free shuttle bus to the airport, right?', '[{\"end\": 2.852, \"word\": \"There\'s\", \"score\": 0.717, \"start\": 2.532, \"posTag\": \"PRON\"}, {\"end\": 2.972, \"word\": \"a\", \"score\": 0.554, \"start\": 2.932, \"posTag\": \"DET\"}, {\"end\": 3.372, \"word\": \"free\", \"score\": 0.873, \"start\": 3.092, \"posTag\": \"ADJ\"}, {\"end\": 3.792, \"word\": \"shuttle\", \"score\": 0.882, \"start\": 3.452, \"posTag\": \"NOUN\"}, {\"end\": 4.113, \"word\": \"bus\", \"score\": 0.859, \"start\": 3.832, \"posTag\": \"NOUN\"}, {\"end\": 4.253, \"word\": \"to\", \"score\": 0.994, \"start\": 4.153, \"posTag\": \"ADP\"}, {\"end\": 4.393, \"word\": \"the\", \"score\": 0.685, \"start\": 4.293, \"posTag\": \"DET\"}, {\"end\": 4.973, \"word\": \"airport,\", \"score\": 0.89, \"start\": 4.473, \"posTag\": \"NOUN\"}, {\"end\": 5.493, \"word\": \"right?\", \"score\": 0.784, \"start\": 5.193, \"posTag\": \"ADJ\"}]', '[\"shuttle\", \"airport\"]', '', 'ðɛɹz ɐ fɹiː ʃʌɾəl bʌs tə ðɪ ɛɹpɔːɹt ɹaɪt', '[\"Chúng tôi chuyên sửa chữa mọi hãng và dòng xe ô tô.\", \"Anh ấy đang nhấc một hộp sơn bằng quai xách của nó.\", \"Bạn gửi nó đến phòng tài chính.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 57 trong bài luyện nghe Part 2.\", \"display_text\": \"There\'s a free shuttle bus to the airport, right?\"}', '2026-09-15 07:19:41')
