('set-2026-t10-p2-s58', 'set-2026-t10-p2', 58, 15, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/21.mp3', NULL, NULL, 7.514e0, 8.874e0, 'She has an overnight flight.', '[{\"end\": 7.654, \"word\": \"She\", \"score\": 0.792, \"start\": 7.514, \"posTag\": \"PRON\"}, {\"end\": 7.874, \"word\": \"has\", \"score\": 0.992, \"start\": 7.694, \"posTag\": \"VERB\"}, {\"end\": 7.974, \"word\": \"an\", \"score\": 0.972, \"start\": 7.914, \"posTag\": \"DET\"}, {\"end\": 8.494, \"word\": \"overnight\", \"score\": 0.819, \"start\": 8.134, \"posTag\": \"ADJ\"}, {\"end\": 8.874, \"word\": \"flight.\", \"score\": 0.88, \"start\": 8.534, \"posTag\": \"NOUN\"}]', '[\"flight\"]', '', 'ʃiː hɐz ɐn oʊvɚnaɪt flaɪt', '[\"Ở cửa hàng đồ kim khí.\", \"Nếu nhìn vào trang đầu tiên của tập tài liệu đào tạo, bạn sẽ thấy tên người dùng và mật khẩu tạm thời.\", \"À, tôi thấy nhà hàng Sunnyvale đã đóng cửa và tòa nhà đó đang cho thuê.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 58 trong bài luyện nghe Part 2.\", \"display_text\": \"She has an overnight flight.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s59', 'set-2026-t10-p2', 59, 15, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/21.mp3', NULL, NULL, 10.855e0, 12.836e0, 'Yes, it stops right outside.', '[{\"end\": 11.155, \"word\": \"Yes,\", \"score\": 0.973, \"start\": 10.855, \"posTag\": \"INTJ\"}, {\"end\": 11.615, \"word\": \"it\", \"score\": 0.835, \"start\": 11.535, \"posTag\": \"PRON\"}, {\"end\": 11.995, \"word\": \"stops\", \"score\": 0.795, \"start\": 11.675, \"posTag\": \"VERB\"}, {\"end\": 12.336, \"word\": \"right\", \"score\": 0.827, \"start\": 12.115, \"posTag\": \"ADV\"}, {\"end\": 12.836, \"word\": \"outside.\", \"score\": 0.885, \"start\": 12.376, \"posTag\": \"ADV\"}]', '[\"stops\"]', '', 'jɛs ɪt stɑːps ɹaɪt aʊtsaɪd', '[\"Bản ghi âm cuộc phỏng vấn đầy đủ với Giám đốc điều hành có trên trang web của chúng tôi.\", \"Ai đã gửi biên bản cuộc họp cho phòng kế toán?\", \"Chúng tôi đóng cửa lúc 6 giờ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 59 trong bài luyện nghe Part 2.\", \"display_text\": \"Yes, it stops right outside.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s60', 'set-2026-t10-p2', 60, 15, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/21.mp3', NULL, NULL, 13.736e0, 16.117e0, 'No, I don\'t have any.', '[{\"end\": 15.157, \"word\": \"No,\", \"score\": 0.959, \"start\": 14.897, \"posTag\": \"INTJ\"}, {\"end\": 15.497, \"word\": \"I\", \"score\": 0.684, \"start\": 15.437, \"posTag\": \"PRON\"}, {\"end\": 15.677, \"word\": \"don\'t\", \"score\": 0.878, \"start\": 15.517, \"posTag\": \"AUX\"}, {\"end\": 15.857, \"word\": \"have\", \"score\": 0.875, \"start\": 15.717, \"posTag\": \"VERB\"}, {\"end\": 16.117, \"word\": \"any.\", \"score\": 0.988, \"start\": 15.917, \"posTag\": \"PRON\"}]', '[\"have\"]', '', 'siː noʊ aɪ doʊnt hæv ɛni', '[\"Nó không có trên trang web của chúng ta sao?\", \"Không, tôi không biết chơi guitar.\", \"Đúng vậy, và vì du lịch mùa đông gần đây đã tăng lên, chúng tôi muốn mở rộng mặt bằng để có thể chứa được nhiều hàng hóa hơn.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 60 trong bài luyện nghe Part 2.\", \"display_text\": \"No, I don\'t have any.\"}', '2026-09-15 07:19:41'),
('set-2026-t10-p2-s61', 'set-2026-t10-p2', 61, 16, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/22.mp3', NULL, NULL, 0.431e0, 4.395e0, 'Who has time to edit this article?', '[{\"end\": 2.734, \"word\": \"Who\", \"score\": 0.816, \"start\": 2.573, \"posTag\": \"PRON\"}, {\"end\": 2.954, \"word\": \"has\", \"score\": 0.858, \"start\": 2.774, \"posTag\": \"VERB\"}, {\"end\": 3.234, \"word\": \"time\", \"score\": 0.916, \"start\": 3.014, \"posTag\": \"NOUN\"}, {\"end\": 3.354, \"word\": \"to\", \"score\": 1.0, \"start\": 3.294, \"posTag\": \"PART\"}, {\"end\": 3.694, \"word\": \"edit\", \"score\": 0.816, \"start\": 3.454, \"posTag\": \"VERB\"}, {\"end\": 3.895, \"word\": \"this\", \"score\": 0.815, \"start\": 3.734, \"posTag\": \"DET\"}, {\"end\": 4.395, \"word\": \"article?\", \"score\": 0.902, \"start\": 3.975, \"posTag\": \"NOUN\"}]', '[\"time\", \"article\"]', '', 'nʌmbɚ twɛnti tuː huː hɐz taɪm tʊ ɛdɪt ðɪs ɑːɹɾɪkəl', '[\"Tôi rất sẵn lòng thực hiện thay đổi đó, nhưng chúng ta đang bận cập nhật phần mềm, nên việc này phải đợi đến thứ Hai nhé.\", \"Người phụ nữ đang mặc áo khoác.\", \"Đã có vài lần nhân vật của tôi không thể di chuyển được.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 61 trong bài luyện nghe Part 2.\", \"display_text\": \"Who has time to edit this article?\"}', '2026-09-15 07:19:41'),
