('set-2026-t10-p3-s8', 'set-2026-t10-p3', 8, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/35-37.mp3', NULL, NULL, 12.777e0, 14.277e0, 'Sure, what do you have in mind?', '[{\"end\": 13.117, \"word\": \"Sure,\", \"score\": 0.819, \"start\": 12.777, \"posTag\": \"INTJ\"}, {\"end\": 13.397, \"word\": \"what\", \"score\": 0.884, \"start\": 13.277, \"posTag\": \"PRON\"}, {\"end\": 13.497, \"word\": \"do\", \"score\": 0.965, \"start\": 13.437, \"posTag\": \"AUX\"}, {\"end\": 13.597, \"word\": \"you\", \"score\": 0.749, \"start\": 13.517, \"posTag\": \"PRON\"}, {\"end\": 13.777, \"word\": \"have\", \"score\": 0.79, \"start\": 13.637, \"posTag\": \"VERB\"}, {\"end\": 13.897, \"word\": \"in\", \"score\": 0.824, \"start\": 13.817, \"posTag\": \"ADP\"}, {\"end\": 14.277, \"word\": \"mind?\", \"score\": 0.813, \"start\": 13.937, \"posTag\": \"NOUN\"}]', '[\"mind\"]', '', 'ʃʊɹ wʌt duː juː hæv ɪn maɪnd', '[\"Vì các nhà máy của chúng ta đều ở nước ngoài, nên mất quá nhiều thời gian để đơn hàng đến tay khách hàng.\", \"Tôi đã sắp xếp buổi họp báo này để chính thức trả lời các thắc mắc của quý vị.\", \"Video chất lượng cao có thể được quay và chỉnh sửa bằng điện thoại thông minh.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 8 trong bài luyện nghe Part 3.\", \"display_text\": \"Sure, what do you have in mind?\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s9', 'set-2026-t10-p3', 9, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/35-37.mp3', NULL, NULL, 15.058e0, 20.44e0, 'Well, I want to paint the walls with one of the colours from our new logo, either green or red.', '[{\"end\": 15.298, \"word\": \"Well,\", \"score\": 0.997, \"start\": 15.058, \"posTag\": \"INTJ\"}, {\"end\": 15.818, \"word\": \"I\", \"score\": 0.6, \"start\": 15.718, \"posTag\": \"PRON\"}, {\"end\": 15.998, \"word\": \"want\", \"score\": 0.747, \"start\": 15.858, \"posTag\": \"VERB\"}, {\"end\": 16.098, \"word\": \"to\", \"score\": 0.869, \"start\": 16.038, \"posTag\": \"PART\"}, {\"end\": 16.318, \"word\": \"paint\", \"score\": 0.851, \"start\": 16.138, \"posTag\": \"VERB\"}, {\"end\": 16.438, \"word\": \"the\", \"score\": 0.833, \"start\": 16.358, \"posTag\": \"DET\"}, {\"end\": 16.778, \"word\": \"walls\", \"score\": 0.865, \"start\": 16.478, \"posTag\": \"NOUN\"}, {\"end\": 16.998, \"word\": \"with\", \"score\": 0.823, \"start\": 16.858, \"posTag\": \"ADP\"}, {\"end\": 17.218, \"word\": \"one\", \"score\": 0.833, \"start\": 17.138, \"posTag\": \"NUM\"}, {\"end\": 17.299, \"word\": \"of\", \"score\": 0.748, \"start\": 17.239, \"posTag\": \"ADP\"}, {\"end\": 17.399, \"word\": \"the\", \"score\": 0.833, \"start\": 17.319, \"posTag\": \"DET\"}, {\"end\": 17.779, \"word\": \"colours\", \"score\": 0.498, \"start\": 17.439, \"posTag\": \"NOUN\"}, {\"end\": 17.939, \"word\": \"from\", \"score\": 0.875, \"start\": 17.819, \"posTag\": \"ADP\"}, {\"end\": 18.099, \"word\": \"our\", \"score\": 0.988, \"start\": 18.019, \"posTag\": \"PRON\"}, {\"end\": 18.319, \"word\": \"new\", \"score\": 0.967, \"start\": 18.159, \"posTag\": \"ADJ\"}, {\"end\": 18.779, \"word\": \"logo,\", \"score\": 0.933, \"start\": 18.359, \"posTag\": \"NOUN\"}, {\"end\": 19.58, \"word\": \"either\", \"score\": 0.806, \"start\": 18.799, \"posTag\": \"CCONJ\"}, {\"end\": 20.0, \"word\": \"green\", \"score\": 0.87, \"start\": 19.72, \"posTag\": \"ADJ\"}, {\"end\": 20.16, \"word\": \"or\", \"score\": 0.858, \"start\": 20.06, \"posTag\": \"CCONJ\"}, {\"end\": 20.44, \"word\": \"red.\", \"score\": 0.855, \"start\": 20.2, \"posTag\": \"NOUN\"}]', '[\"walls\", \"colours\", \"logo\"]', '', 'wɛl aɪ wɔnt tə peɪnt ðə wɔːlz wɪð wʌn ʌvðə kʌlɚz fɹʌm aʊɚ nuː loʊɡoʊ iːðɚ ɡɹiːn ɔːɹ ɹɛd', '[\"Chúng ta sẽ tìm kiếm một địa điểm để xây dựng cơ sở sản xuất.\", \"Hình ảnh thứ hai phản ánh lịch sử thương hiệu của bạn và logo của nó.\", \"Tôi đang cân nhắc mua thêm một số máy nữa trong thời gian tới.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 9 trong bài luyện nghe Part 3.\", \"display_text\": \"Well, I want to paint the walls with one of the colours from our new logo, either green or red.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s10', 'set-2026-t10-p3', 10, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/35-37.mp3', NULL, NULL, 20.98e0, 23.421e0, 'Hmm, I wouldn\'t choose red.', '[{\"end\": 22.101, \"word\": \"Hmm,\", \"score\": 0.735, \"start\": 20.98, \"posTag\": \"INTJ\"}, {\"end\": 22.141, \"word\": \"I\", \"score\": 0.0, \"start\": 22.121, \"posTag\": \"PRON\"}, {\"end\": 22.581, \"word\": \"wouldn\'t\", \"score\": 0.791, \"start\": 22.221, \"posTag\": \"AUX\"}, {\"end\": 23.001, \"word\": \"choose\", \"score\": 0.726, \"start\": 22.681, \"posTag\": \"VERB\"}, {\"end\": 23.421, \"word\": \"red.\", \"score\": 0.863, \"start\": 23.121, \"posTag\": \"NOUN\"}]', '[\"red\"]', '', 'həm aɪ wʊdənt tʃuːz ɹɛd', '[\"Các bạn có thể chia sẻ thêm về công việc kinh doanh của mình được không?\", \"Được rồi, tôi sẽ tiến hành đặt mua vài thùng.\", \"Trước khi chúng ta bắt đầu hôm nay, các bạn cần thiết lập tài khoản nhân viên của mình.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 10 trong bài luyện nghe Part 3.\", \"display_text\": \"Hmm, I wouldn\'t choose red.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s11', 'set-2026-t10-p3', 11, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/35-37.mp3', NULL, NULL, 23.801e0, 25.002e0, 'It will fade too fast.', '[{\"end\": 23.861, \"word\": \"It\", \"score\": 0.936, \"start\": 23.801, \"posTag\": \"PRON\"}, {\"end\": 24.061, \"word\": \"will\", \"score\": 0.837, \"start\": 23.901, \"posTag\": \"AUX\"}, {\"end\": 24.362, \"word\": \"fade\", \"score\": 0.858, \"start\": 24.122, \"posTag\": \"VERB\"}, {\"end\": 24.562, \"word\": \"too\", \"score\": 0.933, \"start\": 24.422, \"posTag\": \"ADV\"}, {\"end\": 25.002, \"word\": \"fast.\", \"score\": 0.995, \"start\": 24.622, \"posTag\": \"ADV\"}]', '[\"fade\"]', '', 'ɪt wɪl feɪd tuː fæst', '[\"Đó là cánh cửa ở cuối hành lang.\", \"Nếu nhìn vào trang đầu tiên của tập tài liệu đào tạo, bạn sẽ thấy tên người dùng và mật khẩu tạm thời.\", \"Zaina, thật bất ngờ!\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 11 trong bài luyện nghe Part 3.\", \"display_text\": \"It will fade too fast.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s12', 'set-2026-t10-p3', 12, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/35-37.mp3', NULL, NULL, 25.827e0, 26.528e0, 'Oh, okay.', '[{\"end\": 25.927, \"word\": \"Oh,\", \"score\": 0.835, \"start\": 25.827, \"posTag\": \"INTJ\"}, {\"end\": 26.528, \"word\": \"okay.\", \"score\": 0.66, \"start\": 26.187, \"posTag\": \"ADJ\"}]', '[\"okay\"]', '', 'oʊ oʊkeɪ', '[\"Anh ấy không còn cái nào nữa.\", \"Tôi thậm chí đang tính mở cơ sở thứ hai.\", \"Tại sao chúng ta phải làm điều này?\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 12 trong bài luyện nghe Part 3.\", \"display_text\": \"Oh, okay.\"}', '2026-09-15 07:19:42'),
