('set-2026-t10-p3-s53', 'set-2026-t10-p3', 53, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/47-49.mp3', NULL, NULL, 15.303e0, 17.984e0, 'Drive to the pickup area by Terminal A.', '[{\"end\": 15.664, \"word\": \"Drive\", \"score\": 0.87, \"start\": 15.303, \"posTag\": \"VERB\"}, {\"end\": 15.844, \"word\": \"to\", \"score\": 0.822, \"start\": 15.724, \"posTag\": \"ADP\"}, {\"end\": 15.944, \"word\": \"the\", \"score\": 0.834, \"start\": 15.864, \"posTag\": \"DET\"}, {\"end\": 16.324, \"word\": \"pickup\", \"score\": 0.849, \"start\": 15.984, \"posTag\": \"ADJ\"}, {\"end\": 16.804, \"word\": \"area\", \"score\": 0.744, \"start\": 16.464, \"posTag\": \"NOUN\"}, {\"end\": 17.004, \"word\": \"by\", \"score\": 0.915, \"start\": 16.844, \"posTag\": \"ADP\"}, {\"end\": 17.584, \"word\": \"Terminal\", \"score\": 0.943, \"start\": 17.064, \"posTag\": \"PROPN\"}, {\"end\": 17.984, \"word\": \"A.\", \"score\": 0.924, \"start\": 17.804, \"posTag\": \"NOUN\"}]', '[\"Drive\", \"area\", \"Terminal\"]', '', 'dɹaɪv tə ðə pɪkʌp ɛɹiə baɪ tɜːmɪnəl eɪ', '[\"Hay là chúng ta quay video lại cảnh các nhân viên có kinh nghiệm thực hiện các công việc cụ thể nhỉ?\", \"Tôi tên là Diego và tôi phụ trách tất cả các buổi định hướng.\", \"Một chiếc thùng gỗ được chất đầy rau củ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 53 trong bài luyện nghe Part 3.\", \"display_text\": \"Drive to the pickup area by Terminal A.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s54', 'set-2026-t10-p3', 54, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/47-49.mp3', NULL, NULL, 18.444e0, 21.506e0, 'Look out for the orange sign that says Rideshare.', '[{\"end\": 18.645, \"word\": \"Look\", \"score\": 0.766, \"start\": 18.444, \"posTag\": \"VERB\"}, {\"end\": 18.845, \"word\": \"out\", \"score\": 0.973, \"start\": 18.725, \"posTag\": \"ADP\"}, {\"end\": 19.025, \"word\": \"for\", \"score\": 0.729, \"start\": 18.905, \"posTag\": \"ADP\"}, {\"end\": 19.165, \"word\": \"the\", \"score\": 0.647, \"start\": 19.045, \"posTag\": \"DET\"}, {\"end\": 19.665, \"word\": \"orange\", \"score\": 0.824, \"start\": 19.345, \"posTag\": \"ADJ\"}, {\"end\": 20.065, \"word\": \"sign\", \"score\": 0.934, \"start\": 19.745, \"posTag\": \"NOUN\"}, {\"end\": 20.225, \"word\": \"that\", \"score\": 0.817, \"start\": 20.105, \"posTag\": \"PRON\"}, {\"end\": 20.585, \"word\": \"says\", \"score\": 0.844, \"start\": 20.285, \"posTag\": \"VERB\"}, {\"end\": 21.506, \"word\": \"Rideshare.\", \"score\": 0.831, \"start\": 20.825, \"posTag\": \"PROPN\"}]', '[\"Look\", \"sign\", \"says\"]', '', 'lʊk aʊt fɚðɪ ɔɹɪndʒ saɪn ðæt sɛz ɹaɪdʃɛɹ', '[\"Một số người đang xem một cuốn sách.\", \"Nó ít hợp thời trang hơn, nhưng không khác biệt nhiều so với bản gốc, điều mà bạn có thể thích hơn.\", \"Người phụ nữ đang cởi mũ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 54 trong bài luyện nghe Part 3.\", \"display_text\": \"Look out for the orange sign that says Rideshare.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s55', 'set-2026-t10-p3', 55, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/47-49.mp3', NULL, NULL, 21.946e0, 23.786e0, 'I\'m sure you\'ll see other drivers there.', '[{\"end\": 22.066, \"word\": \"I\'m\", \"score\": 0.989, \"start\": 21.946, \"posTag\": \"PRON\"}, {\"end\": 22.346, \"word\": \"sure\", \"score\": 0.636, \"start\": 22.146, \"posTag\": \"ADJ\"}, {\"end\": 22.586, \"word\": \"you\'ll\", \"score\": 0.871, \"start\": 22.366, \"posTag\": \"PRON\"}, {\"end\": 22.766, \"word\": \"see\", \"score\": 0.879, \"start\": 22.606, \"posTag\": \"VERB\"}, {\"end\": 23.026, \"word\": \"other\", \"score\": 0.912, \"start\": 22.846, \"posTag\": \"ADJ\"}, {\"end\": 23.446, \"word\": \"drivers\", \"score\": 0.767, \"start\": 23.046, \"posTag\": \"NOUN\"}, {\"end\": 23.786, \"word\": \"there.\", \"score\": 0.776, \"start\": 23.486, \"posTag\": \"ADV\"}]', '[\"see\", \"drivers\"]', '', 'aɪm ʃʊɹ juːl siː ʌðɚ dɹaɪvɚz ðɛɹ', '[\"Tôi làm việc đó hôm qua rồi.\", \"Tôi ổn, cảm ơn bạn.\", \"Người phụ nữ đang buộc tóc.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 55 trong bài luyện nghe Part 3.\", \"display_text\": \"I\'m sure you\'ll see other drivers there.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s56', 'set-2026-t10-p3', 56, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/47-49.mp3', NULL, NULL, 24.407e0, 27.548e0, 'By the way, I recommend taking the Terminal Bypass.', '[{\"end\": 24.547, \"word\": \"By\", \"score\": 0.754, \"start\": 24.407, \"posTag\": \"ADP\"}, {\"end\": 24.647, \"word\": \"the\", \"score\": 0.966, \"start\": 24.567, \"posTag\": \"DET\"}, {\"end\": 24.907, \"word\": \"way,\", \"score\": 0.803, \"start\": 24.707, \"posTag\": \"NOUN\"}, {\"end\": 25.247, \"word\": \"I\", \"score\": 0.791, \"start\": 25.167, \"posTag\": \"PRON\"}, {\"end\": 25.827, \"word\": \"recommend\", \"score\": 0.853, \"start\": 25.367, \"posTag\": \"VERB\"}, {\"end\": 26.207, \"word\": \"taking\", \"score\": 0.863, \"start\": 25.867, \"posTag\": \"VERB\"}, {\"end\": 26.347, \"word\": \"the\", \"score\": 0.682, \"start\": 26.247, \"posTag\": \"DET\"}, {\"end\": 26.867, \"word\": \"Terminal\", \"score\": 0.925, \"start\": 26.387, \"posTag\": \"PROPN\"}, {\"end\": 27.548, \"word\": \"Bypass.\", \"score\": 0.954, \"start\": 26.927, \"posTag\": \"PROPN\"}]', '[\"way\", \"taking\", \"Bypass\"]', '', 'baɪ ðə weɪ aɪ ɹɛkəmɛnd teɪkɪŋ ðə tɜːmɪnəl baɪpæs', '[\"Tôi rất sẵn lòng thực hiện thay đổi đó, nhưng chúng ta đang bận cập nhật phần mềm, nên việc này phải đợi đến thứ Hai nhé.\", \"Chào mừng các nhân viên mới.\", \"Cuối cùng chúng ta đã nhận được sự chấp thuận cho dự án lắp đặt giá để xe đạp tại nhà ga khu vực trung tâm thành phố của bộ phận mình.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 56 trong bài luyện nghe Part 3.\", \"display_text\": \"By the way, I recommend taking the Terminal Bypass.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s57', 'set-2026-t10-p3', 57, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/47-49.mp3', NULL, NULL, 27.928e0, 29.648e0, 'That bridge will take you there faster.', '[{\"end\": 28.088, \"word\": \"That\", \"score\": 0.979, \"start\": 27.928, \"posTag\": \"DET\"}, {\"end\": 28.408, \"word\": \"bridge\", \"score\": 0.881, \"start\": 28.148, \"posTag\": \"NOUN\"}, {\"end\": 28.608, \"word\": \"will\", \"score\": 0.666, \"start\": 28.428, \"posTag\": \"AUX\"}, {\"end\": 28.788, \"word\": \"take\", \"score\": 0.87, \"start\": 28.648, \"posTag\": \"VERB\"}, {\"end\": 28.928, \"word\": \"you\", \"score\": 0.753, \"start\": 28.808, \"posTag\": \"PRON\"}, {\"end\": 29.128, \"word\": \"there\", \"score\": 0.803, \"start\": 28.948, \"posTag\": \"ADV\"}, {\"end\": 29.648, \"word\": \"faster.\", \"score\": 0.916, \"start\": 29.168, \"posTag\": \"ADV\"}]', '[\"bridge\", \"take\"]', '', 'ðæt bɹɪdʒ wɪl teɪk juː ðɛɹ fæstɚ', '[\"Ở góc đường số 4 và phố Main.\", \"Sau đó, bạn sẽ được nhắc tạo mật khẩu của riêng mình.\", \"Cần phải thanh toán trước để giữ chỗ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 57 trong bài luyện nghe Part 3.\", \"display_text\": \"That bridge will take you there faster.\"}', '2026-09-15 07:19:42')
