('set-2026-t10-p3-s58', 'set-2026-t10-p3', 58, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/47-49.mp3', NULL, NULL, 30.069e0, 30.409e0, 'Great.', '[{\"end\": 30.409, \"word\": \"Great.\", \"score\": 0.89, \"start\": 30.069, \"posTag\": \"ADJ\"}]', '[\"Great\"]', '', 'ɡɹeɪt', '[\"Có danh sách khách mời nào không?\", \"Cuối cùng thì!\", \"Máy chiếu đang hoạt động không đúng cách.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 58 trong bài luyện nghe Part 3.\", \"display_text\": \"Great.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s59', 'set-2026-t10-p3', 59, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/47-49.mp3', NULL, NULL, 30.849e0, 31.249e0, 'Thank you.', '[{\"end\": 31.069, \"word\": \"Thank\", \"score\": 0.988, \"start\": 30.849, \"posTag\": \"VERB\"}, {\"end\": 31.249, \"word\": \"you.\", \"score\": 0.894, \"start\": 31.089, \"posTag\": \"PRON\"}]', '[\"Thank\"]', '', 'θæŋk juː', '[\"Tuy nhiên, trên trang web của chúng tôi có liệt kê một số công ty chuyên tháo dỡ và xử lý các món đồ đó giúp anh/chị.\", \"Một ít nước đã đọng lại trên lối đi.\", \"Bước tiếp theo của chúng ta là xin các giấy phép cần thiết.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 59 trong bài luyện nghe Part 3.\", \"display_text\": \"Thank you.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s60', 'set-2026-t10-p3', 60, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/47-49.mp3', NULL, NULL, 31.929e0, 34.27e0, 'Oh, is there a fuel station near the airport?', '[{\"end\": 32.029, \"word\": \"Oh,\", \"score\": 0.833, \"start\": 31.929, \"posTag\": \"INTJ\"}, {\"end\": 32.529, \"word\": \"is\", \"score\": 0.7, \"start\": 32.449, \"posTag\": \"AUX\"}, {\"end\": 32.709, \"word\": \"there\", \"score\": 0.808, \"start\": 32.549, \"posTag\": \"PRON\"}, {\"end\": 32.789, \"word\": \"a\", \"score\": 1.0, \"start\": 32.769, \"posTag\": \"DET\"}, {\"end\": 33.11, \"word\": \"fuel\", \"score\": 0.871, \"start\": 32.829, \"posTag\": \"NOUN\"}, {\"end\": 33.53, \"word\": \"station\", \"score\": 0.799, \"start\": 33.15, \"posTag\": \"NOUN\"}, {\"end\": 33.73, \"word\": \"near\", \"score\": 0.693, \"start\": 33.57, \"posTag\": \"ADP\"}, {\"end\": 33.83, \"word\": \"the\", \"score\": 0.835, \"start\": 33.75, \"posTag\": \"DET\"}, {\"end\": 34.27, \"word\": \"airport?\", \"score\": 0.804, \"start\": 33.89, \"posTag\": \"NOUN\"}]', '[\"there\", \"fuel\", \"airport\"]', '', 'oʊ ɪz ðɛɹ ɐ fjuːəl steɪʃən nɪɹ ðɪ ɛɹpɔːɹt', '[\"Tôi đang cân nhắc mua thêm một số máy nữa trong thời gian tới.\", \"Phàn nàn lớn nhất về việc mua sắm tại các cửa hàng của chúng ta là phải xếp hàng dài để thanh toán.\", \"Vâng, đó là một cuộc gọi hội nghị.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 60 trong bài luyện nghe Part 3.\", \"display_text\": \"Oh, is there a fuel station near the airport?\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s61', 'set-2026-t10-p3', 61, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/47-49.mp3', NULL, NULL, 34.57e0, 35.871e0, 'My tank is almost empty.', '[{\"end\": 34.71, \"word\": \"My\", \"score\": 0.995, \"start\": 34.57, \"posTag\": \"PRON\"}, {\"end\": 35.01, \"word\": \"tank\", \"score\": 0.911, \"start\": 34.77, \"posTag\": \"NOUN\"}, {\"end\": 35.15, \"word\": \"is\", \"score\": 0.668, \"start\": 35.07, \"posTag\": \"AUX\"}, {\"end\": 35.49, \"word\": \"almost\", \"score\": 0.826, \"start\": 35.21, \"posTag\": \"ADV\"}, {\"end\": 35.871, \"word\": \"empty.\", \"score\": 0.799, \"start\": 35.59, \"posTag\": \"ADJ\"}]', '[\"tank\", \"empty\"]', '', 'maɪ tæŋk ɪz ɔːlmoʊst ɛmpti', '[\"Hay là chúng ta quay video lại cảnh các nhân viên có kinh nghiệm thực hiện các công việc cụ thể nhỉ?\", \"Chào Brian và Mateo.\", \"Chúng tôi đóng cửa lúc 6 giờ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 61 trong bài luyện nghe Part 3.\", \"display_text\": \"My tank is almost empty.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s62', 'set-2026-t10-p3', 62, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/47-49.mp3', NULL, NULL, 36.291e0, 38.912e0, 'You\'ll see one by the rental car lot on your way out.', '[{\"end\": 36.531, \"word\": \"You\'ll\", \"score\": 0.75, \"start\": 36.291, \"posTag\": \"PRON\"}, {\"end\": 36.711, \"word\": \"see\", \"score\": 0.888, \"start\": 36.551, \"posTag\": \"VERB\"}, {\"end\": 36.931, \"word\": \"one\", \"score\": 0.891, \"start\": 36.811, \"posTag\": \"NUM\"}, {\"end\": 37.071, \"word\": \"by\", \"score\": 0.984, \"start\": 36.971, \"posTag\": \"ADP\"}, {\"end\": 37.191, \"word\": \"the\", \"score\": 0.904, \"start\": 37.111, \"posTag\": \"DET\"}, {\"end\": 37.571, \"word\": \"rental\", \"score\": 0.811, \"start\": 37.251, \"posTag\": \"ADJ\"}, {\"end\": 37.811, \"word\": \"car\", \"score\": 0.782, \"start\": 37.611, \"posTag\": \"NOUN\"}, {\"end\": 38.111, \"word\": \"lot\", \"score\": 0.837, \"start\": 37.851, \"posTag\": \"NOUN\"}, {\"end\": 38.251, \"word\": \"on\", \"score\": 0.793, \"start\": 38.191, \"posTag\": \"ADP\"}, {\"end\": 38.411, \"word\": \"your\", \"score\": 0.901, \"start\": 38.271, \"posTag\": \"PRON\"}, {\"end\": 38.612, \"word\": \"way\", \"score\": 0.639, \"start\": 38.451, \"posTag\": \"NOUN\"}, {\"end\": 38.912, \"word\": \"out.\", \"score\": 0.946, \"start\": 38.752, \"posTag\": \"ADV\"}]', '[\"see\", \"rental\", \"lot\", \"way\"]', '', 'juːl siː wʌn baɪ ðə ɹɛntəl kɑːɹ lɑːt ɔn jʊɹ weɪ aʊt', '[\"Nhóm bán hàng biết cách sử dụng phần mềm theo dõi phải không?\", \"Phàn nàn lớn nhất về việc mua sắm tại các cửa hàng của chúng ta là phải xếp hàng dài để thanh toán.\", \"Chúng ở trong bãi đậu xe.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 62 trong bài luyện nghe Part 3.\", \"display_text\": \"You\'ll see one by the rental car lot on your way out.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s63', 'set-2026-t10-p3', 63, 7, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/50-52.mp3', NULL, NULL, 4.612e0, 6.533e0, 'Oh, really?', '[{\"end\": 6.053, \"word\": \"Oh,\", \"score\": 0.734, \"start\": 4.612, \"posTag\": \"INTJ\"}, {\"end\": 6.533, \"word\": \"really?\", \"score\": 0.788, \"start\": 6.173, \"posTag\": \"ADV\"}]', '[\"really\"]', '', 'oʊ ɹiəli', '[\"Cảm ơn vì đã đồng ý giúp tôi tổ chức bữa tối gây quỹ thường niên của thư viện nhé, Klaus.\", \"Bằng cách đó, mọi người có thể tìm thấy nó dễ dàng hơn.\", \"Một cái cây nằm chắn ngang một bãi cỏ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 63 trong bài luyện nghe Part 3.\", \"display_text\": \"Oh, really?\"}', '2026-09-15 07:19:42'),
