('set-2026-t10-p3-s75', 'set-2026-t10-p3', 75, 8, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/53-55.mp3', NULL, NULL, 32.088e0, 36.689e0, 'Okay, I won\'t be here, but one of the other employees can definitely help you.', '[{\"end\": 32.428, \"word\": \"Okay,\", \"score\": 0.763, \"start\": 32.088, \"posTag\": \"INTJ\"}, {\"end\": 32.909, \"word\": \"I\", \"score\": 0.674, \"start\": 32.849, \"posTag\": \"PRON\"}, {\"end\": 33.189, \"word\": \"won\'t\", \"score\": 0.732, \"start\": 32.949, \"posTag\": \"AUX\"}, {\"end\": 33.429, \"word\": \"be\", \"score\": 0.876, \"start\": 33.269, \"posTag\": \"AUX\"}, {\"end\": 33.749, \"word\": \"here,\", \"score\": 0.833, \"start\": 33.469, \"posTag\": \"ADV\"}, {\"end\": 34.189, \"word\": \"but\", \"score\": 0.997, \"start\": 34.049, \"posTag\": \"CCONJ\"}, {\"end\": 34.409, \"word\": \"one\", \"score\": 0.718, \"start\": 34.309, \"posTag\": \"NUM\"}, {\"end\": 34.489, \"word\": \"of\", \"score\": 0.928, \"start\": 34.429, \"posTag\": \"ADP\"}, {\"end\": 34.629, \"word\": \"the\", \"score\": 0.934, \"start\": 34.529, \"posTag\": \"DET\"}, {\"end\": 34.929, \"word\": \"other\", \"score\": 0.794, \"start\": 34.729, \"posTag\": \"ADJ\"}, {\"end\": 35.489, \"word\": \"employees\", \"score\": 0.886, \"start\": 34.989, \"posTag\": \"NOUN\"}, {\"end\": 35.689, \"word\": \"can\", \"score\": 0.91, \"start\": 35.529, \"posTag\": \"AUX\"}, {\"end\": 36.229, \"word\": \"definitely\", \"score\": 0.825, \"start\": 35.749, \"posTag\": \"ADV\"}, {\"end\": 36.469, \"word\": \"help\", \"score\": 0.912, \"start\": 36.269, \"posTag\": \"VERB\"}, {\"end\": 36.689, \"word\": \"you.\", \"score\": 0.982, \"start\": 36.509, \"posTag\": \"PRON\"}]', '[\"one\", \"employees\", \"definitely\"]', '', 'oʊkeɪ aɪ woʊnt biː hɪɹ bʌt wʌn ʌvðɪ ʌðɚɹ ɛmplɔɪiːz kæn dɛfɪnətli hɛlp juː', '[\"Bạn đã gọi đến văn phòng bảo trì tại Khu căn hộ Hillview.\", \"Một số thiết bị chiếu sáng đang treo trên trần nhà.\", \"Hay là đặt ở lối vào nhà ga nh