('set-2026-t10-p3-s103', 'set-2026-t10-p3', 103, 11, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/62-64.mp3', NULL, NULL, 15.489e0, 19.071e0, 'All proceeds go toward the purchase of new sports equipment for the centre.', '[{\"end\": 15.649, \"word\": \"All\", \"score\": 0.837, \"start\": 15.489, \"posTag\": \"DET\"}, {\"end\": 16.189, \"word\": \"proceeds\", \"score\": 0.801, \"start\": 15.709, \"posTag\": \"NOUN\"}, {\"end\": 16.409, \"word\": \"go\", \"score\": 0.777, \"start\": 16.229, \"posTag\": \"VERB\"}, {\"end\": 16.75, \"word\": \"toward\", \"score\": 0.879, \"start\": 16.449, \"posTag\": \"ADP\"}, {\"end\": 16.85, \"word\": \"the\", \"score\": 0.836, \"start\": 16.77, \"posTag\": \"DET\"}, {\"end\": 17.31, \"word\": \"purchase\", \"score\": 0.818, \"start\": 16.93, \"posTag\": \"NOUN\"}, {\"end\": 17.41, \"word\": \"of\", \"score\": 0.75, \"start\": 17.35, \"posTag\": \"ADP\"}, {\"end\": 17.67, \"word\": \"new\", \"score\": 0.822, \"start\": 17.49, \"posTag\": \"ADJ\"}, {\"end\": 18.011, \"word\": \"sports\", \"score\": 0.912, \"start\": 17.71, \"posTag\": \"NOUN\"}, {\"end\": 18.411, \"word\": \"equipment\", \"score\": 0.89, \"start\": 18.071, \"posTag\": \"NOUN\"}, {\"end\": 18.531, \"word\": \"for\", \"score\": 0.832, \"start\": 18.431, \"posTag\": \"ADP\"}, {\"end\": 18.631, \"word\": \"the\", \"score\": 0.851, \"start\": 18.551, \"posTag\": \"DET\"}, {\"end\": 19.071, \"word\": \"centre.\", \"score\": 0.912, \"start\": 18.691, \"posTag\": \"NOUN\"}]', '[\"purchase\", \"equipment\"]', '', 'ɔːl pɹoʊsiːdz ɡoʊ təwɔːɹd ðə pɜːtʃɪs ʌv nuː spɔːɹts ɪkwɪpmənt fɚðə sɛntɚ', '[\"Khi nào bạn sẽ chọn quản lý dự án mới?\", \"Bạn có thể mượn của tôi.\", \"Xin lưu ý rằng Dịch vụ Sửa chữa Select sẽ đóng cửa vào thứ Sáu, ngày 30 tháng 6 để chúng tôi hoàn thành việc kiểm kê vật tư hàng quý.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 103 trong bài luyện nghe Part 3.\", \"display_text\": \"All proceeds go toward the purchase of new sports equipment for the centre.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s104', 'set-2026-t10-p3', 104, 11, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/62-64.mp3', NULL, NULL, 19.492e0, 23.274e0, 'You\'ll be entered into a raffle to win a prize based on your donation amount.', '[{\"end\": 19.712, \"word\": \"You\'ll\", \"score\": 0.914, \"start\": 19.492, \"posTag\": \"PRON\"}, {\"end\": 19.812, \"word\": \"be\", \"score\": 0.635, \"start\": 19.732, \"posTag\": \"AUX\"}, {\"end\": 20.132, \"word\": \"entered\", \"score\": 0.88, \"start\": 19.892, \"posTag\": \"VERB\"}, {\"end\": 20.372, \"word\": \"into\", \"score\": 0.806, \"start\": 20.172, \"posTag\": \"ADP\"}, {\"end\": 20.452, \"word\": \"a\", \"score\": 0.498, \"start\": 20.412, \"posTag\": \"DET\"}, {\"end\": 20.953, \"word\": \"raffle\", \"score\": 0.877, \"start\": 20.532, \"posTag\": \"NOUN\"}, {\"end\": 21.173, \"word\": \"to\", \"score\": 0.994, \"start\": 21.073, \"posTag\": \"PART\"}, {\"end\": 21.333, \"word\": \"win\", \"score\": 0.717, \"start\": 21.193, \"posTag\": \"VERB\"}, {\"end\": 21.393, \"word\": \"a\", \"score\": 0.509, \"start\": 21.353, \"posTag\": \"DET\"}, {\"end\": 21.853, \"word\": \"prize\", \"score\": 0.742, \"start\": 21.453, \"posTag\": \"NOUN\"}, {\"end\": 22.234, \"word\": \"based\", \"score\": 0.805, \"start\": 21.973, \"posTag\": \"VERB\"}, {\"end\": 22.354, \"word\": \"on\", \"score\": 0.802, \"start\": 22.294, \"posTag\": \"ADP\"}, {\"end\": 22.494, \"word\": \"your\", \"score\": 0.9, \"start\": 22.374, \"posTag\": \"PRON\"}, {\"end\": 22.954, \"word\": \"donation\", \"score\": 0.849, \"start\": 22.514, \"posTag\": \"NOUN\"}, {\"end\": 23.274, \"word\": \"amount.\", \"score\": 0.903, \"start\": 22.994, \"posTag\": \"NOUN\"}]', '[\"raffle\", \"prize\", \"donation\"]', '', 'juːl biː ɛntɚd ɪntʊ ɐ ɹæfəl tə wɪn ɐ pɹaɪz beɪst ɔn jʊɹ doʊneɪʃən ɐmaʊnt', '[\"Tôi thậm chí đang tính mở cơ sở thứ hai.\", \"Ở cửa hàng đồ kim khí.\", \"Chào mừng các nhân viên mới.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 104 trong bài luyện nghe Part 3.\", \"display_text\": \"You\'ll be entered into a raffle to win a prize based on your donation amount.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s105', 'set-2026-t10-p3', 105, 11, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/62-64.mp3', NULL, NULL, 23.835e0, 24.515e0, 'Sounds great.', '[{\"end\": 24.135, \"word\": \"Sounds\", \"score\": 0.816, \"start\": 23.835, \"posTag\": \"VERB\"}, {\"end\": 24.515, \"word\": \"great.\", \"score\": 0.93, \"start\": 24.195, \"posTag\": \"ADJ\"}]', '[\"Sounds\"]', '', 'saʊndz ɡɹeɪt', '[\"Các đội sửa chữa đang làm việc trên một đoạn đường ray ngay phía nam thị trấn Whedon.\", \"Cửa hàng đó vẫn chưa mở cửa.\", \"Khoảng 12 thùng hàng.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 105 trong bài luyện nghe Part 3.\", \"display_text\": \"Sounds great.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s106', 'set-2026-t10-p3', 106, 11, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/62-64.mp3', NULL, NULL, 25.156e0, 26.196e0, 'I\'d like to donate $50.', '[{\"end\": 25.296, \"word\": \"I\'d\", \"score\": 0.969, \"start\": 25.156, \"posTag\": \"PRON\"}, {\"end\": 25.496, \"word\": \"like\", \"score\": 0.978, \"start\": 25.336, \"posTag\": \"VERB\"}, {\"end\": 25.596, \"word\": \"to\", \"score\": 0.96, \"start\": 25.516, \"posTag\": \"PART\"}, {\"end\": 25.976, \"word\": \"donate\", \"score\": 0.664, \"start\": 25.636, \"posTag\": \"VERB\"}, {\"end\": 26.196, \"word\": \"$50.\", \"score\": 0.994, \"start\": 25.996, \"posTag\": \"NUM\"}]', '[\"donate\"]', '', 'aɪd laɪk tə doʊneɪt dɑːlɚ fɪfti', '[\"Xin chào, tôi là Heather Ross gọi từ Công viên Giải trí Denville.\", \"Tuyệt quá.\", \"Được rồi, tôi sẽ tiến hành đặt mua vài thùng.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 106 trong bài luyện nghe Part 3.\", \"display_text\": \"I\'d like to donate $50.\"}', '2026-09-15 07:19:42'),
('set-2026-t10-p3-s107', 'set-2026-t10-p3', 107, 11, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%2010/audio/62-64.mp3', NULL, NULL, 27.263e0, 27.763e0, 'Wonderful.', '[{\"end\": 27.763, \"word\": \"Wonderful.\", \"score\": 0.975, \"start\": 27.263, \"posTag\": \"ADJ\"}]', '[\"Wonderful\"]', '', 'wʌndɚfəl', '[\"Tôi nhân tiện ghé qua khu này nên định vào mua một cái bánh quy hoặc một miếng bánh ngọt.\", \"Tôi được biết đây là một cửa hàng sửa chữa phải không?\", \"Một số người đề cập rằng họ muốn dùng nó trong các công thức nấu ăn, chẳng hạn như cho vào nước sốt.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 107 trong bài luyện nghe Part 3.\", \"display_text\": \"Wonderful.\"}', '2026-09-15 07:19:42')
