('set-2026-t3-p3-s57', 'set-2026-t3-p3', 57, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%203/audio/47-49.mp3', NULL, NULL, 28.365e0, 29.686e0, 'No, unfortunately.', '[{\"end\": 28.686, \"word\": \"No,\", \"score\": 0.943, \"start\": 28.365, \"posTag\": \"INTJ\"}, {\"end\": 29.686, \"word\": \"unfortunately.\", \"score\": 0.78, \"start\": 28.826, \"posTag\": \"ADV\"}]', '[\"unfortunately\"]', 'Không, tiếc quá.', 'noʊ ʌnfɔːɹtʃənətli', '[\"Cảm ơn bạn.\", \"Chào Gina.\", \"Tàu khởi hành từ Sân ga 12 trong ba phút nữa.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 57 trong bài luyện nghe Part 3.\", \"display_text\": \"No, unfortunately.\"}', '2026-09-15 07:19:47'),
('set-2026-t3-p3-s58', 'set-2026-t3-p3', 58, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%203/audio/47-49.mp3', NULL, NULL, 30.026e0, 31.026e0, 'I must have lost it.', '[{\"end\": 30.086, \"word\": \"I\", \"score\": 0.667, \"start\": 30.026, \"posTag\": \"PRON\"}, {\"end\": 30.326, \"word\": \"must\", \"score\": 0.925, \"start\": 30.146, \"posTag\": \"AUX\"}, {\"end\": 30.486, \"word\": \"have\", \"score\": 0.894, \"start\": 30.366, \"posTag\": \"AUX\"}, {\"end\": 30.886, \"word\": \"lost\", \"score\": 0.813, \"start\": 30.546, \"posTag\": \"VERB\"}, {\"end\": 31.026, \"word\": \"it.\", \"score\": 0.834, \"start\": 30.946, \"posTag\": \"PRON\"}]', '[\"lost\"]', 'Chắc tôi để quên đâu mất rồi.', 'aɪ mʌstɐv lɔst ɪt', '[\"Cô ấy sẽ phải tìm cách khác để đến đó.\", \"Chúng ta ra đó ngay thôi, Sergei.\", \"Đáng tiếc là doanh số của chúng ta vẫn đang tiếp tục giảm.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 58 trong bài luyện nghe Part 3.\", \"display_text\": \"I must have lost it.\"}', '2026-09-15 07:19:47'),
('set-2026-t3-p3-s59', 'set-2026-t3-p3', 59, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%203/audio/47-49.mp3', NULL, NULL, 31.506e0, 31.867e0, 'Hmm.', '[{\"end\": 31.867, \"word\": \"Hmm.\", \"score\": 0.827, \"start\": 31.506, \"posTag\": \"INTJ\"}]', '[\"Hmm\"]', 'Hừm.', 'həm', '[\"Này, bạn có vô tình mang theo ô không?\", \"Họ muốn tiếp thị sản phẩm này cho các đội thể thao cũng như khách hàng cá nhân.\", \"Thực ra, công ty của tôi đã yêu cầu tôi chuyển công tác sang Tây Ban Nha.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 59 trong bài luyện nghe Part 3.\", \"display_text\": \"Hmm.\"}', '2026-09-15 07:19:47')
