('set-2026-t7-p2-s27', 'set-2026-t7-p2', 27, 7, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/13.mp3', NULL, NULL, 8.932e0, 11.976e0, 'I\'ll send you a temporary password.', '[{\"end\": 10.234, \"word\": \"I\'ll\", \"score\": 0.874, \"start\": 10.054, \"posTag\": \"PRON\"}, {\"end\": 10.454, \"word\": \"send\", \"score\": 0.996, \"start\": 10.274, \"posTag\": \"VERB\"}, {\"end\": 10.614, \"word\": \"you\", \"score\": 0.82, \"start\": 10.474, \"posTag\": \"PRON\"}, {\"end\": 10.695, \"word\": \"a\", \"score\": 0.508, \"start\": 10.654, \"posTag\": \"DET\"}, {\"end\": 11.335, \"word\": \"temporary\", \"score\": 0.873, \"start\": 10.755, \"posTag\": \"ADJ\"}, {\"end\": 11.976, \"word\": \"password.\", \"score\": 0.841, \"start\": 11.395, \"posTag\": \"NOUN\"}]', '[\"password\"]', '', 'biː aɪl sɛnd juː ɐ tɛmpɚɹɛɹi pæswɜːd', '[\"Vâng, chúng tôi có.\", \"Cửa của một cửa hàng quần áo đang được chống mở.\", \"Chắc chắn rồi, tôi sẽ đóng khung bức tranh.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 27 trong bài luyện nghe Part 2.\", \"display_text\": \"I\'ll send you a temporary password.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s28', 'set-2026-t7-p2', 28, 7, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/13.mp3', NULL, NULL, 12.917e0, 15.26e0, 'No, he was late.', '[{\"end\": 14.279, \"word\": \"No,\", \"score\": 0.97, \"start\": 13.998, \"posTag\": \"PROPN\"}, {\"end\": 14.699, \"word\": \"he\", \"score\": 0.753, \"start\": 14.579, \"posTag\": \"PRON\"}, {\"end\": 14.879, \"word\": \"was\", \"score\": 0.778, \"start\": 14.739, \"posTag\": \"AUX\"}, {\"end\": 15.26, \"word\": \"late.\", \"score\": 0.965, \"start\": 14.96, \"posTag\": \"ADJ\"}]', '[\"late\"]', '', 'siː noʊ hiː wʌz leɪt', '[\"Tôi rất ngưỡng mộ các tác phẩm của cô, cô Azuma.\", \"Ngoài ra, tôi xin thông báo trước là sẽ có một xe buýt đưa đón chúng ta ở cuối chuyến tham quan để đưa tất cả trở lại bãi đậu xe.\", \"Chào Gabriella.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 28 trong bài luyện nghe Part 2.\", \"display_text\": \"No, he was late.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s29', 'set-2026-t7-p2', 29, 8, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/14.mp3', NULL, NULL, 2.357e0, 4.359e0, 'When does the property manager arrive?', '[{\"end\": 2.517, \"word\": \"When\", \"score\": 0.897, \"start\": 2.357, \"posTag\": \"SCONJ\"}, {\"end\": 2.697, \"word\": \"does\", \"score\": 0.77, \"start\": 2.557, \"posTag\": \"AUX\"}, {\"end\": 2.838, \"word\": \"the\", \"score\": 0.676, \"start\": 2.737, \"posTag\": \"DET\"}, {\"end\": 3.338, \"word\": \"property\", \"score\": 0.84, \"start\": 2.878, \"posTag\": \"NOUN\"}, {\"end\": 3.839, \"word\": \"manager\", \"score\": 0.87, \"start\": 3.378, \"posTag\": \"NOUN\"}, {\"end\": 4.359, \"word\": \"arrive?\", \"score\": 0.889, \"start\": 3.919, \"posTag\": \"NOUN\"}]', '[\"property\"]', '', 'wɛn dʌz ðə pɹɑːpɚɾi mænɪdʒɚɹ ɚɹaɪv', '[\"Tôi có thể dẫn bạn đến đó.\", \"Natalie phụ trách phần đồ dùng.\", \"Tuyệt vời, nhưng hãy chuẩn bị tinh thần cho cái lạnh thấu xương nhé.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 29 trong bài luyện nghe Part 2.\", \"display_text\": \"When does the property manager arrive?\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s30', 'set-2026-t7-p2', 30, 8, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/14.mp3', NULL, NULL, 6.481e0, 7.682e0, 'On Whitmer Boulevard.', '[{\"end\": 6.561, \"word\": \"On\", \"score\": 0.876, \"start\": 6.481, \"posTag\": \"ADP\"}, {\"end\": 7.022, \"word\": \"Whitmer\", \"score\": 0.715, \"start\": 6.621, \"posTag\": \"PROPN\"}, {\"end\": 7.682, \"word\": \"Boulevard.\", \"score\": 0.911, \"start\": 7.062, \"posTag\": \"PROPN\"}]', '[\"Boulevard\"]', '', 'ɔn wɪtmɚ buːlɪvɑːɹd', '[\"Có vẻ như năm nay hội nghị sẽ rất nhiều thông tin bổ ích.\", \"Bạn có thể kiểm tra bảng điện của mình được không?\", \"Thứ Ba tới.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 30 trong bài luyện nghe Part 2.\", \"display_text\": \"On Whitmer Boulevard.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s31', 'set-2026-t7-p2', 31, 8, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/14.mp3', NULL, NULL, 9.745e0, 11.206e0, 'You\'re right, it doesn\'t fit.', '[{\"end\": 9.985, \"word\": \"You\'re\", \"score\": 0.783, \"start\": 9.745, \"posTag\": \"PRON\"}, {\"end\": 10.325, \"word\": \"right,\", \"score\": 0.55, \"start\": 10.065, \"posTag\": \"ADJ\"}, {\"end\": 10.525, \"word\": \"it\", \"score\": 0.958, \"start\": 10.465, \"posTag\": \"PRON\"}, {\"end\": 10.866, \"word\": \"doesn\'t\", \"score\": 0.789, \"start\": 10.585, \"posTag\": \"AUX\"}, {\"end\": 11.206, \"word\": \"fit.\", \"score\": 0.868, \"start\": 10.946, \"posTag\": \"VERB\"}]', '[\"fit\"]', '', 'jʊɹ ɹaɪt ɪt dʌzənt fɪt', '[\"Anh ấy đang kéo một chiếc xe tay đẩy trên lối đi bộ.\", \"Saskia rất có kiến thức về tập luyện và rất nhiều người sử dụng các bài tập trực tuyến của cô ấy.\", \"Một vé khứ hồi.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 31 trong bài luyện nghe Part 2.\", \"display_text\": \"You\'re right, it doesn\'t fit.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s32', 'set-2026-t7-p2', 32, 8, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/14.mp3', NULL, NULL, 12.227e0, 14.089e0, 'At 10 o\'clock.', '[{\"end\": 13.388, \"word\": \"At\", \"score\": 0.512, \"start\": 13.308, \"posTag\": \"ADP\"}, {\"end\": 13.648, \"word\": \"10\", \"score\": 0.598, \"start\": 13.468, \"posTag\": \"NUM\"}, {\"end\": 14.089, \"word\": \"o\'clock.\", \"score\": 0.896, \"start\": 13.688, \"posTag\": \"NOUN\"}]', '[\"o\'clock\"]', '', 'siː æt tɛn əklɑːk', '[\"Chúng tôi cần người chọn địa điểm quay phim phù hợp tại các nhà máy của Five Star, và quảng cáo nói rằng cô có rất nhiều kinh nghiệm tìm kiếm địa điểm công nghiệp.\", \"Hơn 50.000 đô la.\", \"Chúng tôi rất hào hứng được làm việc với ông và chúng tôi đưa ra mức đãi ngộ rất hậu hĩnh.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 32 trong bài luyện nghe Part 2.\", \"display_text\": \"At 10 o\'clock.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s33', 'set-2026-t7-p2', 33, 9, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/15.mp3', NULL, NULL, 2.472e0, 4.813e0, 'Let\'s have dinner at the French restaurant tonight.', '[{\"end\": 2.712, \"word\": \"Let\'s\", \"score\": 0.82, \"start\": 2.472, \"posTag\": \"VERB\"}, {\"end\": 2.912, \"word\": \"have\", \"score\": 0.84, \"start\": 2.752, \"posTag\": \"VERB\"}, {\"end\": 3.232, \"word\": \"dinner\", \"score\": 0.915, \"start\": 2.972, \"posTag\": \"NOUN\"}, {\"end\": 3.372, \"word\": \"at\", \"score\": 0.826, \"start\": 3.272, \"posTag\": \"ADP\"}, {\"end\": 3.492, \"word\": \"the\", \"score\": 0.837, \"start\": 3.412, \"posTag\": \"DET\"}, {\"end\": 3.872, \"word\": \"French\", \"score\": 0.756, \"start\": 3.572, \"posTag\": \"ADJ\"}, {\"end\": 4.433, \"word\": \"restaurant\", \"score\": 0.762, \"start\": 3.953, \"posTag\": \"NOUN\"}, {\"end\": 4.813, \"word\": \"tonight.\", \"score\": 0.876, \"start\": 4.473, \"posTag\": \"NOUN\"}]', '[\"restaurant\"]', '', 'lɛts hæv dɪnɚɹ æt ðə fɹɛntʃ ɹɛstɹɑːnt tənaɪt', '[\"Chúng tôi có các bài đăng hàng tháng về nhiều chủ đề làm vườn và có một bài mới đây về cách trồng hoa hồng.\", \"Một người đàn ông đang trèo lên thang.\", \"Nếu hỏi hành khách, tôi cá là họ sẽ bảo vị trí tiện lợi nhất là càng gần sân ga càng tốt.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 33 trong bài luyện nghe Part 2.\", \"display_text\": \"Let\'s have dinner at the French restaurant tonight.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s34', 'set-2026-t7-p2', 34, 9, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/15.mp3', NULL, NULL, 6.874e0, 8.274e0, 'Okay, I\'ll see you there.', '[{\"end\": 7.234, \"word\": \"Okay,\", \"score\": 0.803, \"start\": 6.874, \"posTag\": \"INTJ\"}, {\"end\": 7.654, \"word\": \"I\'ll\", \"score\": 0.664, \"start\": 7.434, \"posTag\": \"PRON\"}, {\"end\": 7.814, \"word\": \"see\", \"score\": 0.721, \"start\": 7.674, \"posTag\": \"VERB\"}, {\"end\": 7.974, \"word\": \"you\", \"score\": 0.879, \"start\": 7.854, \"posTag\": \"PRON\"}, {\"end\": 8.274, \"word\": \"there.\", \"score\": 0.708, \"start\": 7.994, \"posTag\": \"ADV\"}]', '[\"see\"]', '', 'oʊkeɪ aɪl siː juː ðɛɹ', '[\"Là một làm vườn từng quản lý khuôn viên của nhiều điền trang lịch sử, anh ấy có chuyên môn sâu rộng về những gì đã được trồng vào thời điểm đó.\", \"Tôi gọi để dổi lịch xuất hiện của anh ấy trên chương trình sáng Chủ Nhật.\", \"Có lẽ bây giờ họ sẽ cuối cùng bắt đầu làm điều đó.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 34 trong bài luyện nghe Part 2.\", \"display_text\": \"Okay, I\'ll see you there.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s35', 'set-2026-t7-p2', 35, 9, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/15.mp3', NULL, NULL, 9.195e0, 12.096e0, 'I\'d like to buy some new cookware.', '[{\"end\": 10.455, \"word\": \"I\'d\", \"score\": 0.782, \"start\": 10.295, \"posTag\": \"PRON\"}, {\"end\": 10.675, \"word\": \"like\", \"score\": 0.952, \"start\": 10.475, \"posTag\": \"VERB\"}, {\"end\": 10.795, \"word\": \"to\", \"score\": 0.639, \"start\": 10.715, \"posTag\": \"PART\"}, {\"end\": 11.035, \"word\": \"buy\", \"score\": 0.639, \"start\": 10.855, \"posTag\": \"VERB\"}, {\"end\": 11.275, \"word\": \"some\", \"score\": 0.869, \"start\": 11.115, \"posTag\": \"DET\"}, {\"end\": 11.495, \"word\": \"new\", \"score\": 0.923, \"start\": 11.335, \"posTag\": \"ADJ\"}, {\"end\": 12.096, \"word\": \"cookware.\", \"score\": 0.817, \"start\": 11.575, \"posTag\": \"NOUN\"}]', '[\"cookware\"]', '', 'biː aɪd laɪk tə baɪ sʌm nuː kʊkwɛɹ', '[\"Vậy bây giờ chúng ta cần quyết định vị trí đặt giá để xe.\", \"Có, tôi nghe bạn rất rõ, cảm ơn bạn.\", \"Xin chào, tôi là Heather Ross gọi từ Công viên Giải trí Denville.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 35 trong bài luyện nghe Part 2.\", \"display_text\": \"I\'d like to buy some new cookware.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s36', 'set-2026-t7-p2', 36, 9, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/15.mp3', NULL, NULL, 13.016e0, 15.577e0, 'Here\'s a copy of the agreement.', '[{\"end\": 14.256, \"word\": \"Here\'s\", \"score\": 0.727, \"start\": 14.016, \"posTag\": \"ADV\"}, {\"end\": 14.336, \"word\": \"a\", \"score\": 0.527, \"start\": 14.296, \"posTag\": \"DET\"}, {\"end\": 14.757, \"word\": \"copy\", \"score\": 0.908, \"start\": 14.397, \"posTag\": \"NOUN\"}, {\"end\": 14.877, \"word\": \"of\", \"score\": 0.672, \"start\": 14.797, \"posTag\": \"ADP\"}, {\"end\": 15.037, \"word\": \"the\", \"score\": 0.773, \"start\": 14.917, \"posTag\": \"DET\"}, {\"end\": 15.577, \"word\": \"agreement.\", \"score\": 0.854, \"start\": 15.097, \"posTag\": \"NOUN\"}]', '[\"agreement\"]', '', 'siː hɪɹz ɐ kɑːpi ʌvðɪ ɐɡɹiːmənt', '[\"Đó là chiếc cặp màu đen.\", \"Chúng ta vừa nhận được một đơn hàng gấp từ Great Fitness.\", \"Nếu bạn lật sang trang 4, bạn sẽ thấy bảng chi tiết chi phí.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 36 trong bài luyện nghe Part 2.\", \"display_text\": \"Here\'s a copy of the agreement.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s37', 'set-2026-t7-p2', 37, 10, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/16.mp3', NULL, NULL, 2.635e0, 4.678e0, 'Who\'s supervising the production line?', '[{\"end\": 2.875, \"word\": \"Who\'s\", \"score\": 0.844, \"start\": 2.635, \"posTag\": \"PRON\"}, {\"end\": 3.656, \"word\": \"supervising\", \"score\": 0.946, \"start\": 2.935, \"posTag\": \"AUX\"}, {\"end\": 3.776, \"word\": \"the\", \"score\": 0.831, \"start\": 3.696, \"posTag\": \"DET\"}, {\"end\": 4.317, \"word\": \"production\", \"score\": 0.881, \"start\": 3.817, \"posTag\": \"NOUN\"}, {\"end\": 4.678, \"word\": \"line?\", \"score\": 0.874, \"start\": 4.357, \"posTag\": \"NOUN\"}]', '[\"production\"]', '', 'huːz suːpɚvaɪzɪŋ ðə pɹədʌkʃən laɪn', '[\"Thực ra, tôi vừa mới kiểm tra trò chơi sáng nay.\", \"Tại sao ở sảnh lại không có cuốn brochure nào thế?\", \"Đến sảnh, tôi nghĩ vậy.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 37 trong bài luyện nghe Part 2.\", \"display_text\": \"Who\'s supervising the production line?\"}', '2026-09-15 07:19:57')
