('set-2026-t7-p2-s94', 'set-2026-t7-p2', 94, 24, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/30.mp3', NULL, NULL, 7.683e0, 10.467e0, 'But I\'m going to London.', '[{\"end\": 7.863, \"word\": \"But\", \"score\": 0.839, \"start\": 7.683, \"posTag\": \"CCONJ\"}, {\"end\": 8.143, \"word\": \"I\'m\", \"score\": 0.866, \"start\": 7.983, \"posTag\": \"PRON\"}, {\"end\": 8.524, \"word\": \"going\", \"score\": 0.791, \"start\": 8.244, \"posTag\": \"VERB\"}, {\"end\": 8.684, \"word\": \"to\", \"score\": 0.75, \"start\": 8.584, \"posTag\": \"ADP\"}, {\"end\": 10.467, \"word\": \"London.\", \"score\": 0.9, \"start\": 8.764, \"posTag\": \"PROPN\"}]', '[\"London\"]', '', 'bʌt aɪm ɡoʊɪŋ tə lʌndən', '[\"Tiến sĩ Macmillan, tôi gọi từ Phòng Nhân sự.\", \"Chúng đắt quá.\", \"Có truy cập internet miễn phí không?\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 94 trong bài luyện nghe Part 2.\", \"display_text\": \"But I\'m going to London.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s95', 'set-2026-t7-p2', 95, 24, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/30.mp3', NULL, NULL, 11.248e0, 13.952e0, 'Turn left at the light, please.', '[{\"end\": 11.468, \"word\": \"Turn\", \"score\": 0.869, \"start\": 11.248, \"posTag\": \"NOUN\"}, {\"end\": 11.769, \"word\": \"left\", \"score\": 0.889, \"start\": 11.529, \"posTag\": \"VERB\"}, {\"end\": 11.909, \"word\": \"at\", \"score\": 0.822, \"start\": 11.829, \"posTag\": \"ADP\"}, {\"end\": 12.009, \"word\": \"the\", \"score\": 0.826, \"start\": 11.929, \"posTag\": \"DET\"}, {\"end\": 12.29, \"word\": \"light,\", \"score\": 0.929, \"start\": 12.049, \"posTag\": \"NOUN\"}, {\"end\": 13.952, \"word\": \"please.\", \"score\": 0.829, \"start\": 12.35, \"posTag\": \"INTJ\"}]', '[\"light\"]', '', 'tɜːn lɛft æt ðə laɪt pliːz', '[\"Nghe nói anh ấy dự định nghỉ hưu vào tháng tới.\", \"Chỉ cần tải ứng dụng Lake Point City xuống điện thoại di động của bạn.\", \"Ồ, chỉ cách đây vài phút đi bộ thôi.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 95 trong bài luyện nghe Part 2.\", \"display_text\": \"Turn left at the light, please.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s96', 'set-2026-t7-p2', 96, 24, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/30.mp3', NULL, NULL, 14.733e0, 15.755e0, 'An email update.', '[{\"end\": 14.814, \"word\": \"An\", \"score\": 0.803, \"start\": 14.733, \"posTag\": \"DET\"}, {\"end\": 15.334, \"word\": \"email\", \"score\": 0.747, \"start\": 14.974, \"posTag\": \"NOUN\"}, {\"end\": 15.755, \"word\": \"update.\", \"score\": 0.981, \"start\": 15.374, \"posTag\": \"NOUN\"}]', '[\"update\"]', '', 'ɐn iːmeɪl ʌpdeɪt', '[\"Và thật may mắn cho chúng ta, dự báo thời tiết hôm nay có nắng đan xen mây và không có mưa.\", \"Một người đàn ông đang bỏ một món đồ vào thùng rác.\", \"Nó được giảm giá.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 96 trong bài luyện nghe Part 2.\", \"display_text\": \"An email update.\"}', '2026-09-15 07:19:57'),
('set-2026-t7-p2-s97', 'set-2026-t7-p2', 97, 25, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/31.mp3', NULL, NULL, 2.493e0, 4.995e0, 'Won\'t theater tickets become available later today?', '[{\"end\": 2.753, \"word\": \"Won\'t\", \"score\": 0.815, \"start\": 2.493, \"posTag\": \"AUX\"}, {\"end\": 3.174, \"word\": \"theater\", \"score\": 0.539, \"start\": 2.833, \"posTag\": \"NOUN\"}, {\"end\": 3.574, \"word\": \"tickets\", \"score\": 0.558, \"start\": 3.214, \"posTag\": \"NOUN\"}, {\"end\": 3.874, \"word\": \"become\", \"score\": 0.921, \"start\": 3.614, \"posTag\": \"VERB\"}, {\"end\": 4.355, \"word\": \"available\", \"score\": 0.822, \"start\": 3.914, \"posTag\": \"ADJ\"}, {\"end\": 4.655, \"word\": \"later\", \"score\": 0.943, \"start\": 4.375, \"posTag\": \"ADV\"}, {\"end\": 4.995, \"word\": \"today?\", \"score\": 0.79, \"start\": 4.695, \"posTag\": \"NOUN\"}]', '[\"become\", \"today\"]', '', 'woʊnt θiəɾɚ tɪkɪts bɪkʌm ɐveɪləbəl leɪɾɚ tədeɪ', '[\"Anh/chị có giữ hóa đơn không ạ?\", \"Thay mặt cho Sở Giao thông vận tải, tôi xin trình bày một đề xuất tài trợ việc thay thế toàn bộ 350 nhà chờ xe buýt trong thành phố của chúng ta.\", \"Nó đẹp quá.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 97 trong bài luyện nghe Part 2.\", \"display_text\": \"Won\'t theater tickets become available later today?\"}', '2026-09-15 07:19:57'),
