('set-2026-t7-p4-s5', 'set-2026-t7-p4', 5, 1, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/71-73.mp3', NULL, NULL, 31.038e0, 32.698e0, 'I\'d like to show you how it works.', '[{\"end\": 31.198, \"word\": \"I\'d\", \"score\": 0.687, \"start\": 31.038, \"posTag\": \"PRON\"}, {\"end\": 31.418, \"word\": \"like\", \"score\": 0.912, \"start\": 31.238, \"posTag\": \"VERB\"}, {\"end\": 31.538, \"word\": \"to\", \"score\": 0.558, \"start\": 31.458, \"posTag\": \"PART\"}, {\"end\": 31.778, \"word\": \"show\", \"score\": 0.904, \"start\": 31.598, \"posTag\": \"VERB\"}, {\"end\": 31.938, \"word\": \"you\", \"score\": 0.755, \"start\": 31.818, \"posTag\": \"PRON\"}, {\"end\": 32.118, \"word\": \"how\", \"score\": 0.861, \"start\": 31.978, \"posTag\": \"SCONJ\"}, {\"end\": 32.258, \"word\": \"it\", \"score\": 0.816, \"start\": 32.178, \"posTag\": \"PRON\"}, {\"end\": 32.698, \"word\": \"works.\", \"score\": 0.846, \"start\": 32.298, \"posTag\": \"VERB\"}]', '[\"like\", \"works\"]', '', 'aɪd laɪk tə ʃoʊ juː haʊ ɪt wɜːks', '[\"Điều đó sẽ rất hữu ích cho công ty chúng tôi.\", \"Để tôi gọi một đồng nghiệp giúp bạn nhé.\", \"Khoảng một tháng trước, tôi đã đặt mua một trong những máy trò chơi điện tử mới của các bạn, Space Defenders.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 5 trong bài luyện nghe Part 4.\", \"display_text\": \"I\'d like to show you how it works.\"}', '2026-09-15 07:19:58'),
('set-2026-t7-p4-s6', 'set-2026-t7-p4', 6, 1, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%207/audio/71-73.mp3', NULL, NULL, 33.158e0, 34.759e0, 'Let\'s go look at a machine now.', '[{\"end\": 33.378, \"word\": \"Let\'s\", \"score\": 0.903, \"start\": 33.158, \"posTag\": \"VERB\"}, {\"end\": 33.579, \"word\": \"go\", \"score\": 0.782, \"start\": 33.418, \"posTag\": \"VERB\"}, {\"end\": 33.859, \"word\": \"look\", \"score\": 0.738, \"start\": 33.659, \"posTag\": \"VERB\"}, {\"end\": 33.939, \"word\": \"at\", \"score\": 0.76, \"start\": 33.879, \"posTag\": \"ADP\"}, {\"end\": 34.039, \"word\": \"a\", \"score\": 0.5, \"start\": 33.999, \"posTag\": \"DET\"}, {\"end\": 34.439, \"word\": \"machine\", \"score\": 0.749, \"start\": 34.079, \"posTag\": \"NOUN\"}, {\"end\": 34.759, \"word\": \"now.\", \"score\": 0.973, \"start\": 34.499, \"posTag\": \"ADV\"}]', '[\"Let\'s\", \"machine\"]', '', 'lɛts ɡoʊ lʊk æɾə məʃiːn naʊ', '[\"Anh ấy đang đặt đĩa lên bàn ăn.\", \"Tôi biết chứ, nhưng Great Fitness đặt hàng chỗ mình suốt mà.\", \"Mười tám tháng trước, chúng tôi đã thuê một công ty để xác định xem việc nâng cấp này có khả thi đối với các đoàn tàu của mình hay không.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 6 trong bài luyện nghe Part 4.\", \"display_text\": \"Let\'s go look at a machine now.\"}', '2026-09-15 07:19:58'),
