('set-2026-t8-p2-s13', 'set-2026-t8-p2', 13, 4, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/10.mp3', NULL, NULL, 2.092e0, 6.053e0, 'Does Dr. Cao schedule appointments in the morning or in the afternoon?', '[{\"end\": 2.292, \"word\": \"Does\", \"score\": 0.779, \"start\": 2.092, \"posTag\": \"VERB\"}, {\"end\": 2.652, \"word\": \"Dr.\", \"score\": 0.829, \"start\": 2.332, \"posTag\": \"PROPN\"}, {\"end\": 3.112, \"word\": \"Cao\", \"score\": 0.622, \"start\": 2.712, \"posTag\": \"PROPN\"}, {\"end\": 3.632, \"word\": \"schedule\", \"score\": 0.793, \"start\": 3.132, \"posTag\": \"NOUN\"}, {\"end\": 4.193, \"word\": \"appointments\", \"score\": 0.883, \"start\": 3.672, \"posTag\": \"NOUN\"}, {\"end\": 4.333, \"word\": \"in\", \"score\": 0.7, \"start\": 4.253, \"posTag\": \"ADP\"}, {\"end\": 4.453, \"word\": \"the\", \"score\": 0.883, \"start\": 4.373, \"posTag\": \"DET\"}, {\"end\": 4.873, \"word\": \"morning\", \"score\": 0.847, \"start\": 4.513, \"posTag\": \"NOUN\"}, {\"end\": 5.133, \"word\": \"or\", \"score\": 0.787, \"start\": 5.033, \"posTag\": \"CCONJ\"}, {\"end\": 5.273, \"word\": \"in\", \"score\": 0.992, \"start\": 5.213, \"posTag\": \"ADP\"}, {\"end\": 5.413, \"word\": \"the\", \"score\": 0.673, \"start\": 5.313, \"posTag\": \"DET\"}, {\"end\": 6.053, \"word\": \"afternoon?\", \"score\": 0.767, \"start\": 5.513, \"posTag\": \"NOUN\"}]', '[\"appointments\", \"morning\", \"afternoon\"]', '', 'dʌz dɑːktɚ kaʊ skɛdʒuːl ɐpɔɪntmənts ɪnðə mɔːɹnɪŋ ɔːɹ ɪnðɪ æftɚnuːn', '[\"50.\", \"Còn chỗ ngồi nào không?\", \"Tôi biết chứ, nhưng Great Fitness đặt hàng chỗ mình suốt mà.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 13 trong bài luyện nghe Part 2.\", \"display_text\": \"Does Dr. Cao schedule appointments in the morning or in the afternoon?\"}', '2026-09-15 07:19:59'),
('set-2026-t8-p2-s14', 'set-2026-t8-p2', 14, 4, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/10.mp3', NULL, NULL, 8.234e0, 9.595e0, 'She leaves at noon.', '[{\"end\": 8.434, \"word\": \"She\", \"score\": 0.825, \"start\": 8.234, \"posTag\": \"PRON\"}, {\"end\": 8.955, \"word\": \"leaves\", \"score\": 0.743, \"start\": 8.514, \"posTag\": \"VERB\"}, {\"end\": 9.155, \"word\": \"at\", \"score\": 0.724, \"start\": 9.055, \"posTag\": \"ADP\"}, {\"end\": 9.595, \"word\": \"noon.\", \"score\": 0.893, \"start\": 9.255, \"posTag\": \"NOUN\"}]', '[\"noon\"]', '', 'ʃiː liːvz æt nuːn', '[\"Bạn để hóa đơn của Stanson Incorporated ở đâu rồi?\", \"Đúng vậy, và vì du lịch mùa đông gần đây đã tăng lên, chúng tôi muốn mở rộng mặt bằng để có thể chứa được nhiều hàng hóa hơn.\", \"Đó là sự kết hợp tuyệt vời để dành thời gian ở ngoài sân một cách thoải mái.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 14 trong bài luyện nghe Part 2.\", \"display_text\": \"She leaves at noon.\"}', '2026-09-15 07:19:59'),
