('set-2026-t8-p2-s55', 'set-2026-t8-p2', 55, 14, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/20.mp3', NULL, NULL, 10.421e0, 12.724e0, 'Yes, we already have a lot of orders.', '[{\"end\": 10.782, \"word\": \"Yes,\", \"score\": 0.892, \"start\": 10.421, \"posTag\": \"INTJ\"}, {\"end\": 11.142, \"word\": \"we\", \"score\": 0.9, \"start\": 10.982, \"posTag\": \"PRON\"}, {\"end\": 11.603, \"word\": \"already\", \"score\": 0.743, \"start\": 11.202, \"posTag\": \"ADV\"}, {\"end\": 11.783, \"word\": \"have\", \"score\": 0.928, \"start\": 11.643, \"posTag\": \"VERB\"}, {\"end\": 11.863, \"word\": \"a\", \"score\": 0.5, \"start\": 11.823, \"posTag\": \"DET\"}, {\"end\": 12.203, \"word\": \"lot\", \"score\": 0.899, \"start\": 11.943, \"posTag\": \"NOUN\"}, {\"end\": 12.283, \"word\": \"of\", \"score\": 0.75, \"start\": 12.223, \"posTag\": \"ADP\"}, {\"end\": 12.724, \"word\": \"orders.\", \"score\": 0.86, \"start\": 12.403, \"posTag\": \"NOUN\"}]', '[\"lot\", \"orders\"]', '', 'jɛs wiː ɔːlɹɛdi hæv ɐ lɑːt ʌv ɔːɹdɚz', '[\"Muộn nhất là vào thứ Ba.\", \"Tôi phải xem lại lịch của mình đã.\", \"Chúng ta đã bận rộn hơn bao giờ hết kể từ khi bắt đầu làm việc với True Valley Industries.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 55 trong bài luyện nghe Part 2.\", \"display_text\": \"Yes, we already have a lot of orders.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p2-s56', 'set-2026-t8-p2', 56, 14, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/20.mp3', NULL, NULL, 13.725e0, 15.887e0, 'He\'ll meet you next week.', '[{\"end\": 14.946, \"word\": \"He\'ll\", \"score\": 0.919, \"start\": 14.726, \"posTag\": \"PRON\"}, {\"end\": 15.126, \"word\": \"meet\", \"score\": 0.86, \"start\": 14.966, \"posTag\": \"VERB\"}, {\"end\": 15.306, \"word\": \"you\", \"score\": 0.871, \"start\": 15.146, \"posTag\": \"PRON\"}, {\"end\": 15.587, \"word\": \"next\", \"score\": 0.765, \"start\": 15.366, \"posTag\": \"ADJ\"}, {\"end\": 15.887, \"word\": \"week.\", \"score\": 0.978, \"start\": 15.667, \"posTag\": \"NOUN\"}]', '[\"week\"]', '', 'siː hiːl miːt juː nɛkst wiːk', '[\"Sylvia, tôi vừa nghe nói thị trưởng thành phố sẽ tổ chức họp báo chiều nay.\", \"Tôi chưa nhận được, nhưng hôm nay tôi sẽ gọi cho bên in ấn để hỏi tiến độ.\", \"Bạn đã gọi đến Dịch vụ Sửa chữa Select.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 56 trong bài luyện nghe Part 2.\", \"display_text\": \"He\'ll meet you next week.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p2-s57', 'set-2026-t8-p2', 57, 15, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/21.mp3', NULL, NULL, 2.553e0, 4.995e0, 'How many books are in this mystery series?', '[{\"end\": 2.713, \"word\": \"How\", \"score\": 0.985, \"start\": 2.553, \"posTag\": \"SCONJ\"}, {\"end\": 3.053, \"word\": \"many\", \"score\": 0.82, \"start\": 2.773, \"posTag\": \"ADJ\"}, {\"end\": 3.394, \"word\": \"books\", \"score\": 0.772, \"start\": 3.133, \"posTag\": \"NOUN\"}, {\"end\": 3.594, \"word\": \"are\", \"score\": 0.866, \"start\": 3.474, \"posTag\": \"AUX\"}, {\"end\": 3.794, \"word\": \"in\", \"score\": 0.871, \"start\": 3.694, \"posTag\": \"ADP\"}, {\"end\": 4.014, \"word\": \"this\", \"score\": 0.869, \"start\": 3.834, \"posTag\": \"DET\"}, {\"end\": 4.514, \"word\": \"mystery\", \"score\": 0.803, \"start\": 4.114, \"posTag\": \"NOUN\"}, {\"end\": 4.995, \"word\": \"series?\", \"score\": 0.892, \"start\": 4.554, \"posTag\": \"NOUN\"}]', '[\"series\"]', '', 'haʊ mɛni bʊks ɑːɹ ɪn ðɪs mɪstɚɹi sɪɹiz', '[\"À, máy sấy quần áo cần hai khoảng trống, nên rất có thể chúng ta phải lắp một thứ gọi là bảng phụ.\", \"Chúng ở trong bãi đậu xe.\", \"Cô Stewart, tôi là Rodrigo Gomez, Chủ tịch của Gomez & Sons.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 57 trong bài luyện nghe Part 2.\", \"display_text\": \"How many books are in this mystery series?\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p2-s58', 'set-2026-t8-p2', 58, 15, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/21.mp3', NULL, NULL, 6.996e0, 7.737e0, 'There are seven.', '[{\"end\": 7.196, \"word\": \"There\", \"score\": 0.708, \"start\": 6.996, \"posTag\": \"PRON\"}, {\"end\": 7.336, \"word\": \"are\", \"score\": 0.717, \"start\": 7.236, \"posTag\": \"VERB\"}, {\"end\": 7.737, \"word\": \"seven.\", \"score\": 0.844, \"start\": 7.377, \"posTag\": \"NUM\"}]', '[\"seven\"]', '', 'ðɛɹɑːɹ sɛvən', '[\"Không có gì.\", \"Thực tế, bạn sẽ là một trong những cư dân đầu tiên nếu quyết định chuyển đến đây.\", \"Một người đàn ông đang buộc giày.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 58 trong bài luyện nghe Part 2.\", \"display_text\": \"There are seven.\"}', '2026-09-15 07:20:00'),
