('set-2026-t8-p2-s78', 'set-2026-t8-p2', 78, 20, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/26.mp3', NULL, NULL, 5.653e0, 8.394e0, 'Sure, if you can wait a minute.', '[{\"end\": 6.973, \"word\": \"Sure,\", \"score\": 0.805, \"start\": 6.653, \"posTag\": \"INTJ\"}, {\"end\": 7.413, \"word\": \"if\", \"score\": 0.993, \"start\": 7.333, \"posTag\": \"SCONJ\"}, {\"end\": 7.614, \"word\": \"you\", \"score\": 0.892, \"start\": 7.493, \"posTag\": \"PRON\"}, {\"end\": 7.794, \"word\": \"can\", \"score\": 0.837, \"start\": 7.634, \"posTag\": \"AUX\"}, {\"end\": 8.014, \"word\": \"wait\", \"score\": 0.795, \"start\": 7.834, \"posTag\": \"VERB\"}, {\"end\": 8.074, \"word\": \"a\", \"score\": 0.999, \"start\": 8.054, \"posTag\": \"DET\"}, {\"end\": 8.394, \"word\": \"minute.\", \"score\": 0.83, \"start\": 8.114, \"posTag\": \"NOUN\"}]', '[\"minute\"]', '', 'ɐ ʃʊɹ ɪf juː kæn weɪt ɐ mɪnɪt', '[\"Họ đang rời khỏi nhà hàng.\", \"Ồ, tôi nghĩ chúng ta nên chuyển thông tin đó ra khỏi trang Giới thiệu và tạo một trang riêng cho phần chỉ đường và thông tin đậu xe.\", \"Không, tôi chưa từng đến đó bao giờ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 78 trong bài luyện nghe Part 2.\", \"display_text\": \"Sure, if you can wait a minute.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p2-s79', 'set-2026-t8-p2', 79, 20, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/26.mp3', NULL, NULL, 9.294e0, 11.735e0, 'It\'s not very comfortable.', '[{\"end\": 10.595, \"word\": \"It\'s\", \"score\": 0.816, \"start\": 10.454, \"posTag\": \"PRON\"}, {\"end\": 10.855, \"word\": \"not\", \"score\": 0.766, \"start\": 10.655, \"posTag\": \"PART\"}, {\"end\": 11.135, \"word\": \"very\", \"score\": 0.888, \"start\": 10.895, \"posTag\": \"ADV\"}, {\"end\": 11.735, \"word\": \"comfortable.\", \"score\": 0.878, \"start\": 11.195, \"posTag\": \"ADJ\"}]', '[\"comfortable\"]', '', 'biː ɪts nɑːt vɛɹi kʌmftəbəl', '[\"Ừ, tôi cũng không ngạc nhiên lắm.\", \"Nhóm bán hàng biết cách sử dụng phần mềm theo dõi phải không?\", \"Tôi có thể gửi nó cho cô vào chiều nay.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 79 trong bài luyện nghe Part 2.\", \"display_text\": \"It\'s not very comfortable.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p2-s80', 'set-2026-t8-p2', 80, 20, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/26.mp3', NULL, NULL, 12.655e0, 14.956e0, 'That\'s a good sofa.', '[{\"end\": 13.976, \"word\": \"That\'s\", \"score\": 0.888, \"start\": 13.676, \"posTag\": \"PRON\"}, {\"end\": 14.056, \"word\": \"a\", \"score\": 0.499, \"start\": 14.016, \"posTag\": \"DET\"}, {\"end\": 14.396, \"word\": \"good\", \"score\": 0.894, \"start\": 14.156, \"posTag\": \"ADJ\"}, {\"end\": 14.956, \"word\": \"sofa.\", \"score\": 0.983, \"start\": 14.496, \"posTag\": \"NOUN\"}]', '[\"sofa\"]', '', 'siː ðæts ɐ ɡʊd soʊfə', '[\"Tôi sẽ lấy món chính, cảm ơn.\", \"Quản lý trực tiếp của bạn sẽ trao đổi với bạn về cách tính khoản tiền này và thời điểm bạn nhận được nó.\", \"Đáng tiếc là không.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 80 trong bài luyện nghe Part 2.\", \"display_text\": \"That\'s a good sofa.\"}', '2026-09-15 07:20:00'),
