('set-2026-t8-p2-s82', 'set-2026-t8-p2', 82, 21, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/27.mp3', NULL, NULL, 6.899e0, 8.341e0, 'The meal was delicious.', '[{\"end\": 7.02, \"word\": \"The\", \"score\": 0.857, \"start\": 6.899, \"posTag\": \"DET\"}, {\"end\": 7.38, \"word\": \"meal\", \"score\": 0.905, \"start\": 7.08, \"posTag\": \"NOUN\"}, {\"end\": 7.62, \"word\": \"was\", \"score\": 0.723, \"start\": 7.44, \"posTag\": \"AUX\"}, {\"end\": 8.341, \"word\": \"delicious.\", \"score\": 0.958, \"start\": 7.7, \"posTag\": \"ADJ\"}]', '[\"delicious\"]', '', 'ðə miːl wʌz dᵻlɪʃəs', '[\"Chúng ta sẽ cần được phê duyệt để bắt đầu một chương trình như vậy.\", \"Một công nhân đang kẻ các đường trên sàn nhà.\", \"Tôi muốn trực tiếp xin lỗi vì những vấn đề nhà hàng của cô gặp phải khi sử dụng ô che sân ngoài trời của chúng tôi.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 82 trong bài luyện nghe Part 2.\", \"display_text\": \"The meal was delicious.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p2-s83', 'set-2026-t8-p2', 83, 21, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/27.mp3', NULL, NULL, 10.424e0, 11.765e0, 'In the drawer next to the sink.', '[{\"end\": 10.504, \"word\": \"In\", \"score\": 0.881, \"start\": 10.424, \"posTag\": \"ADP\"}, {\"end\": 10.624, \"word\": \"the\", \"score\": 0.833, \"start\": 10.544, \"posTag\": \"DET\"}, {\"end\": 10.944, \"word\": \"drawer\", \"score\": 0.897, \"start\": 10.664, \"posTag\": \"NOUN\"}, {\"end\": 11.185, \"word\": \"next\", \"score\": 0.805, \"start\": 10.984, \"posTag\": \"ADV\"}, {\"end\": 11.345, \"word\": \"to\", \"score\": 0.816, \"start\": 11.225, \"posTag\": \"ADP\"}, {\"end\": 11.445, \"word\": \"the\", \"score\": 0.997, \"start\": 11.385, \"posTag\": \"DET\"}, {\"end\": 11.765, \"word\": \"sink.\", \"score\": 0.937, \"start\": 11.505, \"posTag\": \"NOUN\"}]', '[\"drawer\"]', '', 'ɪnðə dɹɔːɹ nɛkst tə ðə sɪŋk', '[\"Tôi rất vui khi thấy mọi người có mặt sớm theo yêu cầu.\", \"Claudia Hoffman.\", \"Vì bạn mới đến thành phố này, chắc bạn đang tự hỏi đâu là tuyến xe buýt tốt nhất để đi.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 83 trong bài luyện nghe Part 2.\", \"display_text\": \"In the drawer next to the sink.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p2-s84', 'set-2026-t8-p2', 84, 21, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/27.mp3', NULL, NULL, 12.646e0, 14.629e0, 'That\'s very kind.', '[{\"end\": 13.888, \"word\": \"That\'s\", \"score\": 0.853, \"start\": 13.648, \"posTag\": \"PRON\"}, {\"end\": 14.228, \"word\": \"very\", \"score\": 0.751, \"start\": 13.948, \"posTag\": \"ADV\"}, {\"end\": 14.629, \"word\": \"kind.\", \"score\": 0.992, \"start\": 14.308, \"posTag\": \"ADJ\"}]', '[\"kind\"]', '', 'siː ðæts vɛɹi kaɪnd', '[\"Một chiếc đèn và một số giấy tờ đang ở trên bàn làm việc.\", \"Nó đã được dời lịch lại rồi.\", \"Một số hòn đá đã được chất lên một tấm lót pallet.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 84 trong bài luyện nghe Part 2.\", \"display_text\": \"That\'s very kind.\"}', '2026-09-15 07:20:00'),
