('set-2026-t8-p3-s12', 'set-2026-t8-p3', 12, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/35-37.mp3', NULL, NULL, 14.487e0, 16.328e0, 'I haven\'t opened the refrigerator yet.', '[{\"end\": 14.527, \"word\": \"I\", \"score\": 0.999, \"start\": 14.487, \"posTag\": \"PRON\"}, {\"end\": 14.868, \"word\": \"haven\'t\", \"score\": 0.848, \"start\": 14.567, \"posTag\": \"AUX\"}, {\"end\": 15.188, \"word\": \"opened\", \"score\": 0.678, \"start\": 14.948, \"posTag\": \"VERB\"}, {\"end\": 15.308, \"word\": \"the\", \"score\": 0.924, \"start\": 15.228, \"posTag\": \"DET\"}, {\"end\": 16.028, \"word\": \"refrigerator\", \"score\": 0.909, \"start\": 15.348, \"posTag\": \"NOUN\"}, {\"end\": 16.328, \"word\": \"yet.\", \"score\": 0.924, \"start\": 16.068, \"posTag\": \"ADV\"}]', '[\"opened\", \"refrigerator\"]', '', 'aɪ hævənt oʊpənd ðə ɹᵻfɹɪdʒɚɹeɪɾɚ jɛt', '[\"Mấy tập tem từ bưu điện.\", \"Ba tháng một lần.\", \"Nó có giá trị đổi lấy một vé vào cửa miễn phí tại bảo tàng địa phương.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 12 trong bài luyện nghe Part 3.\", \"display_text\": \"I haven\'t opened the refrigerator yet.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s13', 'set-2026-t8-p3', 13, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/35-37.mp3', NULL, NULL, 16.628e0, 16.948e0, 'Why?', '[{\"end\": 16.948, \"word\": \"Why?\", \"score\": 0.873, \"start\": 16.628, \"posTag\": \"SCONJ\"}]', '[\"Why\"]', '', 'waɪ', '[\"Cô ấy đang lên xe taxi.\", \"Chẳng phải cậu sống cạnh cửa hàng bán hoa sao?\", \"Tại sao tiệc chiêu đãi lại diễn ra ở một địa điểm khác?\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 13 trong bài luyện nghe Part 3.\", \"display_text\": \"Why?\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s14', 'set-2026-t8-p3', 14, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/35-37.mp3', NULL, NULL, 17.448e0, 20.068e0, 'Well, the temperature is off by a few degrees.', '[{\"end\": 17.788, \"word\": \"Well,\", \"score\": 0.916, \"start\": 17.448, \"posTag\": \"INTJ\"}, {\"end\": 18.088, \"word\": \"the\", \"score\": 0.96, \"start\": 17.988, \"posTag\": \"DET\"}, {\"end\": 18.668, \"word\": \"temperature\", \"score\": 0.833, \"start\": 18.168, \"posTag\": \"NOUN\"}, {\"end\": 18.828, \"word\": \"is\", \"score\": 0.737, \"start\": 18.748, \"posTag\": \"AUX\"}, {\"end\": 19.028, \"word\": \"off\", \"score\": 0.941, \"start\": 18.888, \"posTag\": \"ADV\"}, {\"end\": 19.228, \"word\": \"by\", \"score\": 0.832, \"start\": 19.068, \"posTag\": \"ADP\"}, {\"end\": 19.288, \"word\": \"a\", \"score\": 0.48, \"start\": 19.248, \"posTag\": \"DET\"}, {\"end\": 19.528, \"word\": \"few\", \"score\": 0.89, \"start\": 19.348, \"posTag\": \"ADJ\"}, {\"end\": 20.068, \"word\": \"degrees.\", \"score\": 0.847, \"start\": 19.588, \"posTag\": \"NOUN\"}]', '[\"temperature\", \"off\", \"degrees\"]', '', 'wɛl ðə tɛmpɹɪtʃɚɹ ɪz ɔf baɪ ɐ fjuː dᵻɡɹiːz', '[\"Những bức tranh mà các học viên tạo ra lần trước thật phi thường.\", \"Tại sao bạn lại ở văn phòng ăn trưa vậy?\", \"Hãy mua vé điện tử thông qua ứng dụng di động luôn nhé.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 14 trong bài luyện nghe Part 3.\", \"display_text\": \"Well, the temperature is off by a few degrees.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s15', 'set-2026-t8-p3', 15, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/35-37.mp3', NULL, NULL, 20.488e0, 25.669e0, 'We just purchased that refrigerator last month, so it should be in perfect working order.', '[{\"end\": 20.669, \"word\": \"We\", \"score\": 0.732, \"start\": 20.488, \"posTag\": \"PRON\"}, {\"end\": 20.989, \"word\": \"just\", \"score\": 0.831, \"start\": 20.729, \"posTag\": \"ADV\"}, {\"end\": 21.569, \"word\": \"purchased\", \"score\": 0.768, \"start\": 21.109, \"posTag\": \"VERB\"}, {\"end\": 21.749, \"word\": \"that\", \"score\": 0.815, \"start\": 21.609, \"posTag\": \"DET\"}, {\"end\": 22.509, \"word\": \"refrigerator\", \"score\": 0.87, \"start\": 21.829, \"posTag\": \"NOUN\"}, {\"end\": 22.769, \"word\": \"last\", \"score\": 0.793, \"start\": 22.549, \"posTag\": \"ADJ\"}, {\"end\": 23.109, \"word\": \"month,\", \"score\": 0.88, \"start\": 22.849, \"posTag\": \"NOUN\"}, {\"end\": 23.529, \"word\": \"so\", \"score\": 0.794, \"start\": 23.329, \"posTag\": \"SCONJ\"}, {\"end\": 23.969, \"word\": \"it\", \"score\": 1.0, \"start\": 23.909, \"posTag\": \"PRON\"}, {\"end\": 24.229, \"word\": \"should\", \"score\": 0.806, \"start\": 24.029, \"posTag\": \"AUX\"}, {\"end\": 24.369, \"word\": \"be\", \"score\": 0.786, \"start\": 24.269, \"posTag\": \"AUX\"}, {\"end\": 24.469, \"word\": \"in\", \"score\": 0.826, \"start\": 24.389, \"posTag\": \"ADP\"}, {\"end\": 24.949, \"word\": \"perfect\", \"score\": 0.815, \"start\": 24.549, \"posTag\": \"ADJ\"}, {\"end\": 25.329, \"word\": \"working\", \"score\": 0.895, \"start\": 25.009, \"posTag\": \"NOUN\"}, {\"end\": 25.669, \"word\": \"order.\", \"score\": 0.903, \"start\": 25.429, \"posTag\": \"NOUN\"}]', '[\"purchased\", \"refrigerator\", \"month\", \"order\"]', '', 'wiː dʒʌst pɜːtʃɪst ðæt ɹᵻfɹɪdʒɚɹeɪɾɚ læst mʌnθ soʊ ɪt ʃʊd biː ɪn pɜːfɛkt wɜːkɪŋ ɔːɹdɚ', '[\"Các nhân viên kinh doanh rất đánh giá cao buổi đào tạo do chúng ta dẫn dắt.\", \"Chậm khoảng 20 phút.\", \"Kavi làm rất tốt việc giải thích các khái niệm rất kỹ thuật theo cách mà ai cũng có thể hiểu được.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 15 trong bài luyện nghe Part 3.\", \"display_text\": \"We just purchased that refrigerator last month, so it should be in perfect working order.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s16', 'set-2026-t8-p3', 16, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/35-37.mp3', NULL, NULL, 26.51e0, 27.23e0, 'Oh, I see.', '[{\"end\": 26.63, \"word\": \"Oh,\", \"score\": 0.79, \"start\": 26.51, \"posTag\": \"INTJ\"}, {\"end\": 26.77, \"word\": \"I\", \"score\": 0.538, \"start\": 26.69, \"posTag\": \"PRON\"}, {\"end\": 27.23, \"word\": \"see.\", \"score\": 0.915, \"start\": 26.89, \"posTag\": \"VERB\"}]', '[\"see\"]', '', 'oʊ aɪ siː', '[\"Có tin vui đây.\", \"Tôi là Carmen Fuentes, đại diện kinh doanh tại công ty LT Plastic Injectors.\", \"Khoảng ba năm trước.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 16 trong bài luyện nghe Part 3.\", \"display_text\": \"Oh, I see.\"}', '2026-09-15 07:20:00'),
