('set-2026-t8-p3-s18', 'set-2026-t8-p3', 18, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/35-37.mp3', NULL, NULL, 29.71e0, 32.31e0, 'Would you like me to check the temperature every few hours?', '[{\"end\": 29.85, \"word\": \"Would\", \"score\": 0.854, \"start\": 29.71, \"posTag\": \"AUX\"}, {\"end\": 29.97, \"word\": \"you\", \"score\": 0.983, \"start\": 29.89, \"posTag\": \"PRON\"}, {\"end\": 30.17, \"word\": \"like\", \"score\": 0.997, \"start\": 30.01, \"posTag\": \"VERB\"}, {\"end\": 30.31, \"word\": \"me\", \"score\": 0.828, \"start\": 30.21, \"posTag\": \"PRON\"}, {\"end\": 30.43, \"word\": \"to\", \"score\": 0.883, \"start\": 30.35, \"posTag\": \"PART\"}, {\"end\": 30.73, \"word\": \"check\", \"score\": 0.796, \"start\": 30.49, \"posTag\": \"VERB\"}, {\"end\": 30.83, \"word\": \"the\", \"score\": 0.83, \"start\": 30.75, \"posTag\": \"DET\"}, {\"end\": 31.39, \"word\": \"temperature\", \"score\": 0.818, \"start\": 30.87, \"posTag\": \"NOUN\"}, {\"end\": 31.67, \"word\": \"every\", \"score\": 0.736, \"start\": 31.47, \"posTag\": \"DET\"}, {\"end\": 31.89, \"word\": \"few\", \"score\": 0.888, \"start\": 31.71, \"posTag\": \"ADJ\"}, {\"end\": 32.31, \"word\": \"hours?\", \"score\": 0.842, \"start\": 31.93, \"posTag\": \"NOUN\"}]', '[\"like\", \"temperature\", \"hours\"]', '', 'wʊd juː laɪk miː tə tʃɛk ðə tɛmpɹɪtʃɚɹ ɛvɹi fjuː aʊɚz', '[\"Họ thích những gợi ý mà các bạn đã đưa ra cho đến nay, chẳng hạn như cách cập nhật logo để trông hiện đại hơn.\", \"Gửi xe ở khu vực giao hàng chính lên tới 15 đô la một giờ cơ á?\", \"Nó nằm ở vị trí rất thuận tiện.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 18 trong bài luyện nghe Part 3.\", \"display_text\": \"Would you like me to check the temperature every few hours?\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s19', 'set-2026-t8-p3', 19, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/35-37.mp3', NULL, NULL, 32.791e0, 33.391e0, 'That\'s okay.', '[{\"end\": 32.971, \"word\": \"That\'s\", \"score\": 0.848, \"start\": 32.791, \"posTag\": \"PRON\"}, {\"end\": 33.391, \"word\": \"okay.\", \"score\": 0.803, \"start\": 33.051, \"posTag\": \"ADJ\"}]', '[\"okay\"]', '', 'ðæts oʊkeɪ', '[\"Công ty giặt khô của Azuma cách đây bao xa?\", \"Cô ấy đang đứng cạnh một thùng rác.\", \"Một người phụ nữ đang rót đồ uống vào cốc.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 19 trong bài luyện nghe Part 3.\", \"display_text\": \"That\'s okay.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s20', 'set-2026-t8-p3', 20, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/35-37.mp3', NULL, NULL, 33.731e0, 36.371e0, 'I can monitor it from home with my smartphone.', '[{\"end\": 33.791, \"word\": \"I\", \"score\": 0.814, \"start\": 33.731, \"posTag\": \"PRON\"}, {\"end\": 33.991, \"word\": \"can\", \"score\": 0.989, \"start\": 33.831, \"posTag\": \"AUX\"}, {\"end\": 34.551, \"word\": \"monitor\", \"score\": 0.847, \"start\": 34.071, \"posTag\": \"VERB\"}, {\"end\": 34.691, \"word\": \"it\", \"score\": 0.742, \"start\": 34.611, \"posTag\": \"PRON\"}, {\"end\": 34.971, \"word\": \"from\", \"score\": 0.863, \"start\": 34.791, \"posTag\": \"ADP\"}, {\"end\": 35.371, \"word\": \"home\", \"score\": 0.888, \"start\": 35.071, \"posTag\": \"ADV\"}, {\"end\": 35.551, \"word\": \"with\", \"score\": 0.756, \"start\": 35.411, \"posTag\": \"ADP\"}, {\"end\": 35.751, \"word\": \"my\", \"score\": 0.894, \"start\": 35.591, \"posTag\": \"PRON\"}, {\"end\": 36.371, \"word\": \"smartphone.\", \"score\": 0.728, \"start\": 35.771, \"posTag\": \"NOUN\"}]', '[\"monitor\", \"home\", \"smartphone\"]', '', 'aɪ kæn mɑːnɪɾɚɹ ɪt fɹʌm hoʊm wɪð maɪ smɑːɹtfoʊn', '[\"Món đặc biệt trong ngày là súp và bánh mì kẹp.\", \"Một số túi mua sắm đã được đặt trên sân ga tàu.\", \"1.000 chiếc để chính xác hơn.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 20 trong bài luyện nghe Part 3.\", \"display_text\": \"I can monitor it from home with my smartphone.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s21', 'set-2026-t8-p3', 21, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/35-37.mp3', NULL, NULL, 36.751e0, 37.471e0, 'Thanks anyway.', '[{\"end\": 37.011, \"word\": \"Thanks\", \"score\": 0.849, \"start\": 36.751, \"posTag\": \"NOUN\"}, {\"end\": 37.471, \"word\": \"anyway.\", \"score\": 0.896, \"start\": 37.071, \"posTag\": \"ADV\"}]', '[\"Thanks\"]', '', 'θæŋks ɛnɪweɪ', '[\"Tôi thích làm việc nhóm hơn.\", \"Tôi đã đỗ xe cạnh cái cây.\", \"Tuần trước, một khách hàng đã gọi để phàn nàn rằng đồ ăn của họ đã nguội lúc họ tìm thấy.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 21 trong bài luyện nghe Part 3.\", \"display_text\": \"Thanks anyway.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s22', 'set-2026-t8-p3', 22, 3, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/38-40.mp3', NULL, NULL, 5.553e0, 6.814e0, 'Hiroki, good news.', '[{\"end\": 6.094, \"word\": \"Hiroki,\", \"score\": 0.865, \"start\": 5.553, \"posTag\": \"PROPN\"}, {\"end\": 6.354, \"word\": \"good\", \"score\": 0.99, \"start\": 6.174, \"posTag\": \"ADJ\"}, {\"end\": 6.814, \"word\": \"news.\", \"score\": 0.855, \"start\": 6.414, \"posTag\": \"NOUN\"}]', '[\"Hiroki\", \"news\"]', '', 'hɪɹoʊki ɡʊd nuːz', '[\"Với tư cách là giám đốc kinh doanh khu vực, tôi muốn nghiên cứu việc áp dụng một hệ thống thanh toán hiện đại hơn tại các cửa hàng mỹ phẩm của chúng ta.\", \"Một số người đang lục lọi bàn làm việc.\", \"Hừm, tôi hiểu rồi.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 22 trong bài luyện nghe Part 3.\", \"display_text\": \"Hiroki, good news.\"}', '2026-09-15 07:20:00'),
