('set-2026-t8-p3-s41', 'set-2026-t8-p3', 41, 4, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/41-43.mp3', NULL, NULL, 26.198e0, 29.16e0, 'We should use those to create a 3D model of the building.', '[{\"end\": 26.318, \"word\": \"We\", \"score\": 0.817, \"start\": 26.198, \"posTag\": \"PRON\"}, {\"end\": 26.538, \"word\": \"should\", \"score\": 0.867, \"start\": 26.358, \"posTag\": \"AUX\"}, {\"end\": 26.799, \"word\": \"use\", \"score\": 0.77, \"start\": 26.659, \"posTag\": \"VERB\"}, {\"end\": 27.079, \"word\": \"those\", \"score\": 0.798, \"start\": 26.839, \"posTag\": \"PRON\"}, {\"end\": 27.239, \"word\": \"to\", \"score\": 0.874, \"start\": 27.139, \"posTag\": \"PART\"}, {\"end\": 27.619, \"word\": \"create\", \"score\": 0.831, \"start\": 27.299, \"posTag\": \"VERB\"}, {\"end\": 27.679, \"word\": \"a\", \"score\": 1.0, \"start\": 27.659, \"posTag\": \"DET\"}, {\"end\": 28.16, \"word\": \"3D\", \"score\": 0.678, \"start\": 27.719, \"posTag\": \"ADJ\"}, {\"end\": 28.56, \"word\": \"model\", \"score\": 0.743, \"start\": 28.2, \"posTag\": \"NOUN\"}, {\"end\": 28.66, \"word\": \"of\", \"score\": 0.75, \"start\": 28.6, \"posTag\": \"ADP\"}, {\"end\": 28.78, \"word\": \"the\", \"score\": 0.838, \"start\": 28.7, \"posTag\": \"DET\"}, {\"end\": 29.16, \"word\": \"building.\", \"score\": 0.807, \"start\": 28.82, \"posTag\": \"NOUN\"}]', '[\"create\", \"model\", \"building\"]', '', 'wiː ʃʊd juːz ðoʊz tə kɹiːeɪt ɐ θɹiː diː mɑːdəl ʌvðə bɪldɪŋ', '[\"Bạn đã kiểm tra lò nướng chưa?\", \"Chào Shinji.\", \"Tôi e là vậy.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 41 trong bài luyện nghe Part 3.\", \"display_text\": \"We should use those to create a 3D model of the building.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s42', 'set-2026-t8-p3', 42, 4, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/41-43.mp3', NULL, NULL, 29.521e0, 30.221e0, 'You\'re right.', '[{\"end\": 29.761, \"word\": \"You\'re\", \"score\": 0.787, \"start\": 29.521, \"posTag\": \"PRON\"}, {\"end\": 30.221, \"word\": \"right.\", \"score\": 0.742, \"start\": 29.841, \"posTag\": \"ADJ\"}]', '[\"right\"]', '', 'jʊɹ ɹaɪt', '[\"Hội nghị sẽ có một khu triển lãm gồm các nhà cung cấp phục vụ các chuỗi khách sạn, điều này có thể rất hữu ích vì năm tới chúng ta sẽ khai trương các khách sạn ở hai thành phố mới.\", \"Tuy nhiên, những mẫu in hình động vật mà bạn đã gửi...\", \"Tôi đã xem bộ phim đó rồi.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 42 trong bài luyện nghe Part 3.\", \"display_text\": \"You\'re right.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s43', 'set-2026-t8-p3', 43, 4, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/41-43.mp3', NULL, NULL, 30.642e0, 32.383e0, 'Then we can bring that to the meeting.', '[{\"end\": 30.802, \"word\": \"Then\", \"score\": 0.917, \"start\": 30.642, \"posTag\": \"ADV\"}, {\"end\": 30.962, \"word\": \"we\", \"score\": 0.875, \"start\": 30.842, \"posTag\": \"PRON\"}, {\"end\": 31.182, \"word\": \"can\", \"score\": 0.856, \"start\": 31.022, \"posTag\": \"AUX\"}, {\"end\": 31.462, \"word\": \"bring\", \"score\": 0.624, \"start\": 31.222, \"posTag\": \"VERB\"}, {\"end\": 31.682, \"word\": \"that\", \"score\": 0.852, \"start\": 31.502, \"posTag\": \"PRON\"}, {\"end\": 31.842, \"word\": \"to\", \"score\": 0.669, \"start\": 31.722, \"posTag\": \"ADP\"}, {\"end\": 31.963, \"word\": \"the\", \"score\": 0.678, \"start\": 31.862, \"posTag\": \"DET\"}, {\"end\": 32.383, \"word\": \"meeting.\", \"score\": 0.87, \"start\": 32.003, \"posTag\": \"NOUN\"}]', '[\"bring\", \"meeting\"]', '', 'ðɛn wiː kæn bɹɪŋ ðæt tə ðə miːɾɪŋ', '[\"Chúng tôi cần người chọn địa điểm quay phim phù hợp tại các nhà máy của Five Star, và quảng cáo nói rằng cô có rất nhiều kinh nghiệm tìm kiếm địa điểm công nghiệp.\", \"Nhiều cửa hàng của chúng ta có thể hưởng lợi từ việc này, nhưng tôi đã quyết định chạy thử nghiệm tại cửa hàng của chúng ta ở Trung tâm thương mại Center City.\", \"Và tại sao chúng ta lại có áo phông trong mục chi phí vậy?\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 43 trong bài luyện nghe Part 3.\", \"display_text\": \"Then we can bring that to the meeting.\"}', '2026-09-15 07:20:00'),
('set-2026-t8-p3-s44', 'set-2026-t8-p3', 44, 5, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/44-46.mp3', NULL, NULL, 4.935e0, 6.476e0, 'Hi.', '[{\"end\": 6.476, \"word\": \"Hi.\", \"score\": 0.645, \"start\": 4.935, \"posTag\": \"INTJ\"}]', '[]', '', 'haɪ', '[\"Tôi muốn trực tiếp xin lỗi vì những vấn đề nhà hàng của cô gặp phải khi sử dụng ô che sân ngoài trời của chúng tôi.\", \"Phiên bản đầu tiên là một thiết kế hiện đại với màu sắc đậm và chữ cái đơn giản.\", \"À, họ nghĩ đã đến lúc chúng ta cập nhật thương hiệu với các kiểu dáng hoặc màu sắc mới.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 44 trong bài luyện nghe Part 3.\", \"display_text\": \"Hi.\"}', '2026-09-15 07:20:00'),
