('set-2026-t8-p3-s103', 'set-2026-t8-p3', 103, 10, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/59-61.mp3', NULL, NULL, 11.628e0, 13.268e0, 'I think it\'s the hydraulic system.', '[{\"end\": 11.708, \"word\": \"I\", \"score\": 0.748, \"start\": 11.628, \"posTag\": \"PRON\"}, {\"end\": 11.968, \"word\": \"think\", \"score\": 0.894, \"start\": 11.788, \"posTag\": \"VERB\"}, {\"end\": 12.148, \"word\": \"it\'s\", \"score\": 0.795, \"start\": 12.028, \"posTag\": \"PRON\"}, {\"end\": 12.268, \"word\": \"the\", \"score\": 0.947, \"start\": 12.188, \"posTag\": \"DET\"}, {\"end\": 12.848, \"word\": \"hydraulic\", \"score\": 0.973, \"start\": 12.308, \"posTag\": \"ADJ\"}, {\"end\": 13.268, \"word\": \"system.\", \"score\": 0.933, \"start\": 12.888, \"posTag\": \"NOUN\"}]', '[\"think\", \"system\"]', '', 'aɪ θɪŋk ɪts ðə haɪdɹɔːlɪk sɪstəm', '[\"Bởi vì trời đang mưa.\", \"Chiếc áo khoác đó không đắt lắm.\", \"Chúng tôi nhận thu gom tất cả đồ điện tử.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 103 trong bài luyện nghe Part 3.\", \"display_text\": \"I think it\'s the hydraulic system.\"}', '2026-09-15 07:20:01'),
('set-2026-t8-p3-s104', 'set-2026-t8-p3', 104, 10, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/59-61.mp3', NULL, NULL, 14.008e0, 16.749e0, 'I cleaned the pump, but it\'s not running any better.', '[{\"end\": 14.089, \"word\": \"I\", \"score\": 0.745, \"start\": 14.008, \"posTag\": \"PRON\"}, {\"end\": 14.409, \"word\": \"cleaned\", \"score\": 0.587, \"start\": 14.129, \"posTag\": \"VERB\"}, {\"end\": 14.529, \"word\": \"the\", \"score\": 0.877, \"start\": 14.449, \"posTag\": \"DET\"}, {\"end\": 14.909, \"word\": \"pump,\", \"score\": 0.878, \"start\": 14.589, \"posTag\": \"NOUN\"}, {\"end\": 15.369, \"word\": \"but\", \"score\": 0.82, \"start\": 15.209, \"posTag\": \"CCONJ\"}, {\"end\": 15.569, \"word\": \"it\'s\", \"score\": 0.876, \"start\": 15.409, \"posTag\": \"PRON\"}, {\"end\": 15.809, \"word\": \"not\", \"score\": 0.671, \"start\": 15.649, \"posTag\": \"PART\"}, {\"end\": 16.149, \"word\": \"running\", \"score\": 0.944, \"start\": 15.889, \"posTag\": \"VERB\"}, {\"end\": 16.369, \"word\": \"any\", \"score\": 0.72, \"start\": 16.209, \"posTag\": \"ADV\"}, {\"end\": 16.749, \"word\": \"better.\", \"score\": 0.953, \"start\": 16.429, \"posTag\": \"ADV\"}]', '[\"cleaned\", \"pump\", \"running\"]', '', 'aɪ kliːnd ðə pʌmp bʌt ɪts nɑːt ɹʌnɪŋ ɛni bɛɾɚ', '[\"Cần phải thay thế một linh kiện, nhưng việc đó phải đến cuối tuần này mới thực hiện được.\", \"Tôi rất hào hứng về điều đó.\", \"Cô Gao, tôi là Hector và đây là đồng nghiệp của tôi, Sergei.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 104 trong bài luyện nghe Part 3.\", \"display_text\": \"I cleaned the pump, but it\'s not running any better.\"}', '2026-09-15 07:20:01'),
('set-2026-t8-p3-s105', 'set-2026-t8-p3', 105, 10, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/59-61.mp3', NULL, NULL, 17.289e0, 19.57e0, 'I\'ve done this before and it usually fixes it.', '[{\"end\": 17.429, \"word\": \"I\'ve\", \"score\": 0.918, \"start\": 17.289, \"posTag\": \"PRON\"}, {\"end\": 17.629, \"word\": \"done\", \"score\": 0.784, \"start\": 17.469, \"posTag\": \"VERB\"}, {\"end\": 17.809, \"word\": \"this\", \"score\": 0.638, \"start\": 17.649, \"posTag\": \"PRON\"}, {\"end\": 18.25, \"word\": \"before\", \"score\": 0.833, \"start\": 17.869, \"posTag\": \"ADV\"}, {\"end\": 18.47, \"word\": \"and\", \"score\": 0.694, \"start\": 18.37, \"posTag\": \"CCONJ\"}, {\"end\": 18.57, \"word\": \"it\", \"score\": 0.75, \"start\": 18.51, \"posTag\": \"PRON\"}, {\"end\": 19.03, \"word\": \"usually\", \"score\": 0.761, \"start\": 18.75, \"posTag\": \"ADV\"}, {\"end\": 19.49, \"word\": \"fixes\", \"score\": 0.788, \"start\": 19.13, \"posTag\": \"VERB\"}, {\"end\": 19.57, \"word\": \"it.\", \"score\": 0.289, \"start\": 19.51, \"posTag\": \"PRON\"}]', '[\"done\", \"before\", \"fixes\"]', '', 'aɪv dʌn ðɪs bᵻfɔːɹ ænd ɪt juːʒuːəli fɪksᵻz ɪt', '[\"Vé được bán trong tuần này hay tuần sau thế?\", \"Chúng tôi có sẵn một số nhiệt kế điện tử.\", \"Thực tế, bạn sẽ là một trong những cư dân đầu tiên nếu quyết định chuyển đến đây.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 105 trong bài luyện nghe Part 3.\", \"display_text\": \"I\'ve done this before and it usually fixes it.\"}', '2026-09-15 07:20:01'),
('set-2026-t8-p3-s106', 'set-2026-t8-p3', 106, 10, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/59-61.mp3', NULL, NULL, 20.449e0, 21.19e0, 'I see.', '[{\"end\": 20.569, \"word\": \"I\", \"score\": 0.827, \"start\": 20.449, \"posTag\": \"PRON\"}, {\"end\": 21.19, \"word\": \"see.\", \"score\": 0.918, \"start\": 20.83, \"posTag\": \"VERB\"}]', '[\"see\"]', '', 'aɪ siː', '[\"Công việc của chúng tôi hôm nay đã xong, nhưng chúng tôi cần biết phải tiến hành thế nào trước ngày mai.\", \"Hãy nhớ rằng, có một quầy nước giải khát nằm giữa Tòa thị chính và Bảo tàng Nghệ thuật, để bạn có thể cung cấp đủ nước khi xem đua xe.\", \"Tôi vừa mới mua chiếc màn hình này.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 106 trong bài luyện nghe Part 3.\", \"display_text\": \"I see.\"}', '2026-09-15 07:20:01'),
('set-2026-t8-p3-s107', 'set-2026-t8-p3', 107, 10, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/59-61.mp3', NULL, NULL, 21.71e0, 24.853e0, 'Maybe it\'s a problem with a piston in the hydraulic cylinder.', '[{\"end\": 21.95, \"word\": \"Maybe\", \"score\": 0.971, \"start\": 21.71, \"posTag\": \"ADV\"}, {\"end\": 22.11, \"word\": \"it\'s\", \"score\": 0.852, \"start\": 22.01, \"posTag\": \"PRON\"}, {\"end\": 22.211, \"word\": \"a\", \"score\": 0.619, \"start\": 22.171, \"posTag\": \"DET\"}, {\"end\": 22.691, \"word\": \"problem\", \"score\": 0.874, \"start\": 22.251, \"posTag\": \"NOUN\"}, {\"end\": 22.851, \"word\": \"with\", \"score\": 0.888, \"start\": 22.711, \"posTag\": \"ADP\"}, {\"end\": 22.931, \"word\": \"a\", \"score\": 0.943, \"start\": 22.911, \"posTag\": \"DET\"}, {\"end\": 23.452, \"word\": \"piston\", \"score\": 0.945, \"start\": 23.011, \"posTag\": \"NOUN\"}, {\"end\": 23.592, \"word\": \"in\", \"score\": 0.531, \"start\": 23.512, \"posTag\": \"ADP\"}, {\"end\": 23.672, \"word\": \"the\", \"score\": 0.964, \"start\": 23.612, \"posTag\": \"DET\"}, {\"end\": 24.272, \"word\": \"hydraulic\", \"score\": 0.897, \"start\": 23.712, \"posTag\": \"PROPN\"}, {\"end\": 24.853, \"word\": \"cylinder.\", \"score\": 0.891, \"start\": 24.332, \"posTag\": \"NOUN\"}]', '[\"Maybe\", \"problem\", \"piston\", \"hydraulic\"]', '', 'meɪbiː ɪts ɐ pɹɑːbləm wɪð ɐ pɪstən ɪnðə haɪdɹɔːlɪk sɪlɪndɚ', '[\"Cuộc họp có thể đợi đến ngày mai.\", \"Một chiếc ba lô đã được đặt trên mặt đất.\", \"Cảm ơn bạn đã giữ máy.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 107 trong bài luyện nghe Part 3.\", \"display_text\": \"Maybe it\'s a problem with a piston in the hydraulic cylinder.\"}', '2026-09-15 07:20:01'),
('set-2026-t8-p3-s108', 'set-2026-t8-p3', 108, 10, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/59-61.mp3', NULL, NULL, 25.333e0, 27.635e0, 'But a repair that big should be under warranty.', '[{\"end\": 25.453, \"word\": \"But\", \"score\": 0.926, \"start\": 25.333, \"posTag\": \"CCONJ\"}, {\"end\": 25.553, \"word\": \"a\", \"score\": 0.823, \"start\": 25.513, \"posTag\": \"DET\"}, {\"end\": 25.933, \"word\": \"repair\", \"score\": 0.92, \"start\": 25.613, \"posTag\": \"NOUN\"}, {\"end\": 26.134, \"word\": \"that\", \"score\": 0.924, \"start\": 25.973, \"posTag\": \"SCONJ\"}, {\"end\": 26.414, \"word\": \"big\", \"score\": 0.941, \"start\": 26.194, \"posTag\": \"ADJ\"}, {\"end\": 26.614, \"word\": \"should\", \"score\": 0.819, \"start\": 26.434, \"posTag\": \"AUX\"}, {\"end\": 26.714, \"word\": \"be\", \"score\": 0.992, \"start\": 26.634, \"posTag\": \"AUX\"}, {\"end\": 26.974, \"word\": \"under\", \"score\": 0.896, \"start\": 26.774, \"posTag\": \"ADP\"}, {\"end\": 27.635, \"word\": \"warranty.\", \"score\": 0.908, \"start\": 27.014, \"posTag\": \"NOUN\"}]', '[\"repair\", \"big\", \"warranty\"]', '', 'bʌt ɐ ɹᵻpɛɹ ðæt bɪɡ ʃʊd biː ʌndɚ wɔːɹənti', '[\"Thời gian đó có được không?\", \"Khách hàng đang đợi để vào một cửa hàng quần áo.\", \"Một chiếc lò sưởi điện.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 108 trong bài luyện nghe Part 3.\", \"display_text\": \"But a repair that big should be under warranty.\"}', '2026-09-15 07:20:01'),
('set-2026-t8-p3-s109', 'set-2026-t8-p3', 109, 10, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/59-61.mp3', NULL, NULL, 28.355e0, 30.657e0, 'It was Hamdi Equipment that sold it to us.', '[{\"end\": 28.415, \"word\": \"It\", \"score\": 0.982, \"start\": 28.355, \"posTag\": \"PRON\"}, {\"end\": 28.635, \"word\": \"was\", \"score\": 0.828, \"start\": 28.475, \"posTag\": \"AUX\"}, {\"end\": 29.176, \"word\": \"Hamdi\", \"score\": 0.927, \"start\": 28.695, \"posTag\": \"PROPN\"}, {\"end\": 29.696, \"word\": \"Equipment\", \"score\": 0.899, \"start\": 29.236, \"posTag\": \"PROPN\"}, {\"end\": 29.896, \"word\": \"that\", \"score\": 0.935, \"start\": 29.736, \"posTag\": \"PRON\"}, {\"end\": 30.197, \"word\": \"sold\", \"score\": 0.778, \"start\": 29.956, \"posTag\": \"VERB\"}, {\"end\": 30.297, \"word\": \"it\", \"score\": 0.999, \"start\": 30.257, \"posTag\": \"PRON\"}, {\"end\": 30.457, \"word\": \"to\", \"score\": 0.751, \"start\": 30.337, \"posTag\": \"ADP\"}, {\"end\": 30.657, \"word\": \"us.\", \"score\": 0.849, \"start\": 30.557, \"posTag\": \"PRON\"}]', '[\"Hamdi\", \"sold\"]', '', 'ɪt wʌz hæmdi ɪkwɪpmənt ðæt soʊld ɪt tʊ ʌs', '[\"Tại sao việc cải tạo vẫn chưa hoàn tất?\", \"Tôi biết các tệp đó nằm ở đâu trên ổ đĩa máy tính chung của chúng ta.\", \"Được rồi, thưa ông Jabreen, đây là thẻ thư viện mới của ông.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 109 trong bài luyện nghe Part 3.\", \"display_text\": \"It was Hamdi Equipment that sold it to us.\"}', '2026-09-15 07:20:01'),
('set-2026-t8-p3-s110', 'set-2026-t8-p3', 110, 10, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/59-61.mp3', NULL, NULL, 31.337e0, 31.958e0, 'Good point.', '[{\"end\": 31.538, \"word\": \"Good\", \"score\": 0.98, \"start\": 31.337, \"posTag\": \"ADJ\"}, {\"end\": 31.958, \"word\": \"point.\", \"score\": 0.801, \"start\": 31.618, \"posTag\": \"NOUN\"}]', '[\"point\"]', '', 'ɡʊd pɔɪnt', '[\"Tối nay chúng ta sẽ đưa khách hàng đi xem kịch.\", \"Tôi muốn lắp thêm lưới chống côn trùng cho các cửa sổ ở nhà.\", \"Chúng ta có thể làm vậy, nhưng tôi không biết liệu năm nay mình có được phép dùng tình nguyện viên không.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 110 trong bài luyện nghe Part 3.\", \"display_text\": \"Good point.\"}', '2026-09-15 07:20:01')
