('set-2026-t8-p3-s125', 'set-2026-t8-p3', 125, 11, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/62-64.mp3', NULL, NULL, 26.943e0, 29.404e0, 'It looks like I billed you for the wrong tire.', '[{\"end\": 27.023, \"word\": \"It\", \"score\": 0.833, \"start\": 26.943, \"posTag\": \"PRON\"}, {\"end\": 27.383, \"word\": \"looks\", \"score\": 0.864, \"start\": 27.163, \"posTag\": \"VERB\"}, {\"end\": 27.603, \"word\": \"like\", \"score\": 0.956, \"start\": 27.443, \"posTag\": \"SCONJ\"}, {\"end\": 27.823, \"word\": \"I\", \"score\": 0.801, \"start\": 27.723, \"posTag\": \"PRON\"}, {\"end\": 28.103, \"word\": \"billed\", \"score\": 0.632, \"start\": 27.863, \"posTag\": \"VERB\"}, {\"end\": 28.243, \"word\": \"you\", \"score\": 0.895, \"start\": 28.123, \"posTag\": \"PRON\"}, {\"end\": 28.423, \"word\": \"for\", \"score\": 0.842, \"start\": 28.283, \"posTag\": \"ADP\"}, {\"end\": 28.523, \"word\": \"the\", \"score\": 0.866, \"start\": 28.443, \"posTag\": \"DET\"}, {\"end\": 28.903, \"word\": \"wrong\", \"score\": 0.831, \"start\": 28.583, \"posTag\": \"ADJ\"}, {\"end\": 29.404, \"word\": \"tire.\", \"score\": 0.835, \"start\": 28.963, \"posTag\": \"NOUN\"}]', '[\"looks\", \"tire\"]', '', 'ɪt lʊks laɪk aɪ bɪld juː fɚðə ɹɔŋ taɪɚ', '[\"Tất cả nhân viên bắt buộc phải tham gia buổi đào tạo về cách sử dụng nó.\", \"Bạn có thể bảo Kelly gửi cho tôi sơ yếu lý lịch của cô ấy không?\", \"Có chứ, nhưng bạn phải bấm vào trang Giới thiệu và cuộn xuống tận cùng của trang đó.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 125 trong bài luyện nghe Part 3.\", \"display_text\": \"It looks like I billed you for the wrong tire.\"}', '2026-09-15 07:20:01'),
('set-2026-t8-p3-s126', 'set-2026-t8-p3', 126, 11, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/62-64.mp3', NULL, NULL, 29.944e0, 30.624e0, 'Apologies.', '[{\"end\": 30.624, \"word\": \"Apologies.\", \"score\": 0.879, \"start\": 29.944, \"posTag\": \"NOUN\"}]', '[\"Apologies\"]', '', 'ɐpɑːlədʒiz', '[\"Khoảng một tháng.\", \"Bạn muốn cất những cuốn tài liệu quảng cáo thừa ở đâu?\", \"Sau khi Cơ quan Giao thông công bố bản thảo kế hoạch cải thiện của chúng ta vào tuần trước, các phóng viên đã hỏi liệu chúng ta có đang cân nhắc lắp đặt động cơ tiết kiệm nhiên liệu hơn cho các đoàn tàu của mình hay không.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 126 trong bài luyện nghe Part 3.\", \"display_text\": \"Apologies.\"}', '2026-09-15 07:20:01'),
('set-2026-t8-p3-s127', 'set-2026-t8-p3', 127, 11, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/62-64.mp3', NULL, NULL, 30.884e0, 31.744e0, 'Let me fix that.', '[{\"end\": 31.044, \"word\": \"Let\", \"score\": 0.894, \"start\": 30.884, \"posTag\": \"VERB\"}, {\"end\": 31.184, \"word\": \"me\", \"score\": 0.826, \"start\": 31.084, \"posTag\": \"PRON\"}, {\"end\": 31.484, \"word\": \"fix\", \"score\": 0.946, \"start\": 31.244, \"posTag\": \"VERB\"}, {\"end\": 31.744, \"word\": \"that.\", \"score\": 0.891, \"start\": 31.524, \"posTag\": \"PRON\"}]', '[\"fix\"]', '', 'lɛt miː fɪks ðæt', '[\"Họ mời tôi đến buổi khai mạc phải không?\", \"Hội nghị sẽ có một khu triển lãm gồm các nhà cung cấp phục vụ các chuỗi khách sạn, điều này có thể rất hữu ích vì năm tới chúng ta sẽ khai trương các khách sạn ở hai thành phố mới.\", \"Cảm ơn vì đã gặp chúng tôi, cô Azuma.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 127 trong bài luyện nghe Part 3.\", \"display_text\": \"Let me fix that.\"}', '2026-09-15 07:20:01'),
