('set-2026-t8-p4-s4', 'set-2026-t8-p4', 4, 1, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/71-73.mp3', NULL, NULL, 19.321e0, 24.665e0, 'He wants to buy two UAVs, or Underwater Autonomous Vehicles.', '[{\"end\": 19.441, \"word\": \"He\", \"score\": 0.782, \"start\": 19.321, \"posTag\": \"PRON\"}, {\"end\": 19.782, \"word\": \"wants\", \"score\": 0.738, \"start\": 19.501, \"posTag\": \"VERB\"}, {\"end\": 19.922, \"word\": \"to\", \"score\": 0.848, \"start\": 19.842, \"posTag\": \"PART\"}, {\"end\": 20.162, \"word\": \"buy\", \"score\": 0.874, \"start\": 19.982, \"posTag\": \"VERB\"}, {\"end\": 20.642, \"word\": \"two\", \"score\": 0.895, \"start\": 20.302, \"posTag\": \"NUM\"}, {\"end\": 21.803, \"word\": \"UAVs,\", \"score\": 0.786, \"start\": 20.942, \"posTag\": \"NOUN\"}, {\"end\": 22.403, \"word\": \"or\", \"score\": 0.578, \"start\": 22.263, \"posTag\": \"CCONJ\"}, {\"end\": 23.304, \"word\": \"Underwater\", \"score\": 0.849, \"start\": 22.663, \"posTag\": \"PROPN\"}, {\"end\": 24.084, \"word\": \"Autonomous\", \"score\": 0.846, \"start\": 23.484, \"posTag\": \"PROPN\"}, {\"end\": 24.665, \"word\": \"Vehicles.\", \"score\": 0.688, \"start\": 24.144, \"posTag\": \"PROPN\"}]', '[\"buy\", \"UAVs\", \"Underwater\"]', '', 'hiː wɔnts tə baɪ tuː juːeɪviːz ɔːɹ ʌndɚwɔːɾɚɹ ɔːtɑːnəməs viəkəlz', '[\"Và chúng có thể phân hủy sinh học nữa.\", \"Cảm ơn các bạn đã làm việc chăm chỉ để đảm bảo chúng diễn ra suôn sẻ.\", \"Tôi sẽ liên hệ với khách hàng về việc giao hàng bị chậm trễ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 4 trong bài luyện nghe Part 4.\", \"display_text\": \"He wants to buy two UAVs, or Underwater Autonomous Vehicles.\"}', '2026-09-15 07:20:01'),
('set-2026-t8-p4-s5', 'set-2026-t8-p4', 5, 1, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/71-73.mp3', NULL, NULL, 25.265e0, 31.95e0, 'These remotely operated vehicles can be used to inspect, maintain, and repair equipment underwater.', '[{\"end\": 25.505, \"word\": \"These\", \"score\": 0.752, \"start\": 25.265, \"posTag\": \"DET\"}, {\"end\": 26.066, \"word\": \"remotely\", \"score\": 0.846, \"start\": 25.625, \"posTag\": \"ADV\"}, {\"end\": 26.646, \"word\": \"operated\", \"score\": 0.894, \"start\": 26.166, \"posTag\": \"VERB\"}, {\"end\": 27.186, \"word\": \"vehicles\", \"score\": 0.657, \"start\": 26.706, \"posTag\": \"NOUN\"}, {\"end\": 27.427, \"word\": \"can\", \"score\": 0.994, \"start\": 27.266, \"posTag\": \"AUX\"}, {\"end\": 27.567, \"word\": \"be\", \"score\": 0.785, \"start\": 27.467, \"posTag\": \"AUX\"}, {\"end\": 28.007, \"word\": \"used\", \"score\": 0.769, \"start\": 27.747, \"posTag\": \"VERB\"}, {\"end\": 28.347, \"word\": \"to\", \"score\": 0.698, \"start\": 28.207, \"posTag\": \"PART\"}, {\"end\": 28.948, \"word\": \"inspect,\", \"score\": 0.894, \"start\": 28.427, \"posTag\": \"VERB\"}, {\"end\": 29.768, \"word\": \"maintain,\", \"score\": 0.772, \"start\": 29.128, \"posTag\": \"VERB\"}, {\"end\": 30.088, \"word\": \"and\", \"score\": 0.725, \"start\": 29.968, \"posTag\": \"CCONJ\"}, {\"end\": 30.649, \"word\": \"repair\", \"score\": 0.761, \"start\": 30.168, \"posTag\": \"NOUN\"}, {\"end\": 31.269, \"word\": \"equipment\", \"score\": 0.841, \"start\": 30.769, \"posTag\": \"NOUN\"}, {\"end\": 31.95, \"word\": \"underwater.\", \"score\": 0.896, \"start\": 31.369, \"posTag\": \"NOUN\"}]', '[\"vehicles\", \"used\", \"repair\", \"underwater\"]', '', 'ðiːz ɹᵻmoʊtli ɑːpɚɹeɪɾᵻd viəkəlz kæn biː juːzd tʊ ɪnspɛkt meɪnteɪn ænd ɹᵻpɛɹ ɪkwɪpmənt ʌndɚwɔːɾɚ', '[\"Cảm ơn vì đã cho tôi cơ hội phát biểu tại cuộc họp Hội đồng Thành phố này.\", \"Tôi sẽ bận ở lễ khánh thành ga tàu mới.\", \"Một số lá cờ được treo từ các ban công.\"]',