('set-2026-t8-p4-s55', 'set-2026-t8-p4', 55, 9, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/95-97.mp3', NULL, NULL, 7.194e0, 13.496e0, 'The time is right for Snowville Refrigeration to begin marketing our commercial refrigerators internationally.', '[{\"end\": 7.314, \"word\": \"The\", \"score\": 0.72, \"start\": 7.194, \"posTag\": \"DET\"}, {\"end\": 7.574, \"word\": \"time\", \"score\": 0.98, \"start\": 7.354, \"posTag\": \"NOUN\"}, {\"end\": 7.714, \"word\": \"is\", \"score\": 0.708, \"start\": 7.634, \"posTag\": \"AUX\"}, {\"end\": 8.014, \"word\": \"right\", \"score\": 0.854, \"start\": 7.794, \"posTag\": \"ADJ\"}, {\"end\": 8.174, \"word\": \"for\", \"score\": 0.996, \"start\": 8.054, \"posTag\": \"SCONJ\"}, {\"end\": 8.734, \"word\": \"Snowville\", \"score\": 0.884, \"start\": 8.234, \"posTag\": \"PROPN\"}, {\"end\": 9.575, \"word\": \"Refrigeration\", \"score\": 0.858, \"start\": 8.774, \"posTag\": \"PROPN\"}, {\"end\": 10.015, \"word\": \"to\", \"score\": 0.701, \"start\": 9.915, \"posTag\": \"PART\"}, {\"end\": 10.355, \"word\": \"begin\", \"score\": 0.847, \"start\": 10.055, \"posTag\": \"VERB\"}, {\"end\": 10.915, \"word\": \"marketing\", \"score\": 0.824, \"start\": 10.435, \"posTag\": \"VERB\"}, {\"end\": 11.135, \"word\": \"our\", \"score\": 0.964, \"start\": 11.055, \"posTag\": \"PRON\"}, {\"end\": 11.655, \"word\": \"commercial\", \"score\": 0.895, \"start\": 11.195, \"posTag\": \"ADJ\"}, {\"end\": 12.476, \"word\": \"refrigerators\", \"score\": 0.884, \"start\": 11.695, \"posTag\": \"NOUN\"}, {\"end\": 13.496, \"word\": \"internationally.\", \"score\": 0.863, \"start\": 12.676, \"posTag\": \"ADV\"}]', '[\"Snowville\", \"marketing\", \"refrigerators\"]', '', 'ðə taɪm ɪz ɹaɪt fɔːɹ snoʊvɪl ɹᵻfɹɪdʒɚɹeɪʃən tə bɪɡɪn mɑːɹkɪɾɪŋ aʊɚ kəmɜːʃəl ɹᵻfɹɪdʒɚɹeɪɾɚz ɪntɚnæʃənəli', '[\"Sao anh lại gọi cho khách hàng?\", \"Công ty được chọn nhận giải thưởng năm nay từng rất nản lòng vì thiếu ứng viên có đủ năng lực và đã quyết định hành động để giải quyết vấn đề đó.\", \"Ban quản lý Reston đã xác nhận danh sách khách thuê của tòa nhà và chúng tôi đã phỏng vấn Giám đốc điều hành của Barnum Financial Services về văn phòng mới của họ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 55 trong bài luyện nghe Part 4.\", \"display_text\": \"The time is right for Snowville Refrigeration to begin marketing our commercial refrigerators internationally.\"}', '2026-09-15 07:20:02'),
('set-2026-t8-p4-s56', 'set-2026-t8-p4', 56, 9, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%208/audio/95-97.mp3', NULL, NULL, 14.096e0, 20.439e0, 'Due to supply chain problems, many companies that manufacture refrigerators are low on inventory.', '[{\"end\": 14.356, \"word\": \"Due\", \"score\": 0.854, \"start\": 14.096, \"posTag\": \"ADP\"}, {\"end\": 14.517, \"word\": \"to\", \"score\": 0.77, \"start\": 14.417, \"posTag\": \"PART\"}, {\"end\": 15.017, \"word\": \"supply\", \"score\": 0.834, \"start\": 14.577, \"posTag\": \"VERB\"}, {\"end\": 15.337, \"word\": \"chain\", \"score\": 0.874, \"start\": 15.077, \"posTag\": \"NOUN\"}, {\"end\": 15.817, \"word\": \"problems,\", \"score\": 0.937, \"start\": 15.377, \"posTag\": \"NOUN\"}, {\"end\": 16.497, \"word\": \"many\", \"score\": 0.778, \"start\": 16.237, \"posTag\": \"ADJ\"}, {\"end\": 16.977, \"word\": \"companies\", \"score\": 0.867, \"start\": 16.557, \"posTag\": \"NOUN\"}, {\"end\": 17.158, \"word\": \"that\", \"score\": 0.822, \"start\": 17.017, \"posTag\": \"PRON\"}, {\"end\": 18.078, \"word\": \"manufacture\", \"score\": 0.85, \"start\": 17.238, \"posTag\": \"VERB\"}, {\"end\": 18.958, \"word\": \"refrigerators\", \"score\": 0.889, \"start\": 18.158, \"posTag\": \"NOUN\"}, {\"end\": 19.238, \"word\": \"are\", \"score\": 0.964, \"start\": 19.158, \"posTag\": \"AUX\"}, {\"end\": 19.578, \"word\": \"low\", \"score\": 0.834, \"start\": 19.318, \"posTag\": \"ADJ\"}, {\"end\": 19.739, \"word\": \"on\", \"score\": 0.944, \"start\": 19.659, \"posTag\": \"ADP\"}, {\"end\": 20.439, \"word\": \"inventory.\", \"score\": 0.921, \"start\": 19.859, \"posTag\": \"NOUN\"}]', '[\"problems\", \"refrigerators\", \"inventory\"]', '', 'duː tə səplaɪ tʃeɪn pɹɑːbləmz mɛni kʌmpəniz ðæt mænjuːfæktʃɚ ɹᵻfɹɪdʒɚɹeɪɾɚz ɑːɹ loʊ ɔn ɪnvəntɔːɹi', '[\"Đúng vậy, và họ thường đi lại mà báo trước rất gấp.\", \"Bài viết của tôi đã sẵn sàng để đăng tải.\", \"Tuyệt vời.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xá