('set-2026-t9-p2-s17', 'set-2026-t9-p2', 17, 5, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/11.mp3', NULL, NULL, 2.452e0, 4.793e0, 'When will the dishwasher prototype be ready?', '[{\"end\": 2.652, \"word\": \"When\", \"score\": 0.87, \"start\": 2.452, \"posTag\": \"SCONJ\"}, {\"end\": 2.892, \"word\": \"will\", \"score\": 0.736, \"start\": 2.672, \"posTag\": \"AUX\"}, {\"end\": 2.992, \"word\": \"the\", \"score\": 0.833, \"start\": 2.912, \"posTag\": \"DET\"}, {\"end\": 3.652, \"word\": \"dishwasher\", \"score\": 0.85, \"start\": 3.032, \"posTag\": \"NOUN\"}, {\"end\": 4.273, \"word\": \"prototype\", \"score\": 0.934, \"start\": 3.693, \"posTag\": \"NOUN\"}, {\"end\": 4.413, \"word\": \"be\", \"score\": 0.818, \"start\": 4.313, \"posTag\": \"AUX\"}, {\"end\": 4.793, \"word\": \"ready?\", \"score\": 0.881, \"start\": 4.493, \"posTag\": \"ADJ\"}]', '[\"prototype\"]', '', 'wɛn wɪl ðə dɪʃwɑːʃɚ pɹoʊɾoʊtaɪp biː ɹɛdi', '[\"Và thảm hiện tại của chúng tôi có màu sáng.\", \"Tôi gọi về đơn hàng in phiếu giảm giá của chúng tôi.\", \"Tôi vừa xem qua doanh số tuần này và nhận thấy có rất nhiều người gọi món bò hầm đặc biệt.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 17 trong bài luyện nghe Part 2.\", \"display_text\": \"When will the dishwasher prototype be ready?\"}', '2026-09-15 07:20:02'),
('set-2026-t9-p2-s18', 'set-2026-t9-p2', 18, 5, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/11.mp3', NULL, NULL, 6.934e0, 8.114e0, 'On Treetown Avenue.', '[{\"end\": 7.034, \"word\": \"On\", \"score\": 0.601, \"start\": 6.934, \"posTag\": \"ADP\"}, {\"end\": 7.654, \"word\": \"Treetown\", \"score\": 0.868, \"start\": 7.114, \"posTag\": \"PROPN\"}, {\"end\": 8.114, \"word\": \"Avenue.\", \"score\": 0.836, \"start\": 7.754, \"posTag\": \"PROPN\"}]', '[\"Treetown\"]', '', 'ɔn tɹiːtaʊn ævənuː', '[\"Cảm ơn bạn đã làm việc đó.\", \"Vâng, đó là một cuộc gọi hội nghị.\", \"Tôi đã đỗ xe cạnh cái cây.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 18 trong bài luyện nghe Part 2.\", \"display_text\": \"On Treetown Avenue.\"}', '2026-09-15 07:20:02')
