('set-2026-t9-p2-s64', 'set-2026-t9-p2', 64, 16, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/22.mp3', NULL, NULL, 10.061e0, 11.782e0, 'From the florist, down the street.', '[{\"end\": 10.221, \"word\": \"From\", \"score\": 0.639, \"start\": 10.061, \"posTag\": \"ADP\"}, {\"end\": 10.361, \"word\": \"the\", \"score\": 0.833, \"start\": 10.281, \"posTag\": \"DET\"}, {\"end\": 10.881, \"word\": \"florist,\", \"score\": 0.87, \"start\": 10.401, \"posTag\": \"NOUN\"}, {\"end\": 11.262, \"word\": \"down\", \"score\": 0.836, \"start\": 11.041, \"posTag\": \"ADP\"}, {\"end\": 11.382, \"word\": \"the\", \"score\": 0.999, \"start\": 11.322, \"posTag\": \"DET\"}, {\"end\": 11.782, \"word\": \"street.\", \"score\": 0.876, \"start\": 11.442, \"posTag\": \"NOUN\"}]', '[\"florist\", \"street\"]', '', 'fɹʌmðə flɔːɹɪst daʊn ðə stɹiːt', '[\"Trong bản tin địa phương, tòa nhà văn phòng Reston ở trung tâm thành phố đã hoàn thành.\", \"Được rồi, để tôi kiểm tra lại kho lưu trữ.\", \"Bạn có sẵn sàng khớp mức giá của họ không?\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 64 trong bài luyện nghe Part 2.\", \"display_text\": \"From the florist, down the street.\"}', '2026-09-15 07:20:02'),
('set-2026-t9-p2-s65', 'set-2026-t9-p2', 65, 16, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/22.mp3', NULL, NULL, 12.703e0, 15.746e0, 'Let\'s discuss that at our next meeting.', '[{\"end\": 14.004, \"word\": \"Let\'s\", \"score\": 0.845, \"start\": 13.764, \"posTag\": \"PROPN\"}, {\"end\": 14.445, \"word\": \"discuss\", \"score\": 0.937, \"start\": 14.064, \"posTag\": \"VERB\"}, {\"end\": 14.685, \"word\": \"that\", \"score\": 0.796, \"start\": 14.485, \"posTag\": \"SCONJ\"}, {\"end\": 14.885, \"word\": \"at\", \"score\": 0.876, \"start\": 14.825, \"posTag\": \"ADP\"}, {\"end\": 15.045, \"word\": \"our\", \"score\": 0.778, \"start\": 14.945, \"posTag\": \"PRON\"}, {\"end\": 15.326, \"word\": \"next\", \"score\": 0.828, \"start\": 15.105, \"posTag\": \"ADJ\"}, {\"end\": 15.746, \"word\": \"meeting.\", \"score\": 0.958, \"start\": 15.426, \"posTag\": \"NOUN\"}]', '[\"Let\'s\", \"meeting\"]', '', 'siː lɛts dɪskʌs ðæt æɾ aʊɚ nɛkst miːɾɪŋ', '[\"Một người đi xe đạp đang chạy ngang qua một người đi bộ.\", \"Anh ấy đang dọn tuyết trên lối đi.\", \"Nhân viên văn phòng của chúng tôi.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 65 trong bài luyện nghe Part 2.\", \"display_text\": \"Let\'s discuss that at our next meeting.\"}', '2026-09-15 07:20:02'),
('set-2026-t9-p2-s66', 'set-2026-t9-p2', 66, 17, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/23.mp3', NULL, NULL, 0.852e0, 4.997e0, 'Why was the seminar agenda changed?', '[{\"end\": 1.633, \"word\": \"Why\", \"score\": 0.399, \"start\": 0.852, \"posTag\": \"SCONJ\"}, {\"end\": 3.175, \"word\": \"was\", \"score\": 0.882, \"start\": 2.995, \"posTag\": \"AUX\"}, {\"end\": 3.315, \"word\": \"the\", \"score\": 0.97, \"start\": 3.215, \"posTag\": \"DET\"}, {\"end\": 3.876, \"word\": \"seminar\", \"score\": 0.871, \"start\": 3.355, \"posTag\": \"NOUN\"}, {\"end\": 4.417, \"word\": \"agenda\", \"score\": 0.802, \"start\": 3.956, \"posTag\": \"NOUN\"}, {\"end\": 4.997, \"word\": \"changed?\", \"score\": 0.874, \"start\": 4.477, \"posTag\": \"VERB\"}]', '[\"seminar\"]', '', 'waɪ wʌzðə sɛmɪnɑːɹ ɐdʒɛndə tʃeɪndʒd', '[\"Có rất nhiều thông tin cần phải đưa vào.\", \"Không, chọn ngày nào cũng được.\", \"Anh ấy đang gập máy tính xách tay lại.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 66 trong bài luyện nghe Part 2.\", \"display_text\": \"Why was the seminar agenda changed?\"}', '2026-09-15 07:20:03'),
