('set-2026-t9-p2-s69', 'set-2026-t9-p2', 69, 17, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/23.mp3', NULL, NULL, 13.628e0, 15.651e0, 'That\'s a good idea.', '[{\"end\": 14.87, \"word\": \"That\'s\", \"score\": 0.878, \"start\": 14.57, \"posTag\": \"PRON\"}, {\"end\": 15.03, \"word\": \"a\", \"score\": 0.68, \"start\": 14.97, \"posTag\": \"DET\"}, {\"end\": 15.23, \"word\": \"good\", \"score\": 0.938, \"start\": 15.07, \"posTag\": \"ADJ\"}, {\"end\": 15.651, \"word\": \"idea.\", \"score\": 0.941, \"start\": 15.311, \"posTag\": \"NOUN\"}]', '[\"idea\"]', '', 'siː ðæts ɐ ɡʊd aɪdiə', '[\"Một người đàn ông đang cầm điện thoại lên.\", \"Chúng ta vừa nhận được một đơn hàng gấp từ Great Fitness.\", \"Tôi chưa thấy họ dùng bao giờ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 69 trong bài luyện nghe Part 2.\", \"display_text\": \"That\'s a good idea.\"}', '2026-09-15 07:20:03'),
('set-2026-t9-p2-s70', 'set-2026-t9-p2', 70, 18, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/24.mp3', NULL, NULL, 0.432e0, 5.879e0, 'Are you taking the bus or a taxi to the client\'s office?', '[{\"end\": 2.775, \"word\": \"Are\", \"score\": 0.839, \"start\": 2.675, \"posTag\": \"AUX\"}, {\"end\": 2.915, \"word\": \"you\", \"score\": 0.837, \"start\": 2.795, \"posTag\": \"PRON\"}, {\"end\": 3.295, \"word\": \"taking\", \"score\": 0.831, \"start\": 2.955, \"posTag\": \"VERB\"}, {\"end\": 3.436, \"word\": \"the\", \"score\": 0.833, \"start\": 3.335, \"posTag\": \"DET\"}, {\"end\": 3.816, \"word\": \"bus\", \"score\": 0.849, \"start\": 3.476, \"posTag\": \"NOUN\"}, {\"end\": 4.076, \"word\": \"or\", \"score\": 0.624, \"start\": 3.956, \"posTag\": \"CCONJ\"}, {\"end\": 4.136, \"word\": \"a\", \"score\": 0.999, \"start\": 4.116, \"posTag\": \"DET\"}, {\"end\": 4.697, \"word\": \"taxi\", \"score\": 0.956, \"start\": 4.197, \"posTag\": \"NOUN\"}, {\"end\": 4.857, \"word\": \"to\", \"score\": 0.833, \"start\": 4.757, \"posTag\": \"ADP\"}, {\"end\": 4.958, \"word\": \"the\", \"score\": 0.832, \"start\": 4.877, \"posTag\": \"DET\"}, {\"end\": 5.418, \"word\": \"client\'s\", \"score\": 0.891, \"start\": 4.998, \"posTag\": \"NOUN\"}, {\"end\": 5.879, \"word\": \"office?\", \"score\": 0.98, \"start\": 5.498, \"posTag\": \"NOUN\"}]', '[\"bus\", \"taxi\", \"client\'s\"]', '', 'nʌmbɚ twɛnti fɔːɹ ɑːɹ juː teɪkɪŋ ðə bʌs ɔːɹ ɐ tæksi tə ðə klaɪənts ɑːfɪs', '[\"Chào mừng đếnกับ cuộc họp nhân viên hàng tháng của công ty.\", \"Xin chào Minji, tôi là Anil Gupta từ Nhà hàng Gia đình của Jeremy gọi về đơn xin việc bạn đã gửi.\", \"Xin chào, tôi muốn mua một ít thảm trải sàn mới.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 70 trong bài luyện nghe Part 2.\", \"display_text\": \"Are you taking the bus or a taxi to the client\'s office?\"}', '2026-09-15 07:20:03'),
('set-2026-t9-p2-s71', 'set-2026-t9-p2', 71, 18, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/24.mp3', NULL, NULL, 7.942e0, 9.123e0, 'To pick up some coffee.', '[{\"end\": 8.062, \"word\": \"To\", \"score\": 0.868, \"start\": 7.942, \"posTag\": \"PART\"}, {\"end\": 8.282, \"word\": \"pick\", \"score\": 0.849, \"start\": 8.102, \"posTag\": \"VERB\"}, {\"end\": 8.422, \"word\": \"up\", \"score\": 0.82, \"start\": 8.342, \"posTag\": \"ADP\"}, {\"end\": 8.622, \"word\": \"some\", \"score\": 0.759, \"start\": 8.462, \"posTag\": \"DET\"}, {\"end\": 9.123, \"word\": \"coffee.\", \"score\": 0.964, \"start\": 8.683, \"posTag\": \"NOUN\"}]', '[\"coffee\"]', '', 'tə pɪk ʌp sʌm kɔfi', '[\"Sau khi Cơ quan Giao thông công bố bản thảo kế hoạch cải thiện của chúng ta vào tuần trước, các phóng viên đã hỏi liệu chúng ta có đang cân nhắc lắp đặt động cơ tiết kiệm nhiên liệu hơn cho các đoàn tàu của mình hay không.\", \"Chào buổi sáng các nhân viên Bảo tàng Sinh hoạt Glenman House.\", \"Trên bàn làm việc của bạn kìa.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 71 trong bài luyện nghe Part 2.\", \"display_text\": \"To pick up some coffee.\"}', '2026-09-15 07:20:03'),
('set-2026-t9-p2-s72', 'set-2026-t9-p2', 72, 18, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/24.mp3', NULL, NULL, 10.004e0, 12.347e0, 'I brought my car today.', '[{\"end\": 11.286, \"word\": \"I\", \"score\": 0.936, \"start\": 11.186, \"posTag\": \"PRON\"}, {\"end\": 11.526, \"word\": \"brought\", \"score\": 0.858, \"start\": 11.306, \"posTag\": \"VERB\"}, {\"end\": 11.687, \"word\": \"my\", \"score\": 0.838, \"start\": 11.566, \"posTag\": \"PRON\"}, {\"end\": 12.007, \"word\": \"car\", \"score\": 0.883, \"start\": 11.747, \"posTag\": \"NOUN\"}, {\"end\": 12.347, \"word\": \"today.\", \"score\": 0.832, \"start\": 12.047, \"posTag\": \"NOUN\"}]', '[\"today\"]', '', 'biː aɪ bɹɔːt maɪ kɑːɹ tədeɪ', '[\"Ồ.\", \"Thật không may, điều này đã gây ra một số vấn đề về độ lệch khung.\", \"Chào anh, tôi vừa gọi điện xong với ban quản lý.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 72 trong bài luyện nghe Part 2.\", \"display_text\": \"I brought my car today.\"}', '2026-09-15 07:20:03'),
