('set-2026-t9-p3-s8', 'set-2026-t9-p3', 8, 1, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/32-34.mp3', NULL, NULL, 28.2e0, 30.361e0, 'First, I\'ll need to set you up in our system.', '[{\"end\": 28.58, \"word\": \"First,\", \"score\": 0.862, \"start\": 28.2, \"posTag\": \"ADV\"}, {\"end\": 28.88, \"word\": \"I\'ll\", \"score\": 0.78, \"start\": 28.72, \"posTag\": \"PRON\"}, {\"end\": 29.08, \"word\": \"need\", \"score\": 0.915, \"start\": 28.9, \"posTag\": \"VERB\"}, {\"end\": 29.18, \"word\": \"to\", \"score\": 0.504, \"start\": 29.1, \"posTag\": \"PART\"}, {\"end\": 29.381, \"word\": \"set\", \"score\": 0.847, \"start\": 29.22, \"posTag\": \"VERB\"}, {\"end\": 29.501, \"word\": \"you\", \"score\": 0.993, \"start\": 29.401, \"posTag\": \"PRON\"}, {\"end\": 29.641, \"word\": \"up\", \"score\": 0.974, \"start\": 29.561, \"posTag\": \"ADP\"}, {\"end\": 29.761, \"word\": \"in\", \"score\": 0.816, \"start\": 29.681, \"posTag\": \"ADP\"}, {\"end\": 29.901, \"word\": \"our\", \"score\": 0.812, \"start\": 29.801, \"posTag\": \"PRON\"}, {\"end\": 30.361, \"word\": \"system.\", \"score\": 0.918, \"start\": 29.941, \"posTag\": \"NOUN\"}]', '[\"need\", \"system\"]', '', 'fɜːst aɪl niːd tə sɛt juː ʌp ɪn aʊɚ sɪstəm', '[\"Có tin vui đây.\", \"Một trong những người phụ nữ đang mặc áo len.\", \"Hãy sử dụng ứng dụng di động Abingdon Transit để xem thông tin cập nhật trực tiếp về thời gian chuyến xe buýt tiếp theo đến.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 8 trong bài luyện nghe Part 3.\", \"display_text\": \"First, I\'ll need to set you up in our system.\"}', '2026-09-15 07:20:03'),
('set-2026-t9-p3-s9', 'set-2026-t9-p3', 9, 1, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/32-34.mp3', NULL, NULL, 31.001e0, 33.042e0, 'Can I have your name and email address?', '[{\"end\": 31.161, \"word\": \"Can\", \"score\": 0.97, \"start\": 31.001, \"posTag\": \"AUX\"}, {\"end\": 31.281, \"word\": \"I\", \"score\": 0.666, \"start\": 31.221, \"posTag\": \"PRON\"}, {\"end\": 31.482, \"word\": \"have\", \"score\": 0.875, \"start\": 31.341, \"posTag\": \"VERB\"}, {\"end\": 31.642, \"word\": \"your\", \"score\": 0.875, \"start\": 31.502, \"posTag\": \"PRON\"}, {\"end\": 31.962, \"word\": \"name\", \"score\": 0.671, \"start\": 31.702, \"posTag\": \"NOUN\"}, {\"end\": 32.242, \"word\": \"and\", \"score\": 0.879, \"start\": 32.122, \"posTag\": \"CCONJ\"}, {\"end\": 32.602, \"word\": \"email\", \"score\": 0.657, \"start\": 32.362, \"posTag\": \"NOUN\"}, {\"end\": 33.042, \"word\": \"address?\", \"score\": 0.899, \"start\": 32.642, \"posTag\": \"NOUN\"}]', '[\"address\"]', '', 'kæn aɪ hæv jʊɹ neɪm ænd iːmeɪl ɐdɹɛs', '[\"Tôi rất mong chờ bữa tiệc kỷ niệm của chúng ta, Shreya.\", \"Người phụ nữ đang cởi mũ.\", \"Tại công ty của chúng tôi, chúng tôi tự hào thực hiện mọi thứ nội bộ, từ thiết kế đồ họa đến sản xuất.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 9 trong bài luyện nghe Part 3.\", \"display_text\": \"Can I have your name and email address?\"}', '2026-09-15 07:20:03'),
('set-2026-t9-p3-s10', 'set-2026-t9-p3', 10, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/35-37.mp3', NULL, NULL, 6.176e0, 8.198e0, 'Welcome to Reynolds Ice Cream Factory.', '[{\"end\": 6.536, \"word\": \"Welcome\", \"score\": 0.801, \"start\": 6.176, \"posTag\": \"VERB\"}, {\"end\": 6.677, \"word\": \"to\", \"score\": 0.657, \"start\": 6.577, \"posTag\": \"ADP\"}, {\"end\": 7.137, \"word\": \"Reynolds\", \"score\": 0.672, \"start\": 6.717, \"posTag\": \"PROPN\"}, {\"end\": 7.377, \"word\": \"Ice\", \"score\": 0.957, \"start\": 7.257, \"posTag\": \"PROPN\"}, {\"end\": 7.637, \"word\": \"Cream\", \"score\": 0.9, \"start\": 7.417, \"posTag\": \"PROPN\"}, {\"end\": 8.198, \"word\": \"Factory.\", \"score\": 0.905, \"start\": 7.697, \"posTag\": \"PROPN\"}]', '[\"Reynolds\"]', '', 'wɛlkʌm tə ɹɛnəldz aɪs kɹiːm fæktɚɹi', '[\"Một đợt kiểm tra hàng tồn kho.\", \"Mức giá ước tính cho bảo hiểm ô tô này cao hơn chúng tôi mong đợi.\", \"Chúng ta không biết chính xác những giống cây nào đã được trồng vào thời đó.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 10 trong bài luyện nghe Part 3.\", \"display_text\": \"Welcome to Reynolds Ice Cream Factory.\"}', '2026-09-15 07:20:03'),
('set-2026-t9-p3-s11', 'set-2026-t9-p3', 11, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/35-37.mp3', NULL, NULL, 8.758e0, 11.761e0, 'I\'m so glad that you\'ll be joining our Quality Assurance team.', '[{\"end\": 8.918, \"word\": \"I\'m\", \"score\": 0.725, \"start\": 8.758, \"posTag\": \"PRON\"}, {\"end\": 9.259, \"word\": \"so\", \"score\": 0.87, \"start\": 9.059, \"posTag\": \"ADV\"}, {\"end\": 9.599, \"word\": \"glad\", \"score\": 0.788, \"start\": 9.319, \"posTag\": \"ADJ\"}, {\"end\": 9.759, \"word\": \"that\", \"score\": 0.999, \"start\": 9.659, \"posTag\": \"SCONJ\"}, {\"end\": 9.959, \"word\": \"you\'ll\", \"score\": 0.911, \"start\": 9.779, \"posTag\": \"PRON\"}, {\"end\": 10.059, \"word\": \"be\", \"score\": 0.826, \"start\": 9.979, \"posTag\": \"AUX\"}, {\"end\": 10.42, \"word\": \"joining\", \"score\": 0.89, \"start\": 10.099, \"posTag\": \"VERB\"}, {\"end\": 10.56, \"word\": \"our\", \"score\": 0.837, \"start\": 10.46, \"posTag\": \"PRON\"}, {\"end\": 10.98, \"word\": \"Quality\", \"score\": 0.842, \"start\": 10.6, \"posTag\": \"PROPN\"}, {\"end\": 11.461, \"word\": \"Assurance\", \"score\": 0.874, \"start\": 11.02, \"posTag\": \"PROPN\"}, {\"end\": 11.761, \"word\": \"team.\", \"score\": 0.558, \"start\": 11.501, \"posTag\": \"NOUN\"}]', '[\"joining\", \"Assurance\"]', '', 'aɪm soʊ ɡlæd ðæt juːl biː dʒɔɪnɪŋ aʊɚ kwɔlᵻɾi əʃʊɹɹəns tiːm', '[\"À, tôi nghĩ Pauline từng gặp một vấn đề tương tự với trò chơi mà cô ấy kiểm tra.\", \"May mắn thay, chúng ta có thể dùng lại sân khấu và trang thiết bị như những lần trước.\", \"Không, anh ấy uống cà phê.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 11 trong bài luyện nghe Part 3.\", \"display_text\": \"I\'m so glad that you\'ll be joining our Quality Assurance team.\"}', '2026-09-15 07:20:03'),
('set-2026-t9-p3-s12', 'set-2026-t9-p3', 12, 2, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/35-37.mp3', NULL, NULL, 12.421e0, 12.802e0, 'Thanks.', '[{\"end\": 12.802, \"word\": \"Thanks.\", \"score\": 0.916, \"start\": 12.421, \"posTag\": \"NOUN\"}]', '[\"Thanks\"]', '', 'θæŋks', '[\"Camille, cái bơm mới có về kịp hôm nay không?\", \"Trước khi chúng ta bắt đầu hôm nay, các bạn cần thiết lập tài khoản nhân viên của mình.\", \"Một đóng góp nhỏ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 12 trong bài luyện nghe Part 3.\", \"display_text\": \"Thanks.\"}', '2026-09-15 07:20:03'),
