('set-2026-t9-p3-s118', 'set-2026-t9-p3', 118, 12, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/65-67.mp3', NULL, NULL, 13.741e0, 17.083e0, 'The exhibit of Naro Miyazuma\'s drawings is very popular.', '[{\"end\": 13.881, \"word\": \"The\", \"score\": 0.667, \"start\": 13.741, \"posTag\": \"DET\"}, {\"end\": 14.341, \"word\": \"exhibit\", \"score\": 0.87, \"start\": 13.941, \"posTag\": \"NOUN\"}, {\"end\": 14.442, \"word\": \"of\", \"score\": 0.887, \"start\": 14.381, \"posTag\": \"ADP\"}, {\"end\": 14.782, \"word\": \"Naro\", \"score\": 0.909, \"start\": 14.522, \"posTag\": \"PROPN\"}, {\"end\": 15.482, \"word\": \"Miyazuma\'s\", \"score\": 0.843, \"start\": 14.822, \"posTag\": \"PROPN\"}, {\"end\": 15.943, \"word\": \"drawings\", \"score\": 0.907, \"start\": 15.522, \"posTag\": \"NOUN\"}, {\"end\": 16.123, \"word\": \"is\", \"score\": 0.794, \"start\": 16.023, \"posTag\": \"AUX\"}, {\"end\": 16.483, \"word\": \"very\", \"score\": 0.807, \"start\": 16.203, \"posTag\": \"ADV\"}, {\"end\": 17.083, \"word\": \"popular.\", \"score\": 0.94, \"start\": 16.583, \"posTag\": \"ADJ\"}]', '[\"exhibit\", \"drawings\"]', '', 'ðɪ ɛɡzɪbɪt ʌv næɹoʊ mɪjɐzuːməz dɹɔːɪŋz ɪz vɛɹi pɑːpjʊlɚ', '[\"Nghiên cứu người dùng có chiều sâu sẽ giúp chúng ta tạo ra ứng dụng ngân hàng trực tuyến tốt hơn.\", \"Như tôi đã đề cập qua điện thoại, tôi và đồng nghiệp gần đây đã thành lập một công ty thời trang và hy vọng công ty xây dựng thương hiệu của bạn có thể giúp chúng tôi quảng bá dòng trang phục thể thao của mình.\", \"Vâng, chúng tôi cung cấp ứng dụng Cloud Camel.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 118 trong bài luyện nghe Part 3.\", \"display_text\": \"The exhibit of Naro Miyazuma\'s drawings is very popular.\"}', '2026-09-15 07:20:04'),
('set-2026-t9-p3-s119', 'set-2026-t9-p3', 119, 12, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/65-67.mp3', NULL, NULL, 17.544e0, 20.126e0, 'The gift shop has sold out of a lot of the merchandise.', '[{\"end\": 17.644, \"word\": \"The\", \"score\": 0.842, \"start\": 17.544, \"posTag\": \"DET\"}, {\"end\": 17.904, \"word\": \"gift\", \"score\": 0.93, \"start\": 17.684, \"posTag\": \"NOUN\"}, {\"end\": 18.184, \"word\": \"shop\", \"score\": 0.68, \"start\": 17.944, \"posTag\": \"NOUN\"}, {\"end\": 18.344, \"word\": \"has\", \"score\": 0.914, \"start\": 18.204, \"posTag\": \"AUX\"}, {\"end\": 18.665, \"word\": \"sold\", \"score\": 0.714, \"start\": 18.384, \"posTag\": \"VERB\"}, {\"end\": 18.905, \"word\": \"out\", \"score\": 0.824, \"start\": 18.765, \"posTag\": \"ADP\"}, {\"end\": 19.005, \"word\": \"of\", \"score\": 0.748, \"start\": 18.945, \"posTag\": \"ADP\"}, {\"end\": 19.085, \"word\": \"a\", \"score\": 0.501, \"start\": 19.045, \"posTag\": \"DET\"}, {\"end\": 19.305, \"word\": \"lot\", \"score\": 0.868, \"start\": 19.125, \"posTag\": \"NOUN\"}, {\"end\": 19.405, \"word\": \"of\", \"score\": 0.75, \"start\": 19.345, \"posTag\": \"ADP\"}, {\"end\": 19.505, \"word\": \"the\", \"score\": 0.823, \"start\": 19.425, \"posTag\": \"DET\"}, {\"end\": 20.126, \"word\": \"merchandise.\", \"score\": 0.889, \"start\": 19.545, \"posTag\": \"NOUN\"}]', '[\"gift\", \"lot\", \"merchandise\"]', '', 'ðə ɡɪft ʃɑːp hɐz soʊld aʊɾəv ɐ lɑːt ʌvðə mɜːtʃɐndaɪz', '[\"Có lẽ chúng ta có thể bù đắp chi phí vé máy bay bằng cách tiết kiệm tiền khách sạn.\", \"Điều duy nhất tôi nghe được là tên của họ, Công ty Xây dựng CDQ.\", \"Vâng, tôi có đây.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 119 trong bài luyện nghe Part 3.\", \"display_text\": \"The gift shop has sold out of a lot of the merchandise.\"}', '2026-09-15 07:20:04'),
('set-2026-t9-p3-s120', 'set-2026-t9-p3', 120, 12, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/65-67.mp3', NULL, NULL, 20.486e0, 23.008e0, 'Do you want me to see if the display shirt is a small?', '[{\"end\": 20.606, \"word\": \"Do\", \"score\": 0.829, \"start\": 20.486, \"posTag\": \"AUX\"}, {\"end\": 20.746, \"word\": \"you\", \"score\": 0.79, \"start\": 20.646, \"posTag\": \"PRON\"}, {\"end\": 20.926, \"word\": \"want\", \"score\": 0.828, \"start\": 20.786, \"posTag\": \"VERB\"}, {\"end\": 21.046, \"word\": \"me\", \"score\": 0.796, \"start\": 20.966, \"posTag\": \"PRON\"}, {\"end\": 21.146, \"word\": \"to\", \"score\": 0.752, \"start\": 21.086, \"posTag\": \"PART\"}, {\"end\": 21.327, \"word\": \"see\", \"score\": 0.917, \"start\": 21.186, \"posTag\": \"VERB\"}, {\"end\": 21.447, \"word\": \"if\", \"score\": 0.832, \"start\": 21.367, \"posTag\": \"SCONJ\"}, {\"end\": 21.567, \"word\": \"the\", \"score\": 0.888, \"start\": 21.487, \"posTag\": \"DET\"}, {\"end\": 22.107, \"word\": \"display\", \"score\": 0.878, \"start\": 21.607, \"posTag\": \"NOUN\"}, {\"end\": 22.407, \"word\": \"shirt\", \"score\": 0.85, \"start\": 22.167, \"posTag\": \"NOUN\"}, {\"end\": 22.567, \"word\": \"is\", \"score\": 0.822, \"start\": 22.467, \"posTag\": \"AUX\"}, {\"end\": 22.648, \"word\": \"a\", \"score\": 0.739, \"start\": 22.608, \"posTag\": \"DET\"}, {\"end\": 23.008, \"word\": \"small?\", \"score\": 0.821, \"start\": 22.688, \"posTag\": \"ADJ\"}]', '[\"want\", \"see\", \"display\"]', '', 'duː juː wɔnt miː tə siː ɪf ðə dɪspleɪ ʃɜːt ɪz ɐ smɔːl', '[\"Tôi nghĩ ga tàu ở trên đại lộ Mulberry.\", \"Bạn có muốn một bản sao của bài báo mà tôi đã nhắc tới không?\", \"Tôi nghe nói bạn sắp làm việc cho công ty chúng ta ở chi nhánh New Zealand ở nước ngoài.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 120 trong bài luyện nghe Part 3.\", \"display_text\": \"Do you want me to see if the display shirt is a small?\"}', '2026-09-15 07