('set-2026-t9-p4-s25', 'set-2026-t9-p4', 25, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/86-88.mp3', NULL, NULL, 5.652e0, 8.493e0, 'One final thing before we close the team leaders meeting.', '[{\"end\": 5.772, \"word\": \"One\", \"score\": 0.75, \"start\": 5.652, \"posTag\": \"NUM\"}, {\"end\": 6.153, \"word\": \"final\", \"score\": 0.831, \"start\": 5.852, \"posTag\": \"ADJ\"}, {\"end\": 6.413, \"word\": \"thing\", \"score\": 0.738, \"start\": 6.193, \"posTag\": \"NOUN\"}, {\"end\": 6.773, \"word\": \"before\", \"score\": 0.752, \"start\": 6.473, \"posTag\": \"SCONJ\"}, {\"end\": 6.913, \"word\": \"we\", \"score\": 0.928, \"start\": 6.813, \"posTag\": \"PRON\"}, {\"end\": 7.293, \"word\": \"close\", \"score\": 0.893, \"start\": 6.953, \"posTag\": \"VERB\"}, {\"end\": 7.433, \"word\": \"the\", \"score\": 0.832, \"start\": 7.333, \"posTag\": \"DET\"}, {\"end\": 7.713, \"word\": \"team\", \"score\": 0.945, \"start\": 7.473, \"posTag\": \"NOUN\"}, {\"end\": 8.093, \"word\": \"leaders\", \"score\": 0.834, \"start\": 7.753, \"posTag\": \"NOUN\"}, {\"end\": 8.493, \"word\": \"meeting.\", \"score\": 0.9, \"start\": 8.133, \"posTag\": \"NOUN\"}]', '[\"thing\", \"meeting\"]', '', 'wʌn faɪnəl θɪŋ bᵻfɔːɹ wiː kloʊz ðə tiːm liːdɚz miːɾɪŋ', '[\"Gần đây tôi tình cờ đọc được cuốn sách ông viết về lịch sử thời trang Pháp và thấy nó vô cùng hấp dẫn.\", \"Chúng tôi đang làm một số video đào tạo cho khách hàng của mình, Five Star Industries.\", \"Tôi đọc được ở đâu đó rằng mọi người cũng có thể mượn các ấn phẩm kỹ thuật số.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 25 trong bài luyện nghe Part 4.\", \"display_text\": \"One final thing before we close the team leaders meeting.\"}', '2026-09-15 07:20:04'),
('set-2026-t9-p4-s26', 'set-2026-t9-p4', 26, 6, 'https://pub-fc656190823148858ee32a0f29384f75.r2.dev/2026/Test%209/audio/86-88.mp3', NULL, NULL, 9.133e0, 13.374e0, 'Some educators from various countries will be visiting our company next week.', '[{\"end\": 9.353, \"word\": \"Some\", \"score\": 0.823, \"start\": 9.133, \"posTag\": \"DET\"}, {\"end\": 10.074, \"word\": \"educators\", \"score\": 0.885, \"start\": 9.453, \"posTag\": \"NOUN\"}, {\"end\": 10.314, \"word\": \"from\", \"score\": 0.834, \"start\": 10.134, \"posTag\": \"ADP\"}, {\"end\": 10.794, \"word\": \"various\", \"score\": 0.878, \"start\": 10.374, \"posTag\": \"ADJ\"}, {\"end\": 11.334, \"word\": \"countries\", \"score\": 0.732, \"start\": 10.874, \"posTag\": \"NOUN\"}, {\"end\": 11.554, \"word\": \"will\", \"score\": 0.806, \"start\": 11.374, \"posTag\": \"AUX\"}, {\"end\": 11.674, \"word\": \"be\", \"score\": 0.572, \"start\": 11.574, \"posTag\": \"AUX\"}, {\"end\": 12.174, \"word\": \"visiting\", \"score\": 0.78, \"start\": 11.734, \"posTag\": \"VERB\"}, {\"end\": 12.354, \"word\": \"our\", \"score\": 0.873, \"start\": 12.254, \"posTag\": \"PRON\"}, {\"end\": 12.834, \"word\": \"company\", \"score\": 0.902, \"start\": 12.434, \"posTag\": \"NOUN\"}, {\"end\": 13.074, \"word\": \"next\", \"score\": 0.885, \"start\": 12.894, \"posTag\": \"ADJ\"}, {\"end\": 13.374, \"word\": \"week.\", \"score\": 0.758, \"start\": 13.154, \"posTag\": \"NOUN\"}]', '[\"educators\", \"countries\", \"visiting\"]', '', 'sʌm ɛdʒuːkeɪɾɚz fɹʌm vɛɹiəs kʌntɹiz wɪl biː vɪzɪɾɪŋ aʊɚ kʌmpəni nɛkst wiːk', '[\"Chào mừng các đại diện bán hàng mới đến với buổi tập huấn hôm nay về kỹ thuật gọi điện bán hàng cho khách hàng tiềm năng mà chưa biết về chúng ta.\", \"Và các mẫu giấy dán tường dành cho phòng trẻ em đều rất giàu trí tưởng tượng.\", \"Cách đây vài giờ.\"]', '{\"is_correct\": true, \"explanation\": \"Khớp chính xác với nội dung câu 26 trong bài luyện nghe Part 4.\", \"display_text\": \"Some educators from various countries will be visiting our company next week.\"}', '2026-09-15 07:20:04')
